DO $$
DECLARE
  v_lib_id_44 uuid;
BEGIN
  SELECT id INTO v_lib_id_44 FROM quizzes WHERE title = 'الحضارات القديمة: الرافدين والفراعنة' LIMIT 1;
  IF v_lib_id_44 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الحضارات القديمة: الرافدين والفراعنة', 'تاريخ', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_44;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي تحول تقني يفسر انتقال العلامات المسمارية المبكرة من رسوم قابلة للتعرف إلى هيئة إسفينية مجردة؟', '["استبدال الطين بالبردي والفرشاة","ضغط قلم قصبي ذي رأس مقطوع في الطين الرطب","نقش النص بعد حرق اللوح بإزميل حديدي","صب الحروف في قوالب برونزية"]'::jsonb, 1, 35, 0, 'multi', 'أدى ضغط الطرف المقطوع للقلم القصبي في الطين إلى علامات مؤلفة من طبعات إسفينية، ثم غلب هذا الأسلوب على الرسم الخطي الأقدم. لم تكن الكتابة المسمارية حروفًا مصبوبة، ولم ينشأ شكلها من الكتابة على البردي.', 'الرافدان: الكتابة والإدارة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الوظيفة الأساسية التي أدتها لوحة نارمر في فهم نشأة الدولة المصرية، بصرف النظر عن كون مشاهدها تسجيلًا حرفيًا لحدث واحد؟', '["توثيق بناء الهرم المدرج","تقديم صورة ملكية مبكرة لفرض النظام وربط الملك بالوجهين القبلي والبحري","شرح طقوس التحنيط في الدولة الحديثة","تسجيل أول معاهدة مع الحيثيين"]'::jsonb, 1, 35, 1, 'multi', 'تُظهر اللوحة نارمر بتاجي مصر وتوظف لغة بصرية عن إخضاع الخصوم وتثبيت النظام الملكي؛ لذلك تعد شاهدًا محوريًا على أيديولوجيا التوحيد وبدايات الدولة، لا نصًا إداريًا عن بناء الأهرام أو معاهدة متأخرة.', 'مصر: نشأة الدولة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'لماذا تُعد مسلة شريعة حمورابي مصدرًا قانونيًا وسياسيًا معًا؟', '["لأنها دستور منتخب يفصل السلطات الثلاث","لأنها سجل كامل لكل محاكمة بابلية","لأنها تجمع أحكامًا وصيغًا قضائية مع تصوير الملك متلقيًا الشرعية من الإله شمش","لأنها معاهدة حدودية بين بابل وآشور"]'::jsonb, 2, 35, 2, 'multi', 'يحمل النصب مقدمة وخاتمة ملكيتين ومجموعة أحكام، وفوقها مشهد حمورابي أمام شمش إله العدل. لذا يعرض ممارسة القانون ويعلن في الوقت نفسه عدالة الملك وشرعيته؛ وليس سجلًا شاملًا للقضايا ولا دستورًا حديثًا.', 'الرافدان: القانون والملكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي سمة تميز الزقورة في مدن الرافدين عن الهرم الملكي في مصر القديمة؟', '["كلاهما قبر ملكي مغلق الوظيفة نفسها","الزقورة منحوتة دائمًا من صخر طبيعي والهرم من الطين","الزقورة منصة معبد مدرجة ضمن مجمع ديني، أما الهرم فجزء من مجمع جنائزي ملكي","الزقورة مرصد فلكي حصري لا صلة له بالشعائر"]'::jsonb, 2, 35, 3, 'multi', 'كانت الزقورات كتلًا مدرجة من اللِبن ترفع معبدًا أو حرمًا داخل المركز الديني، ولم تكن قبورًا ملكية. أما الأهرامات المصرية فكانت قلب مجمعات جنائزية ملكية تشمل معابد وطرقًا صاعدة.', 'عمارة مقارنة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الذي جعل حجر رشيد حاسمًا في فك الكتابة الهيروغليفية؟', '["احتوى قاموسًا مصريًا يونانيًا مرتبًا أبجديًا","حمل نصًا واحدًا بصيغ هيروغليفية وديموطيقية ويونانية أمكن مقابلة أجزائه","كان أقدم نص هيروغليفي معروف","شرح كاهن مصري على هامشه نطق كل علامة"]'::jsonb, 1, 35, 4, 'multi', 'سجّل الحجر مرسومًا واحدًا بثلاثة أنظمة كتابية: الهيروغليفية والديموطيقية واليونانية. أتاحت معرفة اليونانية مقارنة الأسماء والمقاطع، مع الاستفادة من عمل باحثين سابقين، وصولًا إلى فهم الطبيعة الصوتية والدلالية للهيروغليفية.', 'مصر: الكتابة وفك الرموز');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'في النظام الإداري المصري، ماذا كان دور الوزير على نحو أدق؟', '["قائد معبد محلي بلا سلطة مدنية","ملك مشارك مستقل يحكم الدلتا دائمًا","كاتب مختص حصرًا بتسجيل فيضان النيل","أعلى مسؤول بعد الملك يشرف على القضاء والإدارة والموارد عبر جهاز الدولة"]'::jsonb, 3, 35, 5, 'multi', 'كان الوزير رأس الجهاز الإداري تحت الملك، وترتبط به أعمال القضاء والسجلات والضرائب والموارد والأشغال. تغيرت التفاصيل عبر العصور، بل وُجد وزيران أحيانًا، لكن المنصب لم يكن مجرد كاتب فيضان أو كاهن محلي.', 'مصر: الإدارة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي وصف يطابق وظيفة الأختام الأسطوانية في مجتمعات الرافدين؟', '["كانت نقودًا معيارية تُذاب عند الدفع","كانت أدوات فلكية لقياس الظلال","كانت تُدحرج على الطين فتترك مشهدًا متصلًا يثبت الهوية أو السلطة ويؤمّن الإغلاق","كانت ألواحًا مدرسية لتعليم الأبجدية فقط"]'::jsonb, 2, 35, 6, 'multi', 'يُدحرج الختم الأسطواني المنقوش على طين رطب فوق لوح أو سدادة باب أو وعاء، فيترك بصمة طويلة مرتبطة بصاحبه. أدى بذلك وظائف التوثيق والتفويض والحماية، وحمل أيضًا صورًا دينية واجتماعية.', 'الرافدان: الإدارة والفن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي ملك مصري ارتبط بالمجمع الجنائزي ذي الهرم المدرج في سقارة، المصمم تقليديًا باسم إمحوتب؟', '["سنوسرت الثالث","أحمس الأول","زوسر","رمسيس الثالث"]'::jsonb, 2, 30, 7, 'multi', 'بُني الهرم المدرج لزوسر من الأسرة الثالثة في الدولة القديمة، ويُنسب تصميم مجمعه إلى إمحوتب. سنوسرت الثالث من الدولة الوسطى، وأحمس الأول ورمسيس الثالث من الدولة الحديثة، فلا ينتمون إلى مرحلة العمارة الحجرية المبكرة نفسها.', 'مصر: الدولة القديمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الدليل الأقوى على أن مدينة أور في عصر سلالة أور الثالثة امتلكت إدارة شديدة التنظيم؟', '["غياب الكتابة خارج القصور","كثرة الألواح المسمارية الخاصة بالحصص والعمال والماشية والمعاملات","اقتصار المباني على مساكن متنقلة","عدم وجود مقاييس أو أوزان"]'::jsonb, 1, 35, 8, 'multi', 'خلّفت مؤسسات أور الثالثة أرشيفات ضخمة من السجلات الإدارية، تشمل حركة السلع وحصص العمال والقطعان والضرائب. تكشف هذه الوثائق البيروقراطية اليومية أكثر مما تكشفه النصوص الملكية الدعائية وحدها.', 'الرافدان: الاقتصاد والإدارة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الغرض الأوضح من مشاهد الحياة اليومية المنقوشة في مقابر النخبة المصرية؟', '["تسجيل يوميات العمال بحياد فوتوغرافي","إمداد المتوفى رمزيًا بنظام مثالي مستمر من الغذاء والعمل والطقوس في الآخرة","تعليم العامة القراءة داخل المقبرة","إثبات أن صاحب المقبرة مارس كل مهنة مصورة بنفسه"]'::jsonb, 1, 35, 9, 'multi', 'كانت صور الزراعة والصيد والصناعات والقرابين جزءًا فعالًا من تجهيز المقبرة، إذ تصوغ عالمًا وفيرًا ومنظمًا يستمر فيه المتوفى. وهي منتقاة وفق أعراف جنائزية وليست سجلًا محايدًا لكل تفاصيل المجتمع.', 'مصر: الدين والفن الجنائزي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'لماذا لا يصح وصف قائمة الملوك السومريين بأنها سجل زمني مباشر ودقيق لجميع الحكام؟', '["لأنها تمزج حكامًا تاريخيين بمدد حكم خارقة وتعيد ترتيب الماضي لخدمة فكرة انتقال الملكية","لأنها مكتوبة باليونانية بعد العصر الروماني","لأنها لا تذكر أي مدينة سومرية","لأنها قائمة ضرائب لا أسماء فيها"]'::jsonb, 0, 45, 10, 'multi', 'تجمع القائمة بين سلالات يمكن تثبيت بعض ملوكها تاريخيًا وحكام ما قبل الطوفان ذوي مدد هائلة، وتعرض الملكية كأنها انتقلت تباعًا بين المدن. لذلك تُقرأ بوصفها بناءً أدبيًا وسياسيًا إلى جانب قيمتها التاريخية المقارنة.', 'الرافدان: التأريخ والملكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي دليل ميّز اكتشاف مقبرة الملكة حتب حرس الأولى قرب الهرم الأكبر رغم أن تابوتها الحجري وُجد خاليًا؟', '["وجود بردية تصف معركة قادش","تمثال ضخم لأخناتون","أرشيف مسماري من ألواح الطين","مجموعة أثاث جنائزي ملكي وأوانٍ ونقالة تحمل اسمها أعيد تركيبها من مواد متدهورة"]'::jsonb, 3, 45, 11, 'multi', 'حفظت الحجرة المطمورة تجهيزات فاخرة مرتبطة بحتب حرس، ومنها أثاث مذهب ونقالة ومظلة وأوانٍ. تطلبت المواد العضوية المتحللة توثيقًا وإعادة بناء دقيقة، أما خلو التابوت فظل عنصرًا من لغز الدفن لا نفيًا لهوية صاحبة الأثاث.', 'مصر: الدولة القديمة والآثار');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي اقتران زمني وسياسي يصف سرجون الأكدي بدقة؟', '["وحّد مدنًا واسعة تحت حكم أكدي في أواخر الألف الثالث ق.م. وجعل أكد مركزًا لسلطته","أسس الدولة البابلية الحديثة بعد سقوط نينوى","حكم آشور في القرن السابع ق.م. وبنى مكتبة نينوى","كان ملكًا سومريًا من سلالة أور الثالثة بعد شولگي"]'::jsonb, 0, 45, 12, 'multi', 'أنشأ سرجون في القرن الرابع والعشرين ق.م. سلالة أكد وضم دول مدن سومر ومناطق واسعة إلى سلطة مركزية. تسبق دولته أور الثالثة وبابل القديمة وآشور الحديثة بقرون، لذلك لا يصح نقله إلى تلك السياقات.', 'الرافدان: الدولة الأكدية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الذي يميز إصلاح أخناتون الديني عن العبادة المصرية التقليدية قبل عهده؟', '["ألغى المعابد وكل الطقوس الجنائزية نهائيًا","استبدل اللغة المصرية بالأكدية في جميع النصوص","أعاد العاصمة إلى منف بعد غزو آشوري","رفع عبادة آتون ورعايته الملكية إلى مركز غير مسبوق، همّش معه كثيرًا من الآلهة ونقل البلاط إلى أخيتاتون"]'::jsonb, 3, 45, 13, 'multi', 'ركز أخناتون الشعائر الرسمية على آتون، غيّر اسمه، وبنى عاصمة جديدة في أخيتاتون، مع إجراءات ضد أسماء وصور آلهة ولا سيما آمون. لكن وصف المرحلة بإلغاء كل ممارسة دينية أو بمفهوم توحيد حديث كامل يتجاوز تعقيد الدليل.', 'مصر: الدولة الحديثة والعمارنة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'في رسائل العمارنة، لماذا استخدم البلاط المصري اللغة الأكدية والخط المسماري في جانب كبير من مراسلاته الخارجية؟', '["لأن الأكدية المسمارية أدت دور لغة دبلوماسية مشتركة بين بلاطات الشرق الأدنى في العصر البرونزي المتأخر","لأن الأكدية كانت لغة مصر اليومية","لأن الهيروغليفية لم تكن قد ظهرت","لأن الرسائل نُسخت كلها في العصر الآشوري الحديث"]'::jsonb, 0, 45, 14, 'multi', 'كانت الأكدية المكتوبة بالمسمارية أداة المراسلة الدولية بين مصر وملوك بابل وميتاني والحيثيين وحكام مدن الشام. وجودها في أخيتاتون لا يعني أنها حلت محل المصرية لغةً محلية، بل يعكس عرفًا دبلوماسيًا إقليميًا.', 'مصر والرافدان: الدبلوماسية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الاستنتاج الأدق من نصوص الأهرام في أواخر الأسرة الخامسة والسادسة؟', '["أن أقدم مجموعة كبيرة من التعاويذ الجنائزية الملكية نُقشت داخل الأهرام لضمان تحول الملك وبقائه في الآخرة","أن كل المصريين امتلكوا النصوص نفسها في منازلهم","أنها سجلات بناء يومية للعمال","أنها ترجمة مصرية لملحمة جلجامش"]'::jsonb, 0, 45, 15, 'multi', 'ظهرت نصوص الأهرام من عهد أوناس داخل الحجرات الملكية، وتضم تعاويذ تساعد الملك المتوفى على الصعود والانضمام إلى الآلهة وتلقي القرابين. توسعت التقاليد الجنائزية لاحقًا في نصوص التوابيت وكتاب الموتى، لكن لا يجوز إسقاط هذا الانتشار اللاحق على بدايتها الملكية.', 'مصر: النصوص الجنائزية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'لماذا تُعد مكتبة آشوربانيبال في نينوى بالغة الأهمية لدراسة أدب الرافدين؟', '["لأنها أول مكتبة ورقية عامة مجانية","لأنها لا تضم إلا مراسلات آشوربانيبال الشخصية","لأنها اكتُشفت سليمة في مدينة بابل","لأنها حفظت ألواحًا ونسخًا علمية وأدبية متعددة، بينها نسخ من ملحمة جلجامش، جُمعت من تقاليد أقدم"]'::jsonb, 3, 45, 16, 'multi', 'جمع آشوربانيبال في القرن السابع ق.م. آلاف الألواح المسمارية في نينوى، شملت أدبًا وعرافة وطبًا ومعاجم ونصوصًا طقسية. حفظت المكتبة مؤلفات أقدم بكثير من العصر الآشوري، ولذلك لا تعني نسبة المجموعة إليه أنه ألّفها.', 'الرافدان: آشور والأدب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي تفسير يطابق علاقة فيضان النيل بالتقويم والاقتصاد المصريين من دون تبسيط مفرط؟', '["نظم الإيقاع الزراعي، لكن انخفاضه أو ارتفاعه المفرط كان يهدد المحاصيل، فاستلزم رصدًا وإدارة للموارد","كان الفيضان ثابت الارتفاع دائمًا فلا يحتاج إلى إدارة","ألغى الحاجة إلى الري كليًا في جميع مناطق مصر","كان يحدث شتاءً بسبب ذوبان ثلوج الدلتا"]'::jsonb, 0, 45, 17, 'multi', 'ارتبطت مواسم أخِت وبرِت وشِمو بدورة الفيضان والإنبات والحصاد. جلب الفيضان الماء والطمي، لكن التفاوت الكبير قد يؤدي إلى نقص أو دمار؛ لذا كان قياس المنسوب وتنظيم الأحواض والحبوب جزءًا من قدرة الدولة والمجتمعات المحلية على التكيف.', 'مصر: البيئة والاقتصاد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الذي تكشفه مقابر أور الملكية عن المجتمع السومري في عصر فجر السلالات؟', '["مجتمع بلا تفاوت في الثروة أو الرتبة","اقتصاد منعزل لم يستورد مواد بعيدة","تحول كامل إلى الديانة الآشورية","نخب قادرة على حشد ذهب ولازورد وآلات وطقوس دفن معقدة وربما مرافقين بشريين"]'::jsonb, 3, 45, 18, 'multi', 'تكشف المدافن عن تفاوت شديد، وحرفية عالية، وشبكات بعيدة جلبت اللازورد والذهب، وطقوس صاحبت بعض الدفنات فيها عدد من الأفراد. أما تفسير كيفية موت المرافقين فقد خضع للنقاش، لذلك لا ينبغي تحويله إلى رواية يقينية واحدة.', 'الرافدان: أور والمجتمع');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'بعد انهيار الدولة القديمة، ما السمة السياسية التي ميزت جانبًا كبيرًا من عصر الانتقال الأول قبل إعادة التوحيد؟', '["حكم فارسي مباشر من برسبوليس","سيطرة الهكسوس على طيبة","تنافس مراكز إقليمية، ولا سيما هيراكليوبوليس وطيبة، مع تزايد نفوذ حكام الأقاليم","نقل أخناتون العاصمة إلى العمارنة"]'::jsonb, 2, 45, 19, 'multi', 'شهد عصر الانتقال الأول تفكك السلطة المركزية وصعود قوى إقليمية، وانتهى الصراع بإعادة منتوحتب الثاني الطيبي توحيد البلاد وبداية الدولة الوسطى. الهكسوس والعمارنة والحكم الفارسي مراحل لاحقة منفصلة.', 'مصر: عصر الانتقال الأول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي وصف يفسر نتيجة معركة قادش بين رمسيس الثاني ومواتالي الثاني تفسيرًا تاريخيًا متوازنًا؟', '["نصر مصري حاسم أدى فورًا إلى سقوط الدولة الحيثية","انتصار حيثي أنهى الدولة المصرية الحديثة","مواجهة غير حاسمة استغلها الطرفان دعائيًا، وظلت قادش في المجال الحيثي ثم تلاها سلام لاحق","معركة بحرية ضد شعوب البحر"]'::jsonb, 2, 50, 20, 'multi', 'قدمت نقوش رمسيس المعركة كإنجاز شخصي هائل، لكن مصر لم تنتزع قادش، ولم تُسقط المعركة أيًا من الدولتين. بعد سنوات من التنافس أبرم رمسيس الثاني وحتوسيلي الثالث معاهدة سلام، وهو ما يميز الحدث الفعلي عن الدعاية الملكية.', 'مصر: الدولة الحديثة والدبلوماسية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الفرق الأدق بين السومرية والأكدية في تاريخ الكتابة الرافدينية؟', '["كلتاهما لهجتان يونانيتان كتبتا بالأبجدية","السومرية خط فقط والأكدية لغة بلا كتابة","الأكدية أقدم دائمًا من جميع نصوص السومرية","السومرية لغة معزولة، والأكدية لغة سامية؛ واستعملتا النظام المسماري مع تكييفه لقيم لغوية مختلفة"]'::jsonb, 3, 50, 21, 'multi', 'السومرية لا تُنسب بثقة إلى أسرة لغوية معروفة، بينما الأكدية سامية شرقية. تبنى الناطقون بالأكدية المسمارية الموروثة وطوعوا علاماتها المقطعية واللوغوغرافية، وبقيت السومرية لغة علم وطقس بعد تراجعها كلامًا.', 'الرافدان: اللغات والكتابة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'ما الذي يسمح لعلماء الآثار بتمييز مدينة تلّ رافدينية متعددة الطبقات عن مستوطنة ذات مرحلة واحدة؟', '["وجود قمة طبيعية بركانية فقط","تراكم طبقات بناء وهدم وإعادة تشييد متعاقبة يمكن فصلها طبقيًا وربط لقى كل طبقة بسياقها","العثور على نص ملكي واحد فوق السطح","تشابه جميع الفخار في كل الأعماق"]'::jsonb, 1, 50, 22, 'multi', 'يتكون التل من تراكم العمارة الطينية والردم والنشاط البشري عبر أجيال. يتيح التحليل الطبقي تتبع التعاقب الزمني؛ أما خلط اللقى المنقولة أو الاعتماد على قطعة منفردة فيفصلها عن سياقها ولا يثبت مرحلة كاملة.', 'منهج علم الآثار');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'لماذا يُعد لقب حتشبسوت وصورها الملكية موضوعًا مهمًا لفهم الملكية المصرية؟', '["لأنها أخفت اسمها ولم تستخدم ألقاب الملك قط","لأنها استخدمت ألقاب الفرعون وصورًا تجمع أحيانًا بين هيئة أنثوية وعلامات ملكية ذكورية لتأكيد أهلية الحكم","لأنها حكمت بصفتها ملكة حيثية في الأناضول","لأن جميع صورها دُمرت قبل تتويجها"]'::jsonb, 1, 50, 23, 'multi', 'بدأت حتشبسوت وصية ثم اتخذت ألقاب الملك الكاملة. تتنوع تماثيلها ونقوشها بين إشارات إلى جسدها الأنثوي وصياغات بصرية ملكية تقليدية، ومنها اللحية الاحتفالية؛ وهذا يعكس تكييف مؤسسة مصوغة غالبًا بعبارات ذكورية، لا إنكارًا بسيطًا لهويتها.', 'مصر: الدولة الحديثة والملكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_44, 'أي مقارنة بين سقوط نينوى سنة 612 ق.م. وسقوط بابل سنة 539 ق.م. صحيحة؟', '["نينوى سقطت أمام تحالف بابلي-ميدي منهِيًا قلب الدولة الآشورية الحديثة، أما بابل فدخلت تحت حكم كورش الفارسي","كلاهما حدث في الحرب نفسها على يد رمسيس الثاني","بابل سقطت أولًا وأسست الإمبراطورية الآشورية الحديثة","نينوى فتحها الإسكندر وبابل فتحها حمورابي"]'::jsonb, 0, 50, 24, 'multi', 'دمر البابليون والميديون نينوى عام 612 ق.م. ضمن انهيار آشور الحديثة، ثم أصبحت بابل مركز الدولة البابلية الحديثة. وبعد نحو سبعة عقود استولى كورش الثاني على بابل سنة 539 ق.م. وأدخلها في الإمبراطورية الأخمينية؛ فالحدثان متعاقبان لا متزامنان.', 'الرافدان: آشور وبابل الحديثة');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_45 uuid;
BEGIN
  SELECT id INTO v_lib_id_45 FROM quizzes WHERE title = 'الحروب الحديثة والدبلوماسية العالمية' LIMIT 1;
  IF v_lib_id_45 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الحروب الحديثة والدبلوماسية العالمية', 'تاريخ', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_45;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في التسوية الأوروبية التي صاغها مؤتمر فيينا بين سبتمبر 1814 ويونيو 1815، أي ترتيب أُنشئ خصوصًا ليكون حاجزًا شمال فرنسا؟', '["إنشاء اتحاد ألماني بقيادة بروسية مباشرة","إعادة جمهورية البندقية مستقلة","توحيد سويسرا وسافوا في مملكة واحدة","ضم بلجيكا إلى هولندا في مملكة الأراضي المنخفضة المتحدة"]'::jsonb, 3, 35, 0, 'multi', 'جمع مؤتمر فيينا المقاطعات البلجيكية السابقة مع هولندا في مملكة الأراضي المنخفضة المتحدة تحت أسرة أوراني، ضمن سياسة إقامة دول حاجزة حول فرنسا. أما الاتحاد الألماني فكان رابطة من 39 دولة ولم يكن دولة بروسية موحدة.', 'النظام الأوروبي بعد نابليون');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي بند في معاهدة باريس الموقعة في 30 مارس 1856 بعد حرب القرم غيّر الوضع العسكري للبحر الأسود؟', '["وضع المضائق كلها تحت سيادة روسية","تحييد البحر الأسود ومنع الترسانات والسفن الحربية فيه","منح النمسا قاعدة بحرية في القرم","نقل القسطنطينية إلى إدارة دولية"]'::jsonb, 1, 35, 1, 'multi', 'نصت معاهدة باريس لعام 1856 على تحييد البحر الأسود، فحظر وجود السفن الحربية والترسانات البحرية على سواحله. قُيّد بذلك كل من روسيا والدولة العثمانية، ولم تُنقل السيادة على المضائق أو القسطنطينية.', 'حرب القرم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في اتفاقية الهدنة الكورية الموقعة في بانمونجوم في 27 يوليو 1953، ما الهيئة التي أُنشئت للإشراف على تنفيذ شروط الهدنة؟', '["لجنة الهدنة العسكرية مع لجنة دول محايدة للرقابة","مجلس وصاية تابع للأمم المتحدة","لجنة عسكرية مشتركة من دول الكومنولث","محكمة دائمة في سيول"]'::jsonb, 0, 35, 2, 'multi', 'أنشأت الهدنة لجنة الهدنة العسكرية للإشراف على التطبيق، ولجنة الأمم المحايدة للرقابة لتنفيذ مهام تفتيش محددة. الاتفاق أوقف الأعمال القتالية وأنشأ المنطقة المنزوعة السلاح، لكنه لم يكن معاهدة سلام نهائية.', 'الحرب الكورية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'ما الأثر الإقليمي المباشر لمعاهدة فرانكفورت في 10 مايو 1871 التي أنهت الحرب الفرنسية البروسية؟', '["تخلت بروسيا عن الراين لفرنسا","أصبحت لوكسمبورغ مقاطعة فرنسية","ضمت إيطاليا سافوا ونيس","تنازل فرنسا لألمانيا عن معظم الألزاس وجزء من اللورين"]'::jsonb, 3, 35, 3, 'multi', 'أكدت معاهدة فرانكفورت تنازل فرنسا للإمبراطورية الألمانية الجديدة عن معظم الألزاس وأجزاء من اللورين، إلى جانب تعويض مالي واحتلال مؤقت مرتبط بالسداد. سافوا ونيس انتقلتا إلى فرنسا قبل ذلك في 1860.', 'توحيد ألمانيا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'وفق البروتوكول السري الملحق بمعاهدة عدم الاعتداء الألمانية السوفيتية في 23 أغسطس 1939، في أي مجال وقع تقسيم مناطق النفوذ؟', '["البلقان والأناضول فقط","شرق آسيا والمحيط الهادئ","المستعمرات الأفريقية الألمانية السابقة","أوروبا الشرقية، بما فيها تقسيم مجال بولندا"]'::jsonb, 3, 35, 4, 'multi', 'وزّع البروتوكول السري مناطق نفوذ في شرق أوروبا بين ألمانيا والاتحاد السوفيتي، وتناول فنلندا وإستونيا ولاتفيا وليتوانيا وبولندا وبيسارابيا. ثم عُدلت بعض الحدود التقديرية في معاهدة الحدود والصداقة في 28 سبتمبر 1939.', 'الدبلوماسية قبيل الحرب العالمية الثانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'ما المبدأ الإجرائي الذي أقره ميثاق بريان–كيلوغ الموقّع في باريس في 27 أغسطس 1928؟', '["إنشاء جيش دولي دائم","التخلي عن الحرب أداةً للسياسة الوطنية وتسوية النزاعات سلميًا","إلغاء حق الدفاع عن النفس بنص صريح","فرض عقوبات آلية بواسطة عصبة الأمم"]'::jsonb, 1, 35, 5, 'multi', 'تعهدت الأطراف في المادتين الأولى والثانية بإدانة اللجوء إلى الحرب لحل المنازعات والتخلي عنها أداةً للسياسة الوطنية، وبطلب الحل بالوسائل السلمية. لم ينشئ الميثاق جهاز إنفاذ أو جيشًا دوليًا.', 'الأمن الجماعي بين الحربين');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي التزام يميز المادة الخامسة من معاهدة شمال الأطلسي الموقعة في 4 أبريل 1949؟', '["الرد العسكري المتماثل إلزامي تلقائيًا لكل عضو","الهجوم على عضو يُعد هجومًا على الجميع، ويتخذ كل عضو ما يراه ضروريًا بما فيه القوة المسلحة","أي نزاع تجاري يُحال إلى محكمة العدل الدولية","لا تسري المعاهدة إلا بعد تفويض جديد من مجلس الأمن"]'::jsonb, 1, 35, 6, 'multi', 'تعد المادة الخامسة الهجوم المسلح على طرف أو أكثر هجومًا عليهم جميعًا، لكنها تترك لكل طرف اتخاذ الإجراء الذي يراه ضروريًا، بما في ذلك استخدام القوة المسلحة. لذلك لا تنص على رد عسكري متماثل وآلي حرفيًا.', 'تحالفات الحرب الباردة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في اتفاقيات جنيف الخاصة بالهند الصينية في يوليو 1954، كيف وُصف الخط عند دائرة العرض 17 في فيتنام؟', '["خط ترسيم عسكري مؤقت مع منطقة منزوعة السلاح","حد دولي دائم تعترف به الأمم المتحدة","حد استعماري يعيد تونكين للصين","ممر بحري خاضع لفرنسا خمسين عامًا"]'::jsonb, 0, 40, 7, 'multi', 'نص اتفاق وقف الأعمال القتالية على خط ترسيم عسكري مؤقت ومنطقة منزوعة السلاح، وأكد الإعلان الختامي أن الخط لا ينبغي تفسيره حدًا سياسيًا أو إقليميًا. كان مقررًا إجراء انتخابات عامة في يوليو 1956، لكنها لم تُجرَ.', 'الهند الصينية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'بموجب معاهدة الدولة النمساوية الموقعة في فيينا في 15 مايو 1955، ما التسوية الأساسية التي مهّدت لإنهاء احتلال الحلفاء؟', '["تقسيم النمسا إلى دولتين","إعادة الاتحاد السياسي مع ألمانيا","استعادة النمسا دولة مستقلة ديمقراطية وحظر الاتحاد مع ألمانيا","ضم تيرول كله إلى إيطاليا"]'::jsonb, 2, 40, 8, 'multi', 'أعادت المعاهدة تأسيس النمسا دولة مستقلة وديمقراطية، وحظرت الاتحاد السياسي أو الاقتصادي مع ألمانيا. وبعد دخولها حيز النفاذ انسحبت قوات الاحتلال؛ أما الحياد الدائم فأعلنه قانون دستوري نمساوي منفصل في 26 أكتوبر 1955.', 'تسويات ما بعد الحرب العالمية الثانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'ما الذي قرره قرار مجلس الأمن 242 الصادر في 22 نوفمبر 1967 بشأن إطار التسوية بعد حرب يونيو؟', '["إنشاء دولة فلسطينية بحدود مرسومة تفصيليًا","فرض إدارة أممية دائمة للقدس","إلغاء اتفاقيات الهدنة لعام 1949 فورًا","الدعوة إلى انسحاب القوات الإسرائيلية من أراضٍ احتُلت في النزاع وإقرار حق دول المنطقة في العيش بسلام ضمن حدود آمنة ومعترف بها"]'::jsonb, 3, 40, 9, 'multi', 'جمع القرار 242 بين مبدأ الانسحاب من أراضٍ احتُلت في نزاع 1967 وبين إنهاء حالات الحرب والاعتراف بسيادة كل دولة وحقها في العيش ضمن حدود آمنة ومعترف بها. لم يرسم القرار حدودًا تفصيلية ولم ينشئ إدارة دائمة للقدس.', 'الصراع العربي الإسرائيلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي صيغة دستورية اعتمدها القانون الختامي لمؤتمر فيينا في 9 يونيو 1815 للفضاء الألماني بعد حل الإمبراطورية الرومانية المقدسة؟', '["إمبراطورية وراثية تحت آل هابسبورغ","اتحاد فدرالي مركزي ببرلمان منتخب","كونفدرالية من 39 دولة ذات مجلس اتحادي في فرانكفورت برئاسة نمساوية","اتحاد جمركي تقوده فرنسا"]'::jsonb, 2, 45, 10, 'multi', 'أنشأ قانون الاتحاد الألماني كونفدرالية من 39 دولة، لها جمعية اتحادية دائمة في فرانكفورت وترأسها النمسا. لم تكن الكونفدرالية دولة قومية مركزية ولا برلمانًا منتخبًا على أساس الاقتراع العام.', 'مؤتمر فيينا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في معاهدة سان ستيفانو في 3 مارس 1878 ثم مراجعتها في مؤتمر برلين في 13 يوليو 1878، ما التغيير الأبرز الذي طال بلغاريا؟', '["قُسّمت المملكة البلغارية الكبرى المقترحة إلى إمارة بلغاريا وروميليا الشرقية، مع إعادة مقدونيا للسلطان","تحولت إلى مستعمرة بريطانية","ضُمت كلها إلى روسيا","اتحدت فورًا مع صربيا ورومانيا"]'::jsonb, 0, 45, 11, 'multi', 'قلّصت معاهدة برلين بلغاريا الكبرى التي رسمتها سان ستيفانو: أصبحت بلغاريا إمارة ذاتية الحكم شمال البلقان، وأُنشئت روميليا الشرقية جنوبه بحكم ذاتي إداري، وأعيدت مقدونيا إلى الحكم العثماني المباشر.', 'المسألة الشرقية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'كيف عالجت المادة 231 من معاهدة فرساي الموقعة في 28 يونيو 1919 أساس المسؤولية عن التعويضات؟', '["حمّلت ألمانيا وحلفاءها مسؤولية الخسائر الناجمة عن الحرب المفروضة بعدوانهم كأساس للتعويض","برأت جميع الأطراف من المسؤولية القانونية","فرضت التعويضات على النمسا وحدها","حددت فورًا مبلغًا نهائيًا بالدولار داخل المادة نفسها"]'::jsonb, 0, 45, 12, 'multi', 'قبلت ألمانيا وحلفاؤها في المادة 231 المسؤولية عن الخسائر والأضرار التي لحقت بالحلفاء نتيجة الحرب المفروضة بعدوان ألمانيا وحلفائها. خدمت المادة أساسًا قانونيًا للتعويضات؛ أما المبلغ التفصيلي فلم تحدده المادة نفسها.', 'تسوية فرساي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'ما الآلية التي أضافتها اتفاقيات لوكارنو الموقعة في 16 أكتوبر 1925 لضمان حدود ألمانيا الغربية؟', '["ضم الراين إلى عصبة الأمم","تحالف هجومي فرنسي سوفيتي","ضمان بريطاني وإيطالي متبادل لحدود ألمانيا مع فرنسا وبلجيكا مع ميثاق الراين","اعتراف ألماني مماثل ونهائي بحدودها الشرقية مع بولندا وتشيكوسلوفاكيا"]'::jsonb, 2, 45, 13, 'multi', 'ضمن ميثاق الراين الوضع الإقليمي بين ألمانيا وفرنسا وبلجيكا، وكانت بريطانيا وإيطاليا ضامنتين ضد خرق الحدود أو نزع سلاح الراين. لم تحصل حدود ألمانيا الشرقية على الضمان الجماعي نفسه؛ عولجت عبر معاهدات تحكيم منفصلة.', 'الدبلوماسية بين الحربين');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في اتفاق ميونيخ الموقّع ليلة 29–30 سبتمبر 1938، أي أطراف قررت نقل السوديت إلى ألمانيا دون مشاركة تشيكوسلوفاكيا في التفاوض النهائي؟', '["بريطانيا وفرنسا وألمانيا وإيطاليا","ألمانيا وإيطاليا وبولندا والاتحاد السوفيتي","بريطانيا والولايات المتحدة وفرنسا وتشيكوسلوفاكيا","ألمانيا والاتحاد السوفيتي وبريطانيا واليابان"]'::jsonb, 0, 45, 14, 'multi', 'وقع الاتفاق هتلر وموسوليني وتشامبرلين ودالادييه عن ألمانيا وإيطاليا وبريطانيا وفرنسا. أُلزمت تشيكوسلوفاكيا بإخلاء مناطق السوديت وفق جدول زمني، مع أنها لم تكن طرفًا مشاركًا في صنع الاتفاق النهائي.', 'أزمة ميونيخ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي مسألة تركها بروتوكول مؤتمر بوتسدام الصادر في 2 أغسطس 1945 لتسوية سلام نهائية، رغم وضع الأراضي الألمانية شرق خط الأودر–نايسه تحت إدارة بولندية مؤقتة؟', '["حل القوات المسلحة الألمانية","تقسيم برلين إلى قطاعات احتلال","الحد النهائي لألمانيا","محاكمة مجرمي الحرب"]'::jsonb, 2, 45, 15, 'multi', 'وضع بروتوكول بوتسدام الأراضي الألمانية السابقة شرق الأودر–نايسه تحت الإدارة البولندية، لكنه نص على أن التحديد النهائي للحد الغربي لبولندا ينتظر تسوية السلام. ثُبّت الاعتراف النهائي في سياق معاهدة التسوية النهائية بشأن ألمانيا عام 1990 ومعاهدة الحدود الألمانية البولندية.', 'تسويات الحرب العالمية الثانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في مؤتمر يالطا بين 4 و11 فبراير 1945، ما الصيغة المعتمدة للتصويت في مجلس الأمن التي عالجت مسألة امتياز القوى الكبرى؟', '["إجماع جميع أعضاء الأمم المتحدة في كل قرار","موافقة الأعضاء الدائمين في القرارات الموضوعية، مع امتناع طرف النزاع عن التصويت في بعض قرارات الفصل السادس","صوتان لكل دولة دائمة دون حق نقض","تسعة أصوات فقط بصرف النظر عن موقف الدائمين"]'::jsonb, 1, 50, 16, 'multi', 'أنتجت يالطا صيغة التصويت التي اشترطت تلاقي أصوات الأعضاء الدائمين في المسائل غير الإجرائية، وهي أصل حق النقض. وتضمنت الصيغة قيد امتناع طرف النزاع في قرارات معينة متصلة بالتسوية السلمية؛ ثم صيغ ذلك في المادة 27 من الميثاق.', 'نشأة الأمم المتحدة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي فرق قانوني جوهري ميّز اتفاقية جنيف الثالثة لعام 1949 الخاصة بأسرى الحرب عن اتفاقيتي جنيف لعام 1929؟', '["ألغت حماية الأسرى عند الاستسلام","وسّعت فئات المستفيدين ونظمت الأسر والعمل والمحاكمة والإعادة بتفصيل أكبر","اقتصرت على الحروب البحرية","سمحت للدولة الحاجزة بالتخلي عن مسؤوليتها بنقل الأسرى لأي دولة"]'::jsonb, 1, 50, 17, 'multi', 'استفادت اتفاقية 1949 من خبرة الحرب العالمية الثانية، فوسعت تعريف الفئات المشمولة ووضعت قواعد أكثر تفصيلًا للاحتجاز والعمل والعقوبات القضائية والإفراج والإعادة. كما أبقت مسؤولية الدولة الناقلة إذا أخفقت الدولة المستقبلة في تطبيق الاتفاقية.', 'القانون الدولي الإنساني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في التسوية الدبلوماسية لأزمة الصواريخ الكوبية في أكتوبر 1962، أي ترتيب كان علنيًا وأي ترتيب ظل سريًا آنذاك؟', '["علنًا سحب صواريخ جوبيتر؛ سرًا حصار كوبا","علنًا انضمام كوبا للناتو؛ سرًا تقسيم برلين","علنًا انسحاب السوفييت من ألمانيا؛ سرًا اعتراف أمريكي بكوبا","علنًا سحب الصواريخ السوفيتية من كوبا وتعهد أمريكي بعدم غزوها؛ سرًا سحب صواريخ جوبيتر الأمريكية من تركيا لاحقًا"]'::jsonb, 3, 50, 18, 'multi', 'قبل خروتشوف إزالة الصواريخ الهجومية من كوبا مقابل تعهد علني أمريكي بعدم غزو الجزيرة. وبقناة منفصلة وافقت واشنطن سرًا على إزالة صواريخ جوبيتر من تركيا خلال مدة لاحقة، مع منع تصوير ذلك كمقايضة علنية.', 'أزمات الحرب الباردة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'كيف عالجت معاهدة حظر التجارب النووية الجزئي الموقعة في 5 أغسطس 1963 بيئات الاختبار المختلفة؟', '["حظرت التجارب في الجو والفضاء الخارجي وتحت الماء، ولم تحظر الاختبارات الجوفية ما لم تتجاوز الحطام الإشعاعي حدود الدولة","حظرت كل اختبار نووي بلا استثناء","حظرت التجارب الجوفية فقط","سمحت بالتجارب في الفضاء وحظرتها في الصحارى"]'::jsonb, 0, 50, 19, 'multi', 'حظرت المعاهدة التفجيرات النووية في الغلاف الجوي والفضاء الخارجي وتحت الماء، وكذلك أي بيئة إذا تسبب الانفجار في حطام إشعاعي خارج حدود الدولة. لذلك بقي الاختبار الجوفي المحتوى داخل الحدود غير محظور بموجبها.', 'الحد من التسلح النووي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'أي التزامين شكّلا المقايضة المركزية في معاهدة عدم انتشار الأسلحة النووية التي فُتحت للتوقيع في 1 يوليو 1968 ودخلت حيز النفاذ في 5 مارس 1970؟', '["احتكار دائم بلا التزام تفاوضي مقابل حظر الطاقة النووية المدنية","تسليم كل المواد الانشطارية للأمم المتحدة مقابل ضمان حدود الدول","عدم اقتناء الدول غير النووية للسلاح وقبول الضمانات، مقابل تسهيل الاستخدام السلمي والتزام الأطراف بالتفاوض نحو نزع السلاح","حظر الصواريخ الباليستية مقابل السماح بالتجارب الجوية"]'::jsonb, 2, 50, 20, 'multi', 'تلزم المعاهدة الدول غير الحائزة بعدم صنع أو تلقي السلاح النووي وبضمانات الوكالة الدولية، وتحمي حق الاستخدام السلمي والتعاون فيه. كما تلزم المادة السادسة جميع الأطراف بالسعي بحسن نية إلى مفاوضات بشأن وقف سباق التسلح ونزع السلاح النووي.', 'نظام عدم الانتشار');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في وثيقة هلسنكي الختامية الموقعة في 1 أغسطس 1975، كيف اقترنت حرمة الحدود بإمكان تغييرها؟', '["حُظر أي تغيير للحدود حتى بالاتفاق","أُقرت حرمة الحدود، مع إمكان تغييرها وفق القانون الدولي بوسائل سلمية وبالاتفاق","أُعطي الاتحاد السوفيتي وحده حق تعديل الحدود","أصبحت الوثيقة معاهدة دفاع جماعي ملزمة عسكريًا"]'::jsonb, 1, 50, 21, 'multi', 'أكدت الوثيقة الامتناع عن الاعتداء على حدود الدول، لكنها نصت أيضًا على إمكان تغيير الحدود وفق القانون الدولي وبالوسائل السلمية والاتفاق. كانت الوثيقة التزامًا سياسيًا واسعًا شمل الأمن والتعاون وحقوق الإنسان، لا معاهدة دفاع جماعي.', 'الانفراج الأوروبي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'ما الترتيب الأمني الذي نصت عليه معاهدة السلام المصرية الإسرائيلية الموقعة في 26 مارس 1979 في شبه جزيرة سيناء؟', '["بقاء سيناء تحت إدارة مشتركة دائمة","نشر قوات هجومية مصرية بلا قيود على الحدود","انسحاب إسرائيلي مرحلي مع مناطق متفاوتة القيود على القوات وترتيبات مراقبة","تأجير شرم الشيخ لإسرائيل 99 عامًا"]'::jsonb, 2, 50, 22, 'multi', 'رتبت المعاهدة انسحابًا إسرائيليًا كاملًا على مراحل إلى الحدود الدولية، وقسم ملحقها الأمني سيناء والنقب الحدودي إلى مناطق بقيود مختلفة على القوات والتسليح، مع آليات مراقبة. وبعد تعذر قوة أممية أنشئت القوة متعددة الجنسيات والمراقبون باتفاق لاحق.', 'دبلوماسية الشرق الأوسط');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'لماذا سميت معاهدة 12 سبتمبر 1990 بشأن ألمانيا باتفاق «اثنين زائد أربعة»، وما الأثر السيادي الأساسي لدخولها حيز النفاذ في 15 مارس 1991؟', '["دولتا ألمانيا زائد أربع دول مجاورة؛ أنشأت كونفدرالية مؤقتة","حزبان ألمانيان زائد أربع منظمات؛ أبقت برلين محتلة","ولايتان ألمانيتان زائد أربعة جيوش؛ قسمت ألمانيا ست مناطق","ألمانيا الشرقية والغربية زائد القوى الأربع المحتلة؛ أنهت حقوق ومسؤوليات القوى الأربع وأعادت لألمانيا الموحدة السيادة الكاملة"]'::jsonb, 3, 50, 23, 'multi', 'شارك البلدان الألمانيان والقوى الأربع ذات الحقوق في ألمانيا—الولايات المتحدة والاتحاد السوفيتي وبريطانيا وفرنسا—في التسوية. أنهت المعاهدة حقوق القوى الأربع المتعلقة ببرلين وألمانيا ككل، فأصبحت ألمانيا الموحدة ذات سيادة كاملة على شؤونها الداخلية والخارجية.', 'نهاية الحرب الباردة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_45, 'في الاتفاق الإطاري العام للسلام في البوسنة والهرسك، الموقّع في باريس في 14 ديسمبر 1995 بعد التفاوض في دايتون، كيف نُظمت الدولة داخليًا؟', '["قُسمت إلى ثلاث دول مستقلة ذات سيادة","أصبحت محمية تابعة لحلف الناتو بلا مؤسسات محلية","أُلحقت سراييفو بكرواتيا وبانيا لوكا بصربيا","استمرت البوسنة والهرسك دولة واحدة تتكون من كيانين: اتحاد البوسنة والهرسك وجمهورية صربسكا"]'::jsonb, 3, 50, 24, 'multi', 'أكد دستور الملحق الرابع استمرار الوجود القانوني للبوسنة والهرسك بحدودها المعترف بها دوليًا، ونص على أنها تتكون من كيانين: اتحاد البوسنة والهرسك وجمهورية صربسكا. لم يمنح الكيانين سيادة دولية مستقلة.', 'حروب يوغوسلافيا');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_46 uuid;
BEGIN
  SELECT id INTO v_lib_id_46 FROM quizzes WHERE title = 'تشريح وفسيولوجيا جسم الإنسان' LIMIT 1;
  IF v_lib_id_46 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('تشريح وفسيولوجيا جسم الإنسان', 'علوم وطب', '', 'medium_high', 'ar', true)
    RETURNING id INTO v_lib_id_46;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'عند انقباض الحجاب الحاجز في شهيق هادئ لدى شخص سليم، أي تغير مباشر يفسر دخول الهواء إلى الرئتين؟', '["ينقص حجم الصدر ويرتفع الضغط السنخي فوق الضغط الجوي","يرتفع الضغط داخل الجنبة إلى قيمة موجبة فيدفع الهواء للداخل","يزداد الحجم الرأسي للصدر وينخفض الضغط السنخي دون الضغط الجوي","تنقبض العضلات الوربية الداخلية فتخفض الأضلاع"]'::jsonb, 2, 30, 0, 'multi', 'يهبط الحجاب الحاجز عند انقباضه، فيزيد حجم التجويف الصدري. وبفعل اقتران الرئة بجدار الصدر عبر السائل الجنبي تتمدد الأسناخ وينخفض ضغطها قليلًا دون الضغط الجوي، فيتحرك الهواء إلى الداخل. أما الوربيات الداخلية فتشارك أساسًا في الزفير القسري.', 'الجهاز التنفسي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي وعاء يحمل عادةً دمًا غير مؤكسج من البطين الأيمن نحو الرئتين؟', '["الأوردة الرئوية","الأبهر الصاعد","الوريد الأجوف العلوي","الجذع الرئوي وفروعه"]'::jsonb, 3, 25, 1, 'multi', 'يدفع البطين الأيمن الدم الوريدي عبر الصمام الرئوي إلى الجذع الرئوي ثم الشريانين الرئويين للتبادل الغازي. تسمية الشريان تتعلق باتجاه الجريان بعيدًا عن القلب لا بمحتوى الأكسجين؛ أما الأوردة الرئوية فتعيد الدم المؤكسج إلى الأذين الأيسر.', 'القلب والدوران');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'في الكلية، أين يبدأ الترشيح الذي ينقل الماء والجزيئات الصغيرة من الشعيرات الدموية إلى الحيز البولي؟', '["عروة هنلي والقناة الجامعة","الكبيبة ومحفظة بومان","الحويضة الكلوية والحالب","الجهاز المجاور للكبيبات فقط"]'::jsonb, 1, 25, 2, 'multi', 'يتكون الجسيم الكلوي من كبيبة شعيرية تحيط بها محفظة بومان. يعبر الرشاح حاجزًا من البطانة المثقبة والغشاء القاعدي وشقوق الخلايا القدمية إلى حيز بومان؛ ثم تعدل النبيبات تركيبه بإعادة الامتصاص والإفراز.', 'الجهاز البولي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي جزء من الجهاز العصبي الذاتي يرفع عادةً معدل القلب عبر إفراز النورإبينفرين على العقدة الجيبية الأذينية؟', '["الألياف نظيرة الودية قبل العقدية","العصبونات الحسية الجسدية","الألياف الودية بعد العقدية","الألياف الحركية الجسدية"]'::jsonb, 2, 30, 3, 'multi', 'تنبه الألياف الودية القلبية مستقبلات بيتا-1 في خلايا الناظمة، فتزيد سرعة زوال الاستقطاب التلقائي ومعدل النبض. في المقابل يحرر العصب المبهم أستيل كولين عند القلب ويبطئ العقدة الجيبية والعقدة الأذينية البطينية.', 'الجهاز العصبي الذاتي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي نوع من الخلايا البنكرياسية يفرز الإنسولين استجابةً لارتفاع غلوكوز الدم؟', '["خلايا ألفا في الجزر","الخلايا العنيبية الخارجية الإفراز","خلايا القنوات البنكرياسية","خلايا بيتا في جزر لانغرهانس"]'::jsonb, 3, 25, 4, 'multi', 'خلايا بيتا هي المصدر الصماوي للإنسولين، الذي يعزز دخول الغلوكوز إلى أنسجة حساسة له وتخزين الوقود ويحد من إنتاج الغلوكوز الكبدي. خلايا ألفا تفرز الغلوكاغون، بينما تنتج الخلايا العنيبية إنزيمات هضمية إلى القنوات.', 'الغدد الصماء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي بنية في الأذن الداخلية تحول اهتزازات الصوت إلى إشارات عصبية سمعية؟', '["القنوات نصف الدائرية في الدهليز","الغشاء الطبلي وحده","الخلايا الشعرية في عضو كورتي داخل القوقعة","عظيمات المطرقة والسندان والركاب وحدها"]'::jsonb, 2, 30, 5, 'multi', 'تنقل العظيمات الطاقة الميكانيكية إلى النافذة البيضوية، فتولّد موجة على الغشاء القاعدي. يثني القص حزم الأهداب المجسمة للخلايا الشعرية في عضو كورتي، فتتغير موصليتها وتحرر ناقلًا إلى ألياف العصب القوقعي.', 'الحواس الخاصة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'ما الحركة الأساسية التي تنتجها العضلة ذات الرأسين العضدية عندما يكون الساعد حرًا؟', '["ثني المرفق واستلقاء الساعد","بسط المرفق وكب الساعد","تبعيد العضد ودورانه الإنسي","بسط الرسغ وانحرافه الزندي"]'::jsonb, 0, 25, 6, 'multi', 'ترتكز العضلة ذات الرأسين على الحدبة الكعبرية والصفاق ذي الرأسين؛ لذلك تثني المرفق وتدير الكعبرة إلى وضع الاستلقاء، وتكون مستلقيًا قويًا خصوصًا مع ثني المرفق. البسط وظيفة رئيسة للعضلة ثلاثية الرؤوس.', 'الجهاز العضلي الهيكلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أين يحدث معظم امتصاص المغذيات المهضومة في القناة الهضمية؟', '["المعدة عبر الغدد القاعية","الأمعاء الدقيقة بفضل الطيات والزغابات والزغيبات","القولون الصاعد عبر الخبايا فقط","المريء عبر الظهارة الحرشفية"]'::jsonb, 1, 25, 7, 'multi', 'توفر الأمعاء الدقيقة مساحة سطح واسعة بفعل الطيات الدائرية والزغابات والزغيبات، وتحمل خلاياها نواقل وإنزيمات حدود الفرشاة. يختص القولون أكثر باسترداد الماء والشوارد والتعامل مع نواتج الميكروبيوم، لا بامتصاص معظم المغذيات.', 'الجهاز الهضمي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي خلية دموية ناضجة تنقل معظم الأكسجين بفضل الهيموغلوبين وتفتقر عادةً إلى نواة؟', '["كرية الدم الحمراء","العدلة","الخلية اللمفاوية","الوحيدة"]'::jsonb, 0, 25, 8, 'multi', 'تفقد الكرية الحمراء البشرية نواتها وعضيات كثيرة أثناء النضج، ما يفسح حيزًا للهيموغلوبين ويمنحها مرونة لعبور الشعيرات. وهي تحمل الأكسجين أساسًا مرتبطًا بالهيموغلوبين، في حين تحتفظ الكريات البيضاء المذكورة بأنويتها وتؤدي وظائف مناعية.', 'الدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي فص من قشرة المخ يضم القشرة البصرية الأولية حول الثلم المهمازي؟', '["الفص الجبهي","الفص الصدغي","الفص القذالي","الفص الجزيري"]'::jsonb, 2, 25, 9, 'multi', 'تقع القشرة البصرية الأولية، المساحة 17، على السطح الإنسي للفص القذالي بمحاذاة الثلم المهمازي، وتستقبل مدخلات المهاد البصري عبر الإشعاع البصري. توجد مسارات معالجة بصرية لاحقة تمتد نحو الفصين الجداري والصدغي.', 'الجهاز العصبي المركزي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'لماذا يؤدي تنبيه مستقبلات بيتا-1 في خلايا العقدة الجيبية إلى تسارع معدل القلب؟', '["يفتح قنوات بوتاسيوم مرتبطة بالأستيل كولين فيفرط الاستقطاب","يثبط الأدينيلات سيكلاز ويبطئ بلوغ العتبة","يثبت جهد الغشاء عند جهد الراحة ويمنع التلقائية","يزيد cAMP وتيار If وتيارات الكالسيوم، فتزداد سرعة زوال الاستقطاب في الطور الرابع"]'::jsonb, 3, 40, 10, 'multi', 'ترتبط مستقبلات بيتا-1 ببروتين Gs فتزيد الأدينيلات سيكلاز وcAMP. ينشط ذلك مباشرة قنوات HCN الحاملة لتيار If ويعزز تيارات الكالسيوم، فتبلغ خلية الناظمة العتبة أسرع. فتح قنوات البوتاسيوم وتثبيط cAMP يميزان تأثير M2 المبهمي المعاكس.', 'الفيزيولوجيا القلبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي حدث يفسر انغلاق الصمام التاجي في بداية الانقباض البطيني الطبيعي؟', '["تجاوز ضغط الأبهر ضغط البطين الأيسر","هبوط ضغط البطين دون ضغط الأذين","انقباض العضلات الحليمية وسحب الشرفات إلى البطين","تجاوز ضغط البطين الأيسر ضغط الأذين الأيسر"]'::jsonb, 3, 35, 11, 'multi', 'الصمامات سلبية الحركة وتستجيب لفروق الضغط. حين يبدأ البطين الأيسر بالانقباض ويتجاوز ضغطه ضغط الأذين، يُدفع التاجي إلى الإغلاق مولدًا جزءًا من الصوت الأول. تمنع العضلات الحليمية والحبال انقلاب الشرفات نحو الأذين؛ ولا تغلق الصمام بسحبه.', 'ديناميكا القلب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'في الوصلة العصبية العضلية، ما التسلسل الذي يربط وصول جهد الفعل العصبي بإزالة استقطاب اللوحة النهائية؟', '["دخول Ca2+ قبل مشبكي، إفراز أستيل كولين، فتح مستقبلات نيكوتينية كاتيونية","دخول Na+ قبل مشبكي، إفراز نورإبينفرين، فتح مستقبلات بيتا","خروج Ca2+ من الليف العضلي، إفراز GABA، فتح قنوات كلوريد","تثبيط أستيل كولين إستيراز، إغلاق المستقبلات النيكوتينية، خروج Na+"]'::jsonb, 0, 40, 12, 'multi', 'يفتح جهد الفعل قنوات كالسيوم جهدية في النهاية الحركية، فيحفز اندماج الحويصلات وإطلاق الأستيل كولين. يرتبط الناقل بمستقبلات نيكوتينية عضلية فتفتح قناة كاتيونية؛ يغلب دخول الصوديوم، فينشأ جهد اللوحة النهائية الذي يطلق جهد فعل عضليًا.', 'العضلات والأعصاب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'ما الآلية التي تجعل الطرف الصاعد الغليظ لعروة هنلي جزءًا مولدًا للتدرج الأسموزي اللبي مع أنه غير منفذ للماء؟', '["يفرز اليوريا حصريًا إلى اللمعة عبر ناقل GLUT2","يعيد امتصاص Na+ وK+ وCl− عبر ناقل NKCC2 من دون أن يتبعه الماء","يعيد امتصاص الماء عبر AQP2 استجابةً للألدوستيرون","يرشح البروتينات عبر شقوق الخلايا القدمية"]'::jsonb, 1, 40, 13, 'multi', 'ينقل NKCC2 الأملاح من اللمعة في الطرف الصاعد الغليظ، بينما تكون ظهارته شبه غير منفذة للماء؛ لذلك يخف السائل الأنبوبي ويزداد أسمولال السائل الخلالي اللبي. مع الجريان المعاكس وإعادة تدوير اليوريا ينشأ تدرج يسمح للقناة الجامعة بتركيز البول عند وجود الهرمون المضاد لإدرار البول.', 'الفيزيولوجيا الكلوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'عند ارتفاع أسمولالية البلازما، كيف يزيد الهرمون المضاد لإدرار البول امتصاص الماء في القناة الجامعة؟', '["ينشط مستقبل V1 فيُدرج NKCC2 في الكبيبة","يثبط cAMP فيزيل AQP1 من الشعيرات حول النبيبية","يفتح قنوات ENaC مباشرةً في الطرف النازل الرقيق","ينشط مستقبل V2 في الخلايا الرئيسية فيُدرج قنوات AQP2 في الغشاء القِمّي"]'::jsonb, 3, 40, 14, 'multi', 'يرتبط الفازوبريسين بمستقبل V2 المقترن بـGs على الجانب القاعدي الوحشي للخلايا الرئيسية، فيرفع cAMP ويحفز إدراج حويصلات تحمل AQP2 في السطح القِمّي. يدخل الماء عبر AQP2 ويغادر نحو الدم عبر AQP3 وAQP4 القاعديتين الوحشيتين.', 'تنظيم سوائل الجسم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'لماذا يسهّل انزياح منحنى تفكك الأوكسيهيموغلوبين إلى اليمين تحرير الأكسجين في نسيج نشط استقلابيًا؟', '["لأنه يرفع ألفة الهيموغلوبين ويمنع انفصال الأكسجين","لأنه يحول الهيموغلوبين إلى ميوغلوبين","لأنه يوقف ذوبان الأكسجين في البلازما","لأنه يخفض ألفة الهيموغلوبين للأكسجين عند الضغط الجزئي نفسه"]'::jsonb, 3, 35, 15, 'multi', 'زيادة CO2 والحموضة والحرارة و2,3-BPG تثبت نسبيًا الحالة T منخفضة الألفة للهيموغلوبين. لذلك يكون التشبع أقل عند PO2 معين وتتحرر كمية أكبر من الأكسجين إلى النسيج؛ وهذا جوهر تأثير بوهر بالنسبة للحموضة وثاني أكسيد الكربون.', 'نقل الغازات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي علاقة تشريحية تفسر مرور العصب الحنجري الراجع الأيسر حول الصدر قبل صعوده إلى الحنجرة؟', '["يلتف تحت الشريان تحت الترقوة الأيمن","يلتف تحت قوس الأبهر قرب الرباط الشرياني","يعبر الثقبة الوداجية ثم يلتف حول السباتي الداخلي","يمر أمام قوس الأبهر مباشرةً من دون انعطاف"]'::jsonb, 1, 40, 16, 'multi', 'ينزل الفرع الأيسر من العصب المبهم إلى الصدر ويلتف خلفيًا تحت قوس الأبهر بجوار الرباط الشرياني، ثم يصعد في الثلم الرغامي المريئي. أما الراجع الأيمن فيلتف تحت الشريان تحت الترقوة الأيمن؛ وينشأ عدم التناظر من تطور الأقواس الشريانية وهبوط القلب.', 'تشريح الرأس والعنق والصدر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'في منعكس الشد العضلي، أي مستقبل يرصد أساسًا طول العضلة وسرعة تغيره؟', '["عضو وتر غولجي وألياف Ib فقط","جسيم باتشيني في الجلد","المغزل العضلي وأليافه الحسية Ia وII","المستقبل النيكوتيني في اللوحة النهائية"]'::jsonb, 2, 35, 17, 'multi', 'تقع الألياف داخل المغزل موازية للألياف العضلية خارج المغزل؛ لذا يتغير شد نهاياتها الحسية مع طول العضلة. تنقل Ia مكونًا ديناميكيًا قويًا وII معلومات طول ثابتة. يقع عضو وتر غولجي على التوالي مع العضلة ويرصد التوتر عبر ألياف Ib.', 'الفيزيولوجيا العصبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي طبقة من قشرة الكظر تنتج الألدوستيرون، وما المنظم الفسيولوجي الأهم لإفرازه؟', '["المنطقة الكبيبية؛ الأنجيوتنسين II وارتفاع بوتاسيوم البلازما","المنطقة الحزمية؛ الهرمون المنبه للدرقية","المنطقة الشبكية؛ الإنسولين","لب الكظر؛ الهرمون المضاد لإدرار البول"]'::jsonb, 0, 40, 18, 'multi', 'تفتقر المنطقة الكبيبية إلى إنزيم 17α-hydroxylase وتمتلك aldosterone synthase، فتنتج القشراني المعدني الألدوستيرون. ينبهها الأنجيوتنسين II والبوتاسيوم مباشرةً، بينما يؤدي ACTH دورًا ثانويًا قصير الأمد؛ وتنتج الحزمية الكورتيزول أساسًا.', 'الغدد الصماء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'كيف تمنع البطانة الوعائية السليمة تجمع الصفائح وتساعد على توسع الوعاء؟', '["تفرز الثرومبين وعامل النسيج باستمرار","تنتج أكسيد النتريك والبروستاسيكلين اللذين يثبطان الصفائح ويرخيان العضلة الملساء","تعرض الكولاجين تحت البطاني مباشرةً للدم","تحول البلازمين إلى فيبرين داخل اللمعة"]'::jsonb, 1, 40, 19, 'multi', 'ينتشر NO إلى العضلة الملساء وينشط الغوانيلات سيكلاز وcGMP، بينما يرفع البروستاسيكلين cAMP؛ وكلاهما يحد من تنشيط الصفائح ويسهم في التوسع. عند أذية البطانة ينكشف الكولاجين ويظهر عامل النسيج وتتبدل البيئة نحو الإرقاء.', 'الأوعية والإرقاء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي خاصية نسيجية تميز الحاجز الدموي الهوائي الرقيق في الأسناخ وتسمح بالانتشار السريع للغازات؟', '["تقارب ظهارة سنخية حرشفية من النمط I وبطانة شعيرية مع غشائين قاعديين ملتحمين غالبًا","ظهارة عمودية مطبقة فوق غضروف زجاجي","طبقة عضلية ملساء سميكة تفصل الهواء عن الدم","ظهارة مكعبة مهدبة متعددة الصفوف تحيط بكل شعيرة"]'::jsonb, 0, 40, 20, 'multi', 'يتكون أنحف جزء من الحاجز من السيتوبلازم الرقيق للخلية السنخية I وغشائها القاعدي الملتحم غالبًا بغشاء الخلية البطانية ثم البطانة الشعرية. يقلل ذلك مسافة الانتشار. تنتج خلايا النمط II الفاعل بالسطح ويمكنها تجديد الظهارة، لكنها ليست معظم مساحة السطح.', 'نسج الجهاز التنفسي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'في الاقتران بين الإثارة والانقباض في العضلة الهيكلية، ما الدور المباشر لمستقبلات الديهيدروبيريدين في النبيبات المستعرضة؟', '["تحلل الأستيل كولين في الشق المشبكي","تستشعر تغير الجهد وتغيّر بوابات مستقبلات الريانودين في الشبكة الساركوبلازمية ميكانيكيًا","تضخ Ca2+ من السيتوسول إلى الشبكة باستخدام ATP","ترتبط بالتروبونين C بدل الكالسيوم"]'::jsonb, 1, 40, 21, 'multi', 'يعمل Cav1.1، أو مستقبل الديهيدروبيريدين، حساسًا للجهد في غشاء النبيب T ويرتبط ميكانيكيًا بـRyR1 في الشبكة، فيفتح مخزون الكالسيوم. يرتبط Ca2+ بالتروبونين C ليزيح التروبوميوسين. تعيد مضخة SERCA الكالسيوم إلى الشبكة عند الارتخاء.', 'فيزيولوجيا العضلات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي مسار تشريحي تسلكه معظم ألياف الإحساس باللمس الدقيق والاهتزاز من الجذع قبل بلوغ القشرة؟', '["تعبر فور دخول الحبل ثم تصعد في السبيل الشوكي المهادي الأمامي","تتشابك أولًا في القرن الأمامي ثم تنزل إلى المخيخ","تصعد مماثلة الجانب في الأعمدة الخلفية، تتشابك في البصلة، ثم تعبر في الليمينسكوس الإنسي","تصعد في السبيل القشري الشوكي وتعبر في الأهرام"]'::jsonb, 2, 45, 22, 'multi', 'تدخل الألياف الأولية الأعمدة الخلفية وتصعد في الحزمتين الرشيقة والإسفينية على الجانب نفسه. تتشابك في نواتيهما بالبصلة، وتعبر محاور العصبونات الثانية كألياف مقوسة داخلية لتكوّن الليمينسكوس الإنسي نحو المهاد. يختلف ذلك عن مسار الألم والحرارة الذي يعبر شوكيًا مبكرًا.', 'المسارات العصبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'أي ترتيب صحيح لمرور الصفراء من الخلايا الكبدية نحو الاثني عشر خارج أوقات التخزين؟', '["جيبانيات كبدية ثم وريد بابي ثم قناة مرارية","قنيات صفراوية ثم قنوات داخل الكبد ثم القناتان الكبديتان فالكبدية المشتركة ثم الصفراوية المشتركة","قناة بنكرياسية ثم قناة مرارية ثم وريد كبدي","مسافة ديسه ثم الوريد المركزي ثم أمبولة فاتر"]'::jsonb, 1, 45, 23, 'multi', 'تفرز الخلايا الكبدية الصفراء إلى القنيات الواقعة بين الخلايا، وتسير بعكس اتجاه الدم نحو قنوات متزايدة الحجم ثم القناتين الكبديتين اليمنى واليسرى والكبدية المشتركة. باتحادها مع القناة المرارية تتكون القناة الصفراوية المشتركة التي تنتهي عادةً عند الحليمة الكبرى مع القناة البنكرياسية.', 'تشريح الكبد والطرق الصفراوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_46, 'كيف يحافظ المنعكس الضغطي الشرياني سريعًا على الضغط عند ارتفاعه المفاجئ لدى شخص سليم؟', '["يزيد إطلاق مستقبلات الجيب السباتي وقوس الأبهر، فيقل الخرج الودي ويزداد المبهمي","يقل إطلاق المستقبلات، فيزداد الودي وتقبض الأوعية","يزيد الرينين فورًا فيتكون أنجيوتنسين II","تنبه مستقبلات الحجم الأذينية إفراز الفازوبريسين"]'::jsonb, 0, 40, 24, 'multi', 'يمدد الضغط المرتفع مستقبلات الضغط في الجيب السباتي وقوس الأبهر، فيزداد تواترها عبر العصبين IX وX إلى النواة المفردة. تخفض المراكز البصلية النشاط الودي وتزيد النغمة المبهمية، فيتباطأ القلب ويقل التقلص وتتوسع أوعية المقاومة؛ وهو ضبط سريع لا طويل الأمد.', 'تنظيم ضغط الدم');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_47 uuid;
BEGIN
  SELECT id INTO v_lib_id_47 FROM quizzes WHERE title = 'الفيزياء النظرية والتفاعلات الكيميائية' LIMIT 1;
  IF v_lib_id_47 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الفيزياء النظرية والتفاعلات الكيميائية', 'علوم وطب', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_47;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في تجربة الشقين بإلكترونات مفردة، ما التغيير الذي يزيل نمط التداخل حتى إن لم تُقرأ نتيجة القياس لاحقًا؟', '["إتاحة معلومة قابلة للتمييز عن الشق الذي مر منه الإلكترون","خفض شدة الحزمة مع إبقاء التماسك","زيادة المسافة إلى الشاشة فقط","استبدال الشاشة بكاشف أعلى كفاءة دون كشف المسار"]'::jsonb, 0, 40, 0, 'multi', 'ينشأ التداخل من جمع سعات مسارين غير قابلين للتمييز. إذا تشابكت حالة الإلكترون مع واسم يحمل معلومة المسار، تصبح حالتا المسار قابلتين للتمييز وتضمحل الحدود التداخلية عند تجاهل الواسم؛ ليست ضرورة أن يطالع إنسان النتيجة.', 'ميكانيكا الكم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'أي تناظر مستمر يقود، وفق مبرهنة نويثر، إلى حفظ الطاقة؟', '["تناظر الدوران المكاني","تناظر الانعكاس المرآتي","ثبات قوانين النظام تحت الإزاحة الزمنية","تناظر تبديل الجسيمات المتطابقة"]'::jsonb, 2, 35, 1, 'multi', 'إذا لم يعتمد الفعل صراحة على اختيار مبدأ الزمن، أي بقي ثابتًا تحت الإزاحات الزمنية المستمرة، تعطي مبرهنة نويثر كمية محفوظة هي الطاقة. تناظر الدوران يقترن بدلًا من ذلك بحفظ الزخم الزاوي.', 'التناظرات وقوانين الحفظ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في النسبية الخاصة، حدثان متباعدان مكانيًا ولهما فاصل زمكاني شبيه بالفضاء. ما النتيجة الصحيحة؟', '["يمكن لإشارة ضوئية أن تصل بينهما","يتفق جميع المراقبين على ترتيبهما الزمني","يمكن اختيار إطار قصوري يكونان فيه متزامنين","لا يمكن أن يتغير ترتيب أي حدثين تحت تحويل لورنتز"]'::jsonb, 2, 40, 2, 'multi', 'للفاصل الشبيه بالفضاء يمكن إيجاد إطار قصوري يجعل فرق الزمن صفرًا، كما قد يختلف ترتيب الحدثين بين الأطر. ولا تستطيع إشارة سببية لا تتجاوز سرعة الضوء وصل الحدثين.', 'النسبية الخاصة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'ما الدليل التجريبي المباشر الذي أعلن مرصدا LIGO اكتشافه أول مرة عام 2016 عن حدث وقع في 2015؟', '["جسيمات غرافيتون منفردة","إشعاع هوكينغ من ثقب أسود فلكي","طاقة مظلمة متذبذبة","تموجات زمكانية من اندماج ثقبين أسودين"]'::jsonb, 3, 35, 3, 'multi', 'كانت الإشارة GW150914 موجة ثقالية ناتجة من التحام ثقبين أسودين، قيس أثرها كتغير بالغ الصغر في طولي ذراعي مقياسي التداخل. لم تكن رصدًا لكمّ منفرد من مجال الجاذبية ولا لإشعاع هوكينغ.', 'الجاذبية التجريبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في النموذج القياسي، أي حقل يمنح بوزوني W وZ كتلتيهما عبر الكسر التلقائي للتناظر الكهروضعيف؟', '["حقل هيغز","حقل الغلوون","حقل الفوتون","حقل النيوترينو"]'::jsonb, 0, 35, 4, 'multi', 'تأخذ مركبة حقل هيغز قيمة توقع فراغية غير صفرية، فتولد حدود كتلة لـW وZ مع بقاء الفوتون عديم الكتلة. اكتشاف بوزون هيغز دعم وجود الإثارة الكمية للحقل، ولا يعني أن كل كتلة المادة مصدرها الوحيد هيغز.', 'فيزياء الجسيمات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لتفاعل أولي واحد، ما أثر رفع درجة الحرارة عادة في ثابت السرعة وفق معادلة أرهينيوس إذا بقي عامل التردد وطاقة التنشيط تقريبًا ثابتين؟', '["ينخفض لأن التصادمات تصبح أقل","يبقى ثابتًا لأن ثابت السرعة لا يعتمد على الحرارة","يتغير فقط إذا كان التفاعل طاردًا للحرارة","يزداد بسبب ازدياد العامل الأسي exp(−Ea/RT)"]'::jsonb, 3, 35, 5, 'multi', 'في k=A exp(−Ea/RT)، يؤدي رفع T إلى جعل الأس السالب أقل مقدارًا، فيزداد k عادة. هذا حكم حركي ولا يعتمد في ذاته على كون التفاعل الكلي طاردًا أو ماصًا للحرارة.', 'الحركية الكيميائية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'أُضيف حفاز إلى تفاعل عكوس في وعاء مغلق عند ثبات الحرارة. أي عبارة صحيحة عند بلوغ الاتزان؟', '["يزيد ثابت الاتزان","يجعل طاقة غيبس القياسية سالبة","يرفع مردود النواتج دائمًا","يخفض طاقة تنشيط المسارين الأمامي والعكسي ويسرّع بلوغ الاتزان دون تغيير موضعه"]'::jsonb, 3, 35, 6, 'multi', 'يوفر الحفاز مسارًا بديلًا أقل حاجزًا للتفاعل في الاتجاهين، فيسرع الوصول إلى الاتزان. أما ثابت الاتزان وموضعه فيحددهما الديناميكا الحرارية ودرجة الحرارة، فلا يغيرهما الحفاز.', 'الحفز والاتزان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لتفاعل عند ثبوت الضغط والحرارة، ماذا يعني أن ΔG للتغير المحدد سالبة؟', '["أن التفاعل سريع حتمًا","أن الاتجاه الأمامي مفضل ترموديناميكيًا للتراكيب الحالية، دون تحديد سرعته","أن التفاعل طارد للحرارة حتمًا","أن النظام بلغ الاتزان"]'::jsonb, 1, 35, 7, 'multi', 'تشير ΔG السالبة إلى إمكانية التقدم التلقائي في الاتجاه الأمامي عند الشروط والتركيب الحاليين. لكنها لا تصف حاجز التنشيط، ولذلك قد يكون التفاعل بطيئًا جدًا؛ وعند الاتزان تكون ΔG للتقدم التفاضلي صفرًا.', 'الديناميكا الحرارية الكيميائية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في منحنى طاقة الوضع لتفاعل أولي، ما الذي تمثله الحالة الانتقالية؟', '["نوعًا مستقرًا يمكن عزله دائمًا","أعلى نقطة على مسار أقل طاقة بين حوضي المتفاعلات والنواتج","أدنى نقطة بين المتفاعلات والنواتج","النواتج بعد اكتمال الاتزان"]'::jsonb, 1, 40, 8, 'multi', 'الحالة الانتقالية بنية حرجة عند قمة حاجز الطاقة على إحداثي التفاعل، ولها اتجاه واحد غير مستقر نحو المتفاعلات أو النواتج. تختلف عن الوسيط الذي يقع عند حد أدنى محلي وقد يمتلك عمرًا قابلًا للقياس.', 'آليات التفاعل');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في تفاعل أكسدة واختزال، ما الوصف الصحيح للعامل المؤكسد؟', '["يفقد إلكترونات ويُختزل","يكتسب بروتونات فقط ولا تتغير حالة أكسدته","يخفض طاقة التنشيط دون أن يُستهلك","يكتسب إلكترونات ويُختزل"]'::jsonb, 3, 30, 9, 'multi', 'العامل المؤكسد يؤكسد النوع الآخر بقبول إلكتروناته، ولذلك يتعرض هو للاختزال وتنخفض حالة أكسدته. أما النوع الذي يمنح الإلكترونات فهو العامل المختزل ويتأكسد.', 'الكيمياء الكهربية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لماذا لا تسمح نظرية بيل بإبقاء كل من المحلية والواقعية المحددة مسبقًا مع إعادة إنتاج جميع تنبؤات ميكانيكا الكم؟', '["لأن مبدأ عدم اليقين يمنع أي قياس متزامن","لأن التشابك يرسل رسائل أسرع من الضوء","لأن نظريات المتغيرات الخفية المحلية تخضع لمتباينات تنتهكها ترابطات كمومية مقاسة","لأن معادلة شرودنغر غير خطية"]'::jsonb, 2, 55, 10, 'multi', 'اشتق بيل قيودًا إحصائية تحققها فئة النظريات ذات المتغيرات الخفية المحلية. تنتهك التجارب الملائمة هذه القيود بما يوافق الكم؛ لكن الترابط غير المحلي لا يتيح وحده إرسال معلومات قابلة للتحكم أسرع من الضوء.', 'أسس ميكانيكا الكم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في نظرية الحقول الكمية، ماذا يعني أن اقترانًا «يجري» مع مقياس الطاقة؟', '["أن ثابت الاقتران يتغير مع مقياس إعادة التطبيع بسبب التقلبات الكمية","أن الشحنة الكهربائية لا تُحفظ","أن سرعة الضوء تعتمد على طاقة الجسيم","أن قيمة الاقتران تتذبذب دوريًا مع الزمن المختبري"]'::jsonb, 0, 50, 11, 'multi', 'تصف مجموعة إعادة التطبيع اعتماد المعلمات الفعالة، ومنها الاقتران، على مقياس الطاقة الذي تُفحص عنده العملية. يعكس ذلك تأثير استقطاب الفراغ والتقلبات الافتراضية، ولا يعني خرق حفظ الشحنة.', 'نظرية الحقول الكمية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'ما الخاصية المميزة للحرية التقاربية في الديناميكا اللونية الكمية QCD؟', '["يزداد الاقتران القوي بلا حد عند الطاقات العالية","تصبح الغلوونات عديمة التفاعل عند جميع الطاقات","يضعف الاقتران القوي عند المسافات القصيرة أو انتقال الزخم الكبير","تتحول الكواركات إلى جسيمات عديمة الكتلة حتمًا"]'::jsonb, 2, 50, 12, 'multi', 'إشارة دالة بيتا في QCD تجعل الاقتران الفعال أصغر عند مقاييس الطاقة العالية، فيمكن استخدام الاضطراب لوصف التصادمات الصلبة. لا ينفي ذلك الحصر عند المقاييس المنخفضة، ولا يجعل التفاعل منعدمًا تمامًا.', 'الديناميكا اللونية الكمية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'أي رصد يثبت أن النيوترينوات ذات النكهات المختلفة لا يمكن أن تكون جميعها حالات كتلة متطابقة عديمة الكتلة؟', '["تذبذب النيوترينو مع المسافة والطاقة","إنتاج أزواج إلكترون-بوزيترون","انحلال البروتون","حيود النيوترونات البلوري"]'::jsonb, 0, 45, 13, 'multi', 'يتطلب تغير احتمال النكهة فروقًا في مربعات كتل حالات الانتشار ومزجًا غير صفري بينها. تقيس تجارب التذبذب هذه الفروق، لكنها لا تحدد وحدها الكتلة المطلقة لكل نيوترينو.', 'فيزياء النيوترينو');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في النسبية العامة، ماذا يقرر مبدأ التكافؤ محليًا لمراقب في سقوط حر ضمن مجال جاذبية منتظم تقريبًا؟', '["يمكن جعل قوانين الفيزياء محليًا شبيهة بإطار قصوري، مع بقاء التأثيرات المدّية المرتبطة بالانحناء","يمكن إزالة جميع آثار الجاذبية عبر منطقة ممتدة مهما كان انحناؤها","تختفي الجاذبية عالميًا بتغيير الإحداثيات","تتساوى كل الحقول الجاذبية في شدتها"]'::jsonb, 0, 50, 14, 'multi', 'يمكن في جوار صغير لمراقب ساقط حر اختيار إطار محلي قصوري تزول فيه عجلة الجاذبية المنتظمة. لكن مشتقات المجال، أي قوى المد والجزر التي يقيسها انحناء ريمان، لا يمكن حذفها على منطقة منتهية إذا كان الزمكان منحنيًا.', 'النسبية العامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'أي عبارة تميز أفق الحدث عن التفرد في حل شفارزشيلد المثالي؟', '["كلاهما تفرد انحناء فيزيائي","الأفق سطح مادي صلب","التفرد يقع دائمًا خارج الأفق","أفق الحدث حد سببي قد يكون منتظمًا محليًا، بينما يتباعد الانحناء عند التفرد المركزي"]'::jsonb, 3, 50, 15, 'multi', 'اللانهاية الظاهرية في إحداثيات شفارزشيلد عند الأفق أثر إحداثي يزول بإحداثيات ملائمة، ويمكن للعابر ألا يلحظ ظاهرة محلية خاصة هناك. أما r=0 في الحل الكلاسيكي فيتميز بتباعد ثوابت الانحناء ويمثل تفردًا حقيقيًا.', 'الثقوب السوداء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في نموذج التضخم الكوني البطيء، ما الدور النظري الأساسي لمرحلة التمدد شبه الأسي؟', '["إنتاج العناصر الثقيلة داخل النجوم","جعل مناطق كانت متصلة سببيًا تتمدد إلى مقاييس كونية وتوليد بذور اضطرابات من تقلبات كمية","إثبات أن الكون بدأ من لا شيء","إلغاء الحاجة إلى المادة المظلمة تجريبيًا"]'::jsonb, 1, 55, 16, 'multi', 'يمدد التضخم رقعة صغيرة متجانسة سببيًا إلى حجم هائل، فيعالج مشكلة الأفق ضمن النموذج، كما يمد تقلبات كمية أولية لتصبح بذور بنية واسعة النطاق. هذه آلية نموذجية تدعمها بصمات رصدية، وليست رصدًا مباشرًا لحقل تضخم بعينه.', 'علم الكون النظري');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لماذا يُعد إشعاع الجسم الأسود حاسمًا تاريخيًا لنشأة التكميم؟', '["لأن قانون رايلي–جينز الكلاسيكي يؤدي إلى كارثة فوق بنفسجية، بينما افترض بلانك تبادل الطاقة بحزم","لأن الفيزياء الكلاسيكية تنبأت بطيف مطابق تمامًا","لأنه أثبت وجود النيوترينو","لأنه قاس انحناء الزمكان"]'::jsonb, 0, 45, 17, 'multi', 'يؤدي توزيع تساوي الطاقة الكلاسيكي إلى كثافة طاقة تتباعد عند الترددات العالية، خلاف القياس. أعاد قانون بلانك إنتاج الطيف بافتراض عناصر طاقة تتناسب مع التردد، فكان خطوة تأسيسية نحو نظرية الكم.', 'نشأة نظرية الكم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لتفاعل مركب، لماذا لا يجوز عادة استنتاج قانون السرعة من المعادلة الكيميائية الإجمالية الموزونة وحدها؟', '["لأن حفظ الكتلة لا ينطبق على الآليات","لأن معاملات المعادلة الإجمالية لا تكشف الخطوات الأولية ولا الخطوة المحددة للسرعة","لأن رتبة كل تفاعل تساوي صفرًا","لأن ثابت الاتزان يساوي ثابت السرعة"]'::jsonb, 1, 45, 18, 'multi', 'تختزل المعادلة الإجمالية وسائط وخطوات قد تتحكم في السرعة، لذا يحدد قانون السرعة تجريبيًا أو يشتق من آلية متسقة. فقط في خطوة أولية يمكن ربط الأسس عادة بالستوكيومترية الجزيئية لتلك الخطوة.', 'حركية الآليات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في تقريب الحالة المستقرة لوسيط تفاعلي قصير العمر، ما الفرض المستخدم بعد طور ابتدائي وجيز؟', '["تركيز الوسيط يساوي صفرًا تمامًا","الوسيط في اتزان حراري مع النواتج دائمًا","كل خطوة في الآلية لها ثابت السرعة نفسه","معدل تكوّن الوسيط يقارب معدل استهلاكه، فيكون مشتق تركيزه الزمني قريبًا من الصفر"]'::jsonb, 3, 50, 19, 'multi', 'لا يفترض التقريب غياب الوسيط، بل ثبات تركيزه تقريبًا لأن إنتاجه واستهلاكه يتوازنان حركيًا خلال معظم المسار. وهو مختلف عن فرض الاتزان المسبق الذي يشترط اتزان خطوة عكوسة سريعة.', 'الحركية المتقدمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في نظرية ماركوس لانتقال الإلكترون، ماذا تتنبأ «المنطقة المعكوسة» عندما تصبح القوة الدافعة الطاردة كبيرة جدًا؟', '["يزداد معدل الانتقال إلى ما لا نهاية","قد ينخفض معدل انتقال الإلكترون رغم ازدياد طردية التفاعل","تختفي طاقة إعادة التنظيم","يتحول انتقال الإلكترون إلى تفاعل نووي"]'::jsonb, 1, 55, 20, 'multi', 'تعتمد طاقة التنشيط في نموذج ماركوس على القوة الدافعة وطاقة إعادة التنظيم. بعد النقطة المثلى، يؤدي جعل ΔG أكثر سلبية إلى زيادة الحاجز مجددًا وانخفاض المعدل؛ وقد رُصد هذا السلوك في أنظمة انتقال إلكتروني ملائمة.', 'انتقال الإلكترون');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'وفق مبدأ هاموند، إذا كانت خطوة أولية شديدة الطرد للحرارة، إلى أي طرف تميل بنية حالتها الانتقالية أن تكون أقرب؟', '["النواتج لأنها الأكثر استقرارًا","وسيط منفصل لا علاقة له بالطرفين","المتفاعلات لأن الحالة الانتقالية المبكرة أقرب طاقة وبنية إليها","لا يمكن للمبدأ أن يقدم أي توقع نوعي"]'::jsonb, 2, 50, 21, 'multi', 'يربط مبدأ هاموند تشابه البنية بقرب الطاقة: في خطوة طاردة للحرارة تكون الحالة الانتقالية عادة مبكرة وأقرب في الطاقة والبنية إلى المتفاعلات. هذا استدلال نوعي وليس تصويرًا مباشرًا لبنية الحالة الانتقالية.', 'الكيمياء الفيزيائية العضوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في تفاعل بيريسايكلي حراري، على ماذا تعتمد قواعد وودورد–هوفمان في تقرير المسار المسموح تناظريًا؟', '["حفظ تناظر المدارات الجزيئية المشغولة أثناء التحول المتضافر","قيمة pH وحدها","وجود جذور حرة في كل الحالات","كون التفاعل طاردًا للحرارة فقط"]'::jsonb, 0, 55, 22, 'multi', 'تصنف القواعد المسارات المتضافرة بحسب إمكان استمرار الترابط المداري دون تقاطعات محرمة تناظريًا، مع اختلاف النتيجة بين الإثارة الحرارية والضوئية. السماح التناظري لا يضمن وحده سرعة عالية أو مردودًا مرتفعًا.', 'التفاعلات البيريسايكلية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'لماذا قد يكون نفق البروتون مهمًا في بعض التفاعلات حتى عند طاقات أقل من قمة الحاجز الكلاسيكي؟', '["لأن البروتون لا يمتلك كتلة","لأن دالة موجته قد تنفذ عبر حاجز محدود، ويزداد الأثر عادة للجسيم الأخف والحاجز الأضيق","لأن حفظ الطاقة يُخرق مؤقتًا","لأن النفق يزيل حاجز الطاقة من سطح الوضع"]'::jsonb, 1, 50, 23, 'multi', 'يعطي الوصف الكمي احتمال نفاذ غير صفري عبر حاجز محدود دون أن يمتلك الجسيم طاقة كلاسيكية تتجاوز قمته. حساسية الاحتمال للكتلة وعرض الحاجز تفسر آثار النظائر الحركية الكبيرة أحيانًا، مع بقاء حفظ الطاقة قائمًا.', 'الحركية الكمية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_47, 'في حسابات نظرية دالة الكثافة DFT، ما العبارة الأدق عن مبرهنتي هوهنبرغ–كوهن؟', '["تقدمان الصيغة الدقيقة العامة الواضحة لدالة التبادل والارتباط","تثبتان أن جميع الحالات المثارة تحسب بلا تقريب","تقرران أن كثافة الحالة الأرضية تحدد الجهد الخارجي وخواص الحالة الأرضية، لكن التقريبات العملية للدالة تبقى ضرورية","تلغيان تآثر الإلكترونات وتحولان النظام إلى غاز مثالي"]'::jsonb, 2, 60, 24, 'multi', 'تؤسس المبرهنتان أن كثافة الحالة الأرضية متغير كافٍ من حيث المبدأ وأن الطاقة تبلغ حدها الأدنى عند الكثافة الصحيحة. لكنهما لا توفران الشكل العملي الدقيق لدالة التبادل والارتباط؛ لذلك تعتمد نتائج DFT الحسابية على اختيار تقريبها والتحقق من ملاءمته.', 'الكيمياء الكمومية');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_48 uuid;
BEGIN
  SELECT id INTO v_lib_id_48 FROM quizzes WHERE title = 'بلاغة وإعراب وشعر جاهلي' LIMIT 1;
  IF v_lib_id_48 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('بلاغة وإعراب وشعر جاهلي', 'لغة عربية وأدب', '', 'medium_high', 'ar', true)
    RETURNING id INTO v_lib_id_48;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قول امرئ القيس: «وليلٍ كموج البحر أرخى سدوله»، ما الصورة البيانية في تشبيه الليل بموج البحر؟', '["استعارة مكنية","تشبيه بليغ","تشبيه مرسل مجمل","كناية عن صفة"]'::jsonb, 2, 30, 0, 'multi', 'ذُكرت أداة التشبيه «الكاف»، فالتشبيه مرسل، وحُذف وجه الشبه، فهو مجمل. والمشبَّه الليل والمشبَّه به موج البحر في تراكب ظلمته وهوله.', 'علم البيان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في الجملة «رأيتُ أسدًا يحمل سيفًا في المعركة»، والمراد رجل شجاع، ما نوع المجاز؟', '["استعارة تصريحية","استعارة مكنية","مجاز مرسل بعلاقة الجزئية","كناية عن موصوف"]'::jsonb, 0, 25, 1, 'multi', 'شُبّه الرجل الشجاع بالأسد، ثم حُذف المشبَّه وصرّح بلفظ المشبَّه به «أسد»، ولذلك فهي استعارة تصريحية، والقرينة المانعة من إرادة الحيوان حمل السيف في المعركة.', 'علم البيان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في العبارة «فلان كثير الرماد» عند إرادة وصفه بالكرم، كيف يصنفها علم البيان؟', '["كناية عن موصوف","مجاز مرسل سببي","استعارة تمثيلية","كناية عن صفة"]'::jsonb, 3, 25, 2, 'multi', 'كثرة الرماد دليل على كثرة إيقاد النار للطبخ وكثرة الضيوف، فينتقل الذهن منها إلى صفة الكرم مع جواز المعنى الأصلي؛ لذا فهي كناية عن صفة.', 'علم البيان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'ما إعراب «العلمَ» في قولنا: «إنَّ العلمَ نورٌ»؟', '["خبر إن منصوب","اسم إن منصوب","مبتدأ مرفوع","مفعول به منصوب"]'::jsonb, 1, 20, 3, 'multi', '«إنَّ» من الحروف الناسخة التي تنصب الاسم وترفع الخبر؛ فـ«العلمَ» اسمها منصوب بالفتحة، و«نورٌ» خبرها مرفوع.', 'النواسخ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «كان الجوُّ معتدلًا»، ما الوظيفة الإعرابية لكلمة «معتدلًا»؟', '["خبر كان منصوب","حال منصوب","مفعول به ثانٍ","تمييز منصوب"]'::jsonb, 0, 20, 4, 'multi', '«كان» فعل ناقص يرفع الاسم وينصب الخبر؛ فـ«الجوُّ» اسم كان مرفوع، و«معتدلًا» خبرها منصوب.', 'النواسخ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «جاء الطالبان كلاهما»، ما إعراب «كلاهما» إذا أريد بها توكيد الطالبين؟', '["بدل منصوب بالياء","حال مرفوعة بالألف","فاعل ثانٍ مرفوع","توكيد معنوي مرفوع بالألف وهو مضاف"]'::jsonb, 3, 30, 5, 'multi', '«كلا» من ألفاظ التوكيد المعنوي إذا أضيفت إلى ضمير يطابق المؤكَّد. وهي هنا تابعة لـ«الطالبان» في الرفع، وعلامة رفعها الألف لأنها ملحقة بالمثنى، و«هما» مضاف إليه.', 'التوابع');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'أي بيت يفتتح به امرؤ القيس معلقته؟', '["أمِن أمِّ أوفى دمنةٌ لم تكلَّمِ","هل غادر الشعراء من متردَّمِ","لخولة أطلالٌ ببرقة ثهمدِ","قِفا نبكِ من ذكرى حبيبٍ ومنزلِ"]'::jsonb, 3, 25, 6, 'multi', 'معلقة امرئ القيس تفتتح بـ«قفا نبك من ذكرى حبيب ومنزلِ». أما الأبيات الأخرى فهي مطالع معلقات زهير وعنترة وطرفة على الترتيب.', 'الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'من قائل البيت الجاهلي: «هل غادر الشعراء من متردَّمِ أم هل عرفت الدار بعد توهُّمِ»؟', '["عنترة بن شداد","زهير بن أبي سلمى","لبيد بن ربيعة","الحارث بن حلزة"]'::jsonb, 0, 25, 7, 'multi', 'البيت مطلع معلقة عنترة بن شداد. و«المتردَّم» الموضع المسترقع أو المستصلح، وفي المطلع تساؤل عن بقاء معنى لم يسبق الشعراء إليه.', 'الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'أي غرض يهيمن على مقطع زهير: «ومن لا يَذُدْ عن حوضه بسلاحه يُهدَّمْ، ومن لا يَظلم الناس يُظلمِ»؟', '["النسيب ووصف المحبوبة","الاعتذار إلى الملك","الحكمة المستخلصة من خبرة الحرب والمجتمع","وصف الناقة في الرحلة"]'::jsonb, 2, 30, 8, 'multi', 'ينتمي البيت إلى سلسلة حكم في معلقة زهير تصوغ خبرته بطباع الناس والحرب في قضايا شرطية عامة، وليس إلى النسيب أو الرحلة أو الاعتذار.', 'أغراض الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قول لبيد: «ألا كلُّ شيءٍ ما خلا اللهَ باطلٌ»، ما إعراب لفظ الجلالة على الوجه الذي تكون فيه «خلا» فعلًا؟', '["مفعول به منصوب","مستثنى مجرور","فاعل مرفوع","بدل مرفوع"]'::jsonb, 0, 30, 9, 'multi', 'إذا عُدّت «خلا» فعلًا ماضيًا للاستثناء كان فاعلها ضميرًا مستترًا، ونُصب ما بعدها مفعولًا به؛ لذلك جاء «اللهَ» منصوبًا. أما الجر فيكون عند عدّ «خلا» حرف جر.', 'الاستثناء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قول امرئ القيس: «مِكرٍّ مِفرٍّ مُقبلٍ مُدبرٍ معًا كجلمودِ صخرٍ حطَّه السيلُ من علِ»، ما سر التشبيه في الشطر الثاني؟', '["تشبيه لون الفرس بلون الصخر فقط","تمثيل هيئة الفرس في سرعة اندفاعه وصلابته بهيئة صخرة يهوي بها السيل","كناية عن بطء الفرس وثقله","مجاز مرسل علاقته المحلية"]'::jsonb, 1, 40, 10, 'multi', 'وجه الشبه هيئة منتزعة من أمور: سرعة الانقضاض وقوة الاندفاع واجتماع الحركة والصلابة، لا صفة مفردة كاللون؛ ولذلك يقرأ تشبيهًا تمثيليًا يبرز حركة الفرس.', 'التشبيه التمثيلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «ما محمدٌ إلا رسولٌ»، أي مسلك بلاغي حقق القصر؟', '["إنما","النفي والاستثناء","تقديم ما حقه التأخير","العطف بـ«بل»"]'::jsonb, 1, 35, 11, 'multi', 'اجتمع النفي بـ«ما» والاستثناء بـ«إلا»، فقُصر محمد على الرسالة في سياق رد ما قد يتوهم من الخلود. هذا أحد طرق القصر الاصطلاحية، وهو غير القصر بـ«إنما» أو التقديم.', 'علم المعاني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قولنا «إياك نعبد»، ما الدلالة البلاغية الأصلية لتقديم المفعول «إياك» على فعله؟', '["مجرد مراعاة السجع","تحويل الخبر إلى إنشاء طلبي","إفادة الشك في وقوع العبادة","الاختصاص والقصر بحسب المقام"]'::jsonb, 3, 35, 12, 'multi', 'تقديم المعمول الذي حقه التأخير يفيد الاختصاص في هذا المقام: نخصك بالعبادة ولا نعبد غيرك. فالقيمة ناشئة من ترتيب أجزاء الكلام ومقتضى الحال، لا من السجع.', 'التقديم والتأخير');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «زيدٌ طويلُ النجاد» إذا أريد طول قامته، ما سبب عدّ التعبير كناية لا مجازًا مانعًا من الحقيقة؟', '["لأن لفظ النجاد استُعمل في غير معناه مع قرينة مانعة","لأن المشبه به مذكور والمشبه محذوف","لأن طول النجاد يمكن أن يكون حقيقيًا مع الانتقال منه إلى طول القامة","لأن العلاقة بين اللفظ والمعنى هي الكلية"]'::jsonb, 2, 40, 13, 'multi', 'من فارق الكناية عن المجاز أن إرادة لازم المعنى لا تمنع جواز المعنى الأصلي. فطول حمائل السيف قد يتحقق حقيقة، ويُستدل به على طول القامة؛ فلا توجد قرينة مانعة من الحقيقة كما في المجاز.', 'الكناية والمجاز');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قولهم «بنى الأميرُ المدينةَ» إذا كان الآمر بالبناء لا المباشر له، ما علاقة المجاز العقلي؟', '["الإسناد إلى الزمان","الإسناد إلى المكان","الإسناد إلى السببية","المجاز المرسل بعلاقة الجزئية"]'::jsonb, 2, 40, 14, 'multi', 'الفعل أُسند إلى الأمير لأنه سبب البناء بأمره وتمويله، مع أن العمال باشروا الفعل؛ فالمجاز في الإسناد وعلاقته السببية، ولذلك يسمى مجازًا عقليًا.', 'المجاز العقلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في الجملة «ما جاءني من أحدٍ»، ما الوظيفة النحوية لـ«من» وما أثرها في «أحد»؟', '["حرف جر زائد للتوكيد، و«أحد» فاعل مجرور لفظًا مرفوع محلًا","حرف جر أصلي، و«أحد» مفعول به","اسم شرط جازم، و«أحد» مبتدأ","حرف تبعيض، و«أحد» بدل"]'::jsonb, 0, 45, 15, 'multi', 'تزاد «من» بعد نفي وقبل نكرة لتأكيد الاستغراق. و«أحد» هو الذي أسند إليه المجيء، فهو فاعل في المحل، لكنه مجرور في اللفظ بـ«من» الزائدة.', 'حروف الجر الزائدة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «إنْ تدرسْ تنجحْ»، ما الإعراب الأدق للفعلين؟', '["«تدرسْ» فعل الشرط مجزوم، و«تنجحْ» جوابه مجزوم","كلاهما منصوب بأن مضمرة","الأول مجزوم والثاني مرفوع للاستئناف","الأول مرفوع والثاني مجزوم في جواب الطلب"]'::jsonb, 0, 35, 16, 'multi', '«إنْ» حرف شرط جازم يجزم فعلين مضارعين: الأول فعل الشرط والثاني جوابه وجزاؤه؛ وعلامة الجزم في كليهما السكون لصحّة الآخر.', 'الشرط والجزم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «لا طالبَ علمٍ مهملٌ»، كيف يعرب التركيب «طالبَ علمٍ»؟', '["اسم لا مبني على الفتح و«علمٍ» نعت","مبتدأ منصوب و«علمٍ» تمييز","منادى مضاف و«علمٍ» مجرور","اسم لا منصوب وهو مضاف، و«علمٍ» مضاف إليه"]'::jsonb, 3, 40, 17, 'multi', 'اسم «لا» النافية للجنس إذا كان مضافًا يكون معربًا منصوبًا، لا مبنيًا على ما ينصب به. لذا «طالبَ» اسم لا منصوب وهو مضاف، و«علمٍ» مضاف إليه، و«مهملٌ» خبر لا.', 'لا النافية للجنس');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «يا طالبًا علمًا، اجتهد»، لماذا نُصب «طالبًا» ونُوِّن؟', '["لأنه منادى علم مفرد مبني على الضم","لأنه منادى شبيه بالمضاف عمل فيما بعده","لأنه مفعول به لفعل النداء المحذوف فقط ولا صلة له بما بعده","لأنه مستغاث به مجرور"]'::jsonb, 1, 40, 18, 'multi', '«طالبًا» اسم فاعل اتصل به معموله «علمًا»، فشابه المضاف من غير إضافة صريحة. والمنادى الشبيه بالمضاف منصوب منون، بخلاف العلم المفرد والنكرة المقصودة اللذين يبنيان على ما يرفعان به.', 'النداء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «أعجبني الطالبُ خُلُقُه»، ما نوع البدل في «خُلُقُه»؟', '["بدل بعض من كل","بدل اشتمال","بدل كل من كل","بدل مباين"]'::jsonb, 1, 40, 19, 'multi', 'الخُلُق معنى يشتمل عليه الطالب وليس جزءًا ماديًا منه، والضمير في «خلقه» رابط يعود إلى المبدل منه؛ لذلك هو بدل اشتمال لا بدل بعض من كل.', 'البدل');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في «لولا العلمُ ما تقدمت الأمم»، لماذا جاء الاسم بعد «لولا» مرفوعًا؟', '["لأنه فاعل لفعل محذوف","لأنه اسم لولا مرفوع على عملها كـ«كان»","لأنه مبتدأ خبره محذوف وجوبًا تقديره موجود","لأنه بدل من ضمير مستتر"]'::jsonb, 2, 45, 20, 'multi', '«لولا» الامتناعية تدخل على جملة اسمية؛ فالاسم بعدها مبتدأ، ويُحذف خبره العام وجوبًا، ويقدّر «موجود» أو «حاصل». ولا تعمل «لولا» في الاسم عمل الأفعال الناسخة.', 'الأدوات والجمل');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في مطلع معلقة زهير «أمِن أمِّ أوفى دِمنةٌ لم تكلَّمِ»، ما المقصود بـ«الدِّمنة» في سياق الوقوف على الأطلال؟', '["سحابة ممطرة فوق الحي","ناقة سريعة في الرحلة","ساحة الحرب بعد انقضائها","آثار الدار وما سوّدته وبقي من حطامها"]'::jsonb, 3, 40, 21, 'multi', 'الدِّمنة أثر الدار وما اسودّ من البعر والرماد ونحوهما بعد رحيل أهلها. لذلك خاطب زهير آثار منزل أم أوفى في تقليد الوقوف على الطلل.', 'لغة الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في معلقة طرفة: «ستُبدي لك الأيامُ ما كنتَ جاهلًا ويأتيك بالأخبار من لم تُزوِّدِ»، ما الفكرة التي يقررها البيت؟', '["لا يُقبل الخبر إلا من رسول مزوّد بالمال","تكشف الأيام المجهول، وقد يأتي الخبر ممن لم تكلّفه أو تهيئه لذلك","السفر يمنع وصول الأخبار الصحيحة","العلم بالمستقبل مقصور على الشاعر"]'::jsonb, 1, 40, 22, 'multi', 'يصوغ طرفة حكمة في انكشاف الخفي بمرور الزمن؛ و«من لم تزود» هو من لم ترسله ولم تمنحه زادًا ليأتيك بالخبر، ومع ذلك يحمله إليك.', 'حكمة الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قول عمرو بن كلثوم: «ألا لا يجهلنْ أحدٌ علينا فنجهلَ فوق جهل الجاهلينا»، ما توجيه نصب «نجهلَ»؟', '["مجزوم عطفًا على «يجهلن»","مرفوع لأنه مستأنف","منصوب بأن مضمرة وجوبًا بعد فاء السببية الواقعة في جواب النهي","منصوب على أنه مفعول به"]'::jsonb, 2, 45, 23, 'multi', 'سبق الفاء نهيٌ محض في «لا يجهلن»، وجاء المضارع بعدها مسببًا عنه؛ فينصب بـ«أن» مضمرة وجوبًا بعد فاء السببية. لذلك ففتحة «نجهلَ» علامة نصب لا جزم.', 'نصب المضارع');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_48, 'في قول النابغة الذبياني: «فإنك كالليل الذي هو مُدركي وإن خِلتُ أن المنتأى عنك واسعُ»، ما وظيفة التشبيه في سياق الاعتذار؟', '["وصف سواد لون الممدوح","تصوير حتمية بلوغ سلطان الممدوح للشاعر كما يدرك الليل كل هارب","التغزل بليل هادئ بعيد عن الخوف","إثبات أن الشاعر أسرع من الليل"]'::jsonb, 1, 45, 24, 'multi', 'يشبه النابغة النعمان بالليل في إحاطة سلطانه وحتمية إدراكه؛ فمهما ظن الشاعر أن البعد واسع فلن يفلت. يخدم التشبيه الاعتذار بإظهار هيبة المخاطب وعجز الشاعر عن الفرار.', 'الشعر الجاهلي والبلاغة');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_49 uuid;
BEGIN
  SELECT id INTO v_lib_id_49 FROM quizzes WHERE title = 'غريب الألفاظ والمذاهب الأدبية' LIMIT 1;
  IF v_lib_id_49 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('غريب الألفاظ والمذاهب الأدبية', 'لغة عربية وأدب', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_49;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'في قول امرئ القيس «وجيدٍ كجيدِ الرئمِ ليس بفاحشٍ»، ما الرئم؟', '["صغير النعام","الثور الوحشي","الوعل طويل القرنين","الظبي الأبيض الخالص البياض"]'::jsonb, 3, 35, 0, 'multi', 'الرِّئم في المعاجم الظبي الأبيض الخالص البياض؛ ومن ثم شبّه امرؤ القيس جيد محبوبته بجيد الظبي، لا بالنعام أو الوعل.', 'غريب الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'ما معنى «السُّرى» في قولهم: سَرَوا من آخر الليل؟', '["الراحة عند الظهيرة","السير ليلًا","السير أول النهار","الإقامة في المنزل"]'::jsonb, 1, 30, 1, 'multi', 'السُّرى هو سير عامة الليل أو بعضه، والفعل سَرَى وأسرى يدل على السير ليلًا؛ فلا يعني القيلولة أو البكور.', 'غريب الألفاظ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'إذا وُصف الرجل في العربية القديمة بأنه «أشمط»، فأي صفة غلبت على شعره؟', '["شدة الجعودة","اختلاط البياض بالسواد","الطول حتى المنكبين","الحمرة الخالصة"]'::jsonb, 1, 30, 2, 'multi', 'الشَّمَط بياض شعر الرأس يخالط سواده؛ ولذلك فالأشمط ليس من ابيض شعره كله، بل من اختلط بياضه بسواده.', 'صفات عربية قديمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي وصف يطابق «الهَزِيع» في الاستعمال العربي القديم؟', '["طائفة من الليل","أول ضوء من الفجر","حرّ منتصف النهار","مطر قصير عند الغروب"]'::jsonb, 0, 35, 3, 'multi', 'الهزيع طائفة أو نحو ثلث من الليل؛ ولذلك يقال هزيع من الليل، ولا يراد به الفجر نفسه ولا وقت الظهيرة.', 'ألفاظ الزمن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي سمة جعلها كتّاب الواقعية في القرن التاسع عشر محورًا مقابل النزعة الرومانسية؟', '["تمثيل الحياة اليومية والوسط الاجتماعي تمثيلًا تفصيليًا","إحياء الأسطورة وحدها ورفض المجتمع","إلغاء السببية من السرد","حصر الأدب في الاعتراف الذاتي الغنائي"]'::jsonb, 0, 35, 4, 'multi', 'سعت الواقعية إلى تقديم الحياة المعاصرة العادية وبيئاتها الاجتماعية بتفصيل وملاحظة، في ابتعاد عن التخييل الرومانسي المثالي أو الغنائي الخالص.', 'المذاهب الأدبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'ما المبدأ الذي يدل عليه شعار البرناسية «الفن للفن» في صورته الأساسية؟', '["إخضاع القصيدة للدعاية السياسية","تسجيل اللاوعي بالكتابة الآلية","محاكاة الوثيقة العلمية بلا عناية بالشكل","استقلال القيمة الجمالية عن الوعظ والمنفعة المباشرة"]'::jsonb, 3, 35, 5, 'multi', 'أكد البرناسيون الصنعة والانضباط الشكلي واستقلال الفن، فرفضوا قياس القصيدة بمنفعتها الأخلاقية أو السياسية المباشرة.', 'المذاهب الأدبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي اقتران يصف جماعة «الديوان» في النقد العربي الحديث؟', '["شوقي وحافظ ومطران، مع الالتزام بالمحاكاة الكلاسيكية","نعيمة وجبران وأبو ماضي، بوصفهم جماعة مصرية","العقاد والمازني وشكري، مع الدعوة إلى الوحدة العضوية والصدق النفسي","السياب ونازك والبياتي، بوصفهم مدرسة نثرية"]'::jsonb, 2, 40, 6, 'multi', 'تُنسَب جماعة الديوان إلى عباس محمود العقاد وإبراهيم المازني وعبد الرحمن شكري، ودعت إلى صدق التجربة ووحدة القصيدة العضوية في مواجهة التقليد.', 'مدارس الأدب العربي الحديث');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'في المصطلح النقدي، ماذا يميز «تيار الوعي»؟', '["تمثيل تدفق الإدراك والأفكار والانطباعات الداخلية للشخصية","ترتيب الأحداث زمنيًا بلسان مؤرخ محايد","اقتصار السرد على الحوار المسرحي","إخفاء العالم النفسي والاكتفاء بوصف المكان"]'::jsonb, 0, 35, 7, 'multi', 'تيار الوعي تقنية تسعى إلى محاكاة الحركة المتصلة للوعي بما فيها الخواطر والإحساسات والذكريات، وقد تستعمل المونولوج الداخلي لكنها أوسع منه.', 'تقنيات السرد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'في بيت طرفة «على مثلها أمضي إذا قال صاحبي ألا ليتني أفديك منها وأفتدي»، إلى ماذا يعود ضمير «مثلها» في سياق المعلقة؟', '["ناقة موصوفة بالقوة والسرعة","خمر معتقة","امرأة من الحي","سفينة في البحر"]'::jsonb, 0, 45, 8, 'multi', 'يرد البيت داخل وصف طويل لناقة طرفة؛ فالضمير يعود إلى الناقة التي يمضي على مثلها في المخاوف، لا إلى الخمر أو المرأة.', 'غريب الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'ما الفارق المعجمي الأدق بين «الحَمْل» و«الحِمْل» كما قرره الخليل؟', '["الحَمْل للخفيف والحِمْل للثقيل","الحَمْل للإنسان والحِمْل للحيوان","الحَمْل لما في البطن أو على الشجر، والحِمْل لما حُمل على الظهر","هما لغتان بلا فرق دلالي"]'::jsonb, 2, 45, 9, 'multi', 'يفرّق كتاب العين بين الحَمْل، ومنه ما في البطن أو على الشجر، والحِمْل الذي يُحمل على ظهر أو رأس؛ وهو فرق بالحركة والدلالة.', 'فروق لغوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي معنى معجمي يلائم لفظ «العِهن» في عبارة «كالعهن المنفوش»؟', '["الصوف المصبوغ بألوان","القطن الأبيض غير المغزول","الحرير الخالص","وبر الإبل الأسود"]'::jsonb, 0, 40, 10, 'multi', 'العِهن هو الصوف، وقيل المصبوغ منه خاصة؛ ووصفه بالمنفوش يصور الجبال يوم القيامة في خفة الصوف المتفرق وتعدد ألوانه.', 'غريب القرآن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'إذا قالت العرب «ثَكِلَتْه أمه»، فما الأصل الدلالي للفعل «ثَكِل»؟', '["مرض ولدها","هجرها زوجها","افتقرت بعد غنى","فقدت ولدها"]'::jsonb, 3, 40, 11, 'multi', 'الثُّكل فقدان المرأة ولدها، فهي ثاكل وثكلى؛ وقد ترد العبارة دعاءً أو على مجرى كلام العرب من غير إرادة ظاهرها، لكن أصلها المعجمي هو فقد الولد.', 'غريب الحديث');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'ما المقصود بـ«الأوابد» في قول امرئ القيس «وقد أغتدي والطير في وكناتها بمنجرد قيد الأوابد هيكل»؟', '["الطيور في أعشاشها","الوحوش النافرة","الإبل المعلَّمة","الخيول المربوطة"]'::jsonb, 1, 45, 12, 'multi', 'الأوابد الوحوش التي توحشت ونفرت؛ و«قيد الأوابد» وصف للفرس كأنه يقيد الوحوش بسرعة إدراكه لها، لا أنه يقيد خيلًا مربوطة.', 'غريب الشعر الجاهلي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي عبارة تميز «الطَّلْح» في أشهر تفسير لغوي لآية «وطلح منضود»؟', '["نخل باسق قليل الثمر","سدر منزوع الشوك","شجر الموز المتراكب الثمر","عنب مجفف في عناقيد"]'::jsonb, 2, 45, 13, 'multi', 'نقل أهل اللغة والتفسير أن الطلح في الآية هو الموز، والمنضود المتراكب بعضه فوق بعض. أما السدر فقد ذُكر مستقلًا قبلها في «سدر مخضود».', 'غريب القرآن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'بماذا تختلف الطبيعية الأدبية عند إميل زولا عن الواقعية العامة؟', '["تنفي أثر المجتمع وترد السلوك إلى المصادفة","تؤكد أثر الوراثة والبيئة وتستلهم المنهج التجريبي","تجعل الرمز الغامض غاية العمل الوحيدة","تلتزم بوحدة الوزن والقافية في كل الأجناس"]'::jsonb, 1, 45, 14, 'multi', 'دفعت الطبيعية مبادئ الواقعية نحو تصور حتمي متأثر بالعلم الوضعي: الشخصيات نتاج الوراثة والوسط والظروف، وزولا أبرز منظّري «الرواية التجريبية».', 'المذاهب الأدبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي ممارسة ترتبط بالسريالية تاريخيًا أكثر من غيرها؟', '["الوصف الاجتماعي المحايد وفق وثائق الإحصاء","تقليد نماذج القدماء مع وحدة الأجناس","تنقية القصيدة من الصورة والمجاز","الكتابة الآلية لاستكشاف تداعيات اللاوعي"]'::jsonb, 3, 45, 15, 'multi', 'استلهم السرياليون التحليل النفسي وسعوا إلى تحرير عمل اللاوعي؛ وكانت الكتابة الآلية إحدى وسائل تجاوز الرقابة العقلية الواعية.', 'المذاهب الأدبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'في الرمزية الفرنسية، ما الوظيفة الأبرز لـ«المراسلات» بين الحواس والأشياء؟', '["إثبات الوقائع بتقرير علمي مباشر","إلغاء الموسيقى اللفظية من القصيدة","الإيحاء بعلاقات باطنية عبر الرمز والتشابك الحسي","قصر الدلالة على المعنى المعجمي الحرفي"]'::jsonb, 2, 45, 16, 'multi', 'ترى الرمزية أن الظاهر يومئ إلى حقائق خفية، فتستعمل الرمز والموسيقى وتراسل الحواس لاقتراح المعنى بدل تقريره المباشر.', 'المذاهب الأدبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي قضية نقدية كانت مركزية عند جماعة أبولو المصرية مقارنة بالإحيائيين؟', '["المحافظة الصارمة على معجم المدائح العباسية","رفض التعبير الذاتي تمامًا","التجربة الوجدانية والصورة العضوية المتصلة بالطبيعة","تحويل الشعر إلى توثيق تاريخي محض"]'::jsonb, 2, 45, 17, 'multi', 'مثلت أبولو اتجاهًا رومانسيًا أبرز الوجدان والطبيعة والخيال ووحدة التجربة، في مقابل عناية الإحيائيين الأكبر بمحاكاة النموذج التراثي.', 'مدارس الأدب العربي الحديث');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'ما الذي يفصل «المونولوج الداخلي المباشر» عن السرد النفسي غير المباشر في التصنيف الشائع؟', '["لا ينقل أي فكرة للشخصية","يشترط راويا عليمًا يفسر كل إحساس","لا يمكن أن يرد إلا في المسرح المنظوم","يعرض كلام الشخصية الباطني دون تدخل شارح ظاهر من الراوي"]'::jsonb, 3, 45, 18, 'multi', 'المونولوج الداخلي المباشر يقدم المحتوى الذهني كما لو أنه يجري في وعي الشخصية مع تقليل الوساطة السردية؛ أما التحليل النفسي غير المباشر فيصوغه الراوي ويشرحه.', 'تقنيات السرد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_49, 'أي تعريف يطابق «التناص» عند جوليا كريستيفا في أصله النظري؟', '["نقل عبارة من مصدر مع توثيقها فقط","تشكل النص بوصفه تقاطعًا وتحويلًا لنصوص وخطابات سابقة","مطابقة وزن قصيدة لوزن قصيدة أخرى","ترجمة النص إلى لغتين في صفحة واحدة"]'::jsonb, 1, 50, 19, 'multi', 'التناص أوسع من الاقتباس المعلن؛ فالنص يتكون داخل شبكة من نصوص وخطابات يمتصها ويحوّلها، وهو تصور طورته كريستيفا انطلاقًا من حوارية باختين.', 'النظرية الأدبية');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_50 uuid;
BEGIN
  SELECT id INTO v_lib_id_50 FROM quizzes WHERE title = 'ألغاز متواليات واستنتاج منطقي' LIMIT 1;
  IF v_lib_id_50 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('ألغاز متواليات واستنتاج منطقي', 'ألغاز ومنطق', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_50;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'متوالية حسابية حدها الأول 7 وفرقها الثابت 5. ما حدها الثامن؟', '["42","40","47","35"]'::jsonb, 0, 30, 0, 'multi', 'في المتوالية الحسابية a_n=a_1+(n-1)d؛ لذلك a_8=7+7×5=42.', 'متواليات حسابية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'متوالية هندسية موجبة تبدأ بـ 3، 6، 12. إذا ظلت النسبة ثابتة، فما الحد السادس؟', '["48","72","192","96"]'::jsonb, 3, 30, 1, 'multi', 'النسبة المشتركة 2، ومن ثم الحدود التالية 24 ثم 48 ثم 96؛ أو a_6=3×2^5=96.', 'متواليات هندسية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'تُعرّف المتوالية بـ a₁=2 وaₙ=aₙ₋₁+n لكل n≥2. ما قيمة a₅؟', '["14","20","16","12"]'::jsonb, 2, 35, 2, 'multi', 'نضيف رقم الحد في كل خطوة: a₂=4، a₃=7، a₄=11، a₅=16.', 'علاقات عودية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'إذا كانت العبارة «كل الباحثين دقيقون» صحيحة، وكان سامر باحثًا، فأي نتيجة تلزم منطقيًا؟', '["سامر دقيق","كل الدقيقين باحثون","سامر الباحث الوحيد","لا يوجد دقيق غير سامر"]'::jsonb, 0, 30, 3, 'multi', 'من ∀x(باحث(x)→دقيق(x)) ومن باحث(سامر)، ينتج دقيق(سامر) بقاعدة إثبات المقدم. عكس الشرط أو ادعاء التفرد لا يلزمان.', 'استدلال شرطي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'أحد الصناديق الثلاثة A وB وC يحوي المفتاح. العبارات هي: «المفتاح ليس في A»، «المفتاح في C»، «المفتاح ليس في A ولا B». إذا كانت عبارة واحدة فقط صحيحة، فأين المفتاح؟', '["في A","في C","في B","لا يمكن تحديده"]'::jsonb, 2, 40, 4, 'multi', 'إن كان في A كذبت العبارات الثلاث، وإن كان في C صدقت العبارات الثلاث. أما إن كان في B فتصدق الأولى وحدها وتكذب الثانية والثالثة؛ لذا B هو الحل الوحيد.', 'تحليل حالات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'في صف من ثلاثة مقاعد، تجلس ليلى قبل مريم، وتجلس مريم قبل نور. ما الترتيب الوحيد من اليسار إلى اليمين؟', '["مريم، ليلى، نور","ليلى، مريم، نور","نور، مريم، ليلى","ليلى، نور، مريم"]'::jsonb, 1, 30, 5, 'multi', 'العلاقتان تفرضان ليلى < مريم < نور بالتعدي، ومع وجود ثلاثة أشخاص وثلاثة مقاعد يكون هذا الترتيب وحيدًا.', 'ترتيب منطقي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'إذا كان نفي العبارة «سافر أحمد وكتب التقرير» صحيحًا، فأي صياغة تكافئه وفق قوانين دي مورغان؟', '["لم يسافر أحمد ولم يكتب التقرير","سافر أحمد أو كتب التقرير","لم يسافر أحمد أو لم يكتب التقرير","إذا سافر أحمد فلن يكتب التقرير"]'::jsonb, 2, 35, 6, 'multi', 'نفي الاقتران ¬(P∧Q) يكافئ ¬P∨¬Q، ولا يشترط أن يكون الحدثان كلاهما منفيين.', 'تكافؤ منطقي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'تبدأ متوالية فيبوناتشي هنا بـ 1، 1، وكل حد لاحق مجموع سابقيه. ما الحد السابع؟', '["13","8","21","11"]'::jsonb, 0, 30, 7, 'multi', 'الحدود هي 1، 1، 2، 3، 5، 8، 13، لذا السابع 13.', 'متواليات عودية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'لتكن a₁=1 وaₙ=2aₙ₋₁+1. أي صيغة مغلقة صحيحة لـ aₙ؟', '["2ⁿ+1","2ⁿ−1","2n−1","n²−1"]'::jsonb, 1, 45, 8, 'multi', 'بالتعويض تعطي الصيغة 2¹−1=1. وإذا aₙ₋₁=2ⁿ⁻¹−1 فإن 2aₙ₋₁+1=2ⁿ−1، فتثبت بالاستقراء.', 'علاقات عودية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'متوالية كثيرة حدود من الدرجة الثانية قيمها عند n=1,2,3,4 هي 2، 6، 12، 20. ما قيمة الحد الخامس؟', '["28","32","26","30"]'::jsonb, 3, 45, 9, 'multi', 'الفروق الأولى 4، 6، 8 وفروقها الثانية ثابتة وتساوي 2؛ لذا الفرق التالي 10 والحد الخامس 20+10=30. القيد بأنها تربيعية يجعل الاستكمال وحيدًا.', 'فروق منتهية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'في جزيرة، الصادق يصدق دائمًا والكاذب يكذب دائمًا. قال أ: «ب كاذب». وقال ب: «نحن من النوع نفسه». ما نوع كل منهما؟', '["أ كاذب وب صادق","أ صادق وب كاذب","كلاهما صادق","كلاهما كاذب"]'::jsonb, 1, 45, 10, 'multi', 'إن صدق أ فب كاذب، وقول ب إنهما من النوع نفسه كذب، فيتسق الحل. وإن كذب أ كان ب صادقًا، لكن قول ب إنهما من النوع نفسه يصبح كذبًا، فتناقض. إذن الحل وحيد.', 'صادق وكاذب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'أربع مهام A وB وC وD في ترتيب خطي. A قبل B، وC بعد B مباشرة، وD قبل A. ما الترتيب الوحيد؟', '["A، D، B، C","D، B، C، A","B، C، D، A","D، A، B، C"]'::jsonb, 3, 45, 11, 'multi', 'B وC كتلة متجاورة بالترتيب BC. يجب أن يسبقها A، وأن يسبق D العنصر A؛ فتُفرض السلسلة D<A<B<C.', 'ترتيب بقيود');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'لدينا المقدمات: إذا نجح الاختبار فالنظام يعمل. إذا عمل النظام وصل الإشعار. لم يصل الإشعار. ما النتيجة اللازمة؟', '["نجح الاختبار ولم يعمل النظام","لم ينجح الاختبار","وصل الإشعار متأخرًا","لا يمكن استنتاج شيء عن الاختبار"]'::jsonb, 1, 45, 12, 'multi', 'من P→S وS→N نحصل على P→N بالقياس الشرطي. ومع ¬N نستنتج ¬P بنفي التالي (modus tollens).', 'استدلال شرطي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'أي عبارة هي النقيض المنطقي الدقيق لعبارة «لكل طالب كتاب واحد على الأقل»؟', '["لا يملك أي طالب كتابًا","يوجد طالب يملك كتابًا واحدًا","لكل طالب كتابان على الأقل","يوجد طالب لا يملك أي كتاب"]'::jsonb, 3, 45, 13, 'multi', 'نفي ∀x∃y يمتلك(x,y) هو ∃x∀y ¬يمتلك(x,y): يوجد طالب لا يملك أي كتاب. لا يعني النفي أن جميع الطلاب بلا كتب.', 'منطق محمولات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'إذا كانت P↔Q صحيحة وP كاذبة، فما قيمة Q بالضرورة؟', '["صحيحة","غير قابلة للتحديد","كاذبة","صحيحة وكاذبة معًا"]'::jsonb, 2, 40, 14, 'multi', 'التكافؤ الثنائي يكون صادقًا عندما تتساوى قيمتا الطرفين فقط؛ وبما أن P كاذبة، يلزم أن تكون Q كاذبة.', 'جداول صدق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'تتبع المتوالية القاعدة a₁=4 وaₙ=aₙ₋₁+2n−1. أي حد يساوي 103؟', '["التاسع","الحادي عشر","الثاني عشر","العاشر"]'::jsonb, 3, 50, 15, 'multi', 'مجموع الأعداد الفردية من 3 حتى 2n−1 يساوي n²−1؛ لذا aₙ=4+(n²−1)=n²+3. بحل n²+3=103 نحصل على n=10.', 'علاقات عودية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'ثلاث بطاقات مرقمة 1 و2 و3 توضع في صف. البطاقة 1 ليست في الطرف، والبطاقة 3 تقع يسار البطاقة 2. ما الترتيب الوحيد؟', '["2، 1، 3","1، 3، 2","3، 1، 2","3، 2، 1"]'::jsonb, 2, 40, 16, 'multi', 'بما أن 1 ليست طرفًا فهي في الوسط. يبقى الطرفان لـ2 و3، وشرط وقوع 3 يسار 2 يفرض 3،1،2.', 'تباديل مقيدة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'في رسم بياني بسيط، درجات الرؤوس هي 3، 3، 2، 2، 2، 2. كم عدد الحواف؟', '["7","6","8","14"]'::jsonb, 0, 45, 17, 'multi', 'مجموع الدرجات 14. وفق مبرهنة المصافحة يساوي مجموع الدرجات ضعفي عدد الحواف، لذا عدد الحواف 14÷2=7.', 'منطق الرسوم البيانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'لدينا أربع عبارات عن عدد صحيح n: (1) n زوجي، (2) n>10، (3) n من مضاعفات 3، (4) n<15. إذا كانت ثلاث عبارات فقط صحيحة وكان n أحد الأعداد 9 أو12 أو15 أو18، فما n؟', '["18","12","9","15"]'::jsonb, 0, 50, 18, 'multi', 'عند 12 تكون العبارات الأربع: صحيحة، صحيحة، صحيحة، صحيحة؛ وهذا يخالف الشرط. عند 18: صحيحة، صحيحة، صحيحة، خاطئة، فتتحقق ثلاث. إذن الصحيح هو 18 لا 12.', 'تحليل حالات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_50, 'المقدمات: بعض الشعراء علماء، ولا عالم مهمل. أي نتيجة تلزم؟', '["كل الشعراء علماء","بعض الشعراء ليسوا مهملين","لا شاعر مهمل","بعض المهملين شعراء"]'::jsonb, 1, 45, 19, 'multi', 'يوجد شخص شاعر وعالم بمقتضى المقدمة الأولى. وبما أن كل عالم غير مهمل، فهذا الشخص نفسه شاعر غير مهمل؛ ولا يلزم تعميم الحكم على كل الشعراء.', 'قياس حملي');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_51 uuid;
BEGIN
  SELECT id INTO v_lib_id_51 FROM quizzes WHERE title = 'المسائل الصورية والمفارقات المنطقية' LIMIT 1;
  IF v_lib_id_51 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('المسائل الصورية والمفارقات المنطقية', 'ألغاز ومنطق', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_51;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'إذا كانت P صادقة وQ كاذبة، فما قيمة الصيغة ¬(P ∧ Q) ↔ (¬P ∨ ¬Q)؟', '["صادقة لأن طرفي التكافؤ صادقان","كاذبة لأن طرفه الأيسر فقط صادق","كاذبة لأن طرفه الأيمن فقط صادق","لا يمكن تحديدها من القيم المعطاة"]'::jsonb, 0, 35, 0, 'multi', 'P ∧ Q كاذبة، فنفيها صادق. كذلك ¬P كاذبة و¬Q صادقة، ولذلك ¬P ∨ ¬Q صادقة. والتكافؤ بين قضيتين صادقتين صادق؛ وهذا تطبيق مباشر لقانون دي مورغان.', 'جداول الصدق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي صيغة هي النفي الصحيح لعبارة «كل باحث قرأ كتابًا واحدًا على الأقل» إذا رمز R(x,y) إلى «x قرأ y» وكان مجال y هو الكتب؟', '["∀x∃y ¬R(x,y)","∃x∃y ¬R(x,y)","∀x∀y ¬R(x,y)","∃x∀y ¬R(x,y)"]'::jsonb, 3, 40, 1, 'multi', 'العبارة الأصلية صورتها ∀x∃y R(x,y). عند نفي الكمّين نعكسهما وننفي المحمول: ¬∀x∃yR يكافئ ∃x∀y¬R؛ أي يوجد باحث لم يقرأ أي كتاب.', 'منطق المحمولات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'من المقدمتين P → Q و¬Q، أي نتيجة تلزم في المنطق الكلاسيكي؟', '["P","Q","¬P","P ↔ Q"]'::jsonb, 2, 30, 2, 'multi', 'لو كانت P صادقة للزم Q من الشرطية، لكن ¬Q معطاة؛ إذن P كاذبة. هذه قاعدة نفي التالي (modus tollens)، وهي صورة استدلال صحيحة.', 'قواعد الاستدلال');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'في عالم لا يضم إلا أمل وبدر، كانت F(x) صادقة لأمل فقط. أي قضية تكون صادقة؟', '["∃x F(x) ∧ ¬∀x F(x)","∀x F(x)","¬∃x F(x)","∀x ¬F(x)"]'::jsonb, 0, 35, 3, 'multi', 'وجود أمل التي تحقق F يجعل ∃xF(x) صادقة، وعدم تحقق F لبدر يجعل ∀xF(x) كاذبة، ومن ثم نفيها صادق. لذلك يصدق اقتران الوجود مع نفي العموم وحده.', 'دلالات منطق الرتبة الأولى');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي حالة تُبطل الحجة: «إذا نجح الاختبار نُشر البرنامج؛ نُشر البرنامج؛ إذن نجح الاختبار»؟', '["الاختبار لم ينجح والبرنامج نُشر لسبب آخر","الاختبار نجح والبرنامج نُشر","الاختبار لم ينجح والبرنامج لم يُنشر","الاختبار نجح والبرنامج لم يُنشر"]'::jsonb, 0, 35, 4, 'multi', 'الحجة من صورة إثبات التالي: P→Q، Q، إذن P. الحالة P كاذبة وQ صادقة تجعل المقدمتين صادقتين والنتيجة كاذبة، فتكون مثالًا مضادًا يثبت عدم الصلاحية.', 'المغالطات الصورية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'لدينا: «لا شاعرَ مهندسٌ»، و«بعض المعلمين شعراء». ما النتيجة اللازمة؟', '["لا معلم مهندس","بعض المهندسين معلمون","بعض المعلمين ليسوا مهندسين","كل الشعراء معلمون"]'::jsonb, 2, 40, 5, 'multi', 'يوجد بمقتضى المقدمة الثانية فرد معلم وشاعر. وبما أن مجموعة الشعراء منفصلة عن المهندسين وفق الأولى، فهذا الفرد نفسه ليس مهندسًا؛ لذا تلزم النتيجة الوجودية فقط، لا تعميم على جميع المعلمين.', 'القياس الحملي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'في لغز الفرسان والكذابين، يقول شخص واحد: «أنا كاذب». مع افتراض أن الفارس يصدق دائمًا والكاذب يكذب دائمًا، فما الوصف الأدق؟', '["لا يمكن لأي من النوعين قولها على نحو متسق","لا بد أنه فارس","لا بد أنه كاذب","يمكن أن يكون أيًا منهما بلا تناقض"]'::jsonb, 0, 35, 6, 'multi', 'إن كان فارسًا فقوله إنه كاذب كذب، وهذا يناقض كونه فارسًا. وإن كان كاذبًا فالجملة «أنا كاذب» صادقة، وهذا يناقض اشتراط كذبه دائمًا. لذلك لا يوجد إسناد متسق ضمن الفرضين.', 'ألغاز الصدق والكذب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي علاقة تصف قضيتي «كل A هو B» و«بعض A ليس B» في مربع التقابل التقليدي مع افتراض وجود أفراد من A؟', '["متضادتان: قد تكذبان معًا","متداخلتان: صدق الأولى يستلزم صدق الثانية","متناقضتان: تصدق إحداهما وتكذب الأخرى","لا علاقة دلالية بينهما"]'::jsonb, 2, 40, 7, 'multi', '«كل A هو B» قضية كلية موجبة (A)، و«بعض A ليس B» جزئية سالبة (O). كل واحدة نفي للأخرى: نفي ∀x(A→B) يكافئ ∃x(A∧¬B)، لذا لا تصدقان ولا تكذبان معًا.', 'مربع التقابل');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي إسناد للقيم يجعل الصيغة ((P → Q) ∧ (Q → R)) → (P → R) كاذبة؟', '["P صادقة وQ كاذبة وR كاذبة","لا يوجد؛ الصيغة صادقة في كل إسناد","P كاذبة وQ صادقة وR كاذبة","P صادقة وQ صادقة وR كاذبة"]'::jsonb, 1, 50, 8, 'multi', 'لكي تكذب الشرطية الكلية يجب أن يصدق مقدمها وتكذب P→R، أي P صادقة وR كاذبة. عندئذ يفرض P→Q صدق Q، لكن Q→R تصبح كاذبة، فلا يصدق المقدم. لذلك لا يوجد مثال مضاد والصيغة تحصيل حاصل.', 'جداول الصدق المتقدمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي زوج من الصيغ غير متكافئ عمومًا في منطق الرتبة الأولى؟', '["¬∀xP(x) و∃x¬P(x)","∀x(P(x) ∨ Q(x)) و(∀xP(x) ∨ ∀xQ(x))","¬∃xP(x) و∀x¬P(x)","∀x(P(x) ∧ Q(x)) و(∀xP(x) ∧ ∀xQ(x))"]'::jsonb, 1, 50, 9, 'multi', 'قد يحقق كل فرد واحدًا من P أو Q من دون أن يحقق جميع الأفراد P ولا جميعهم Q؛ مثال ذلك فرد يحقق P فقط وآخر يحقق Q فقط. أما نفي الكمّين في الزوجين التاليين وتوزيع الكلي على الاقتران فهي تكافؤات صحيحة.', 'تكافؤات الكم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'في الاستدلال الطبيعي، لماذا لا يجوز من ∃x P(x) اختيار ثابت قديم a سبق أن ورد في فرض مفتوح ثم استنتاج P(a)؟', '["لأن حذف الكم الوجودي ممنوع في جميع البراهين","لأن P(a) يستلزم دائمًا ∀xP(x)","لأن الثوابت لا يجوز أن تظهر داخل المحمولات","لأن a قد يدل على فرد مخصوص لا على شاهد اعتباطي للوجود"]'::jsonb, 3, 55, 10, 'multi', 'قاعدة حذف الوجود تشترط اسمًا جديدًا لا يحمل معلومات مستقلة، حتى يمثل شاهدًا اعتباطيًا. استعمال ثابت مرتبط بفرض سابق قد ينقل خصائص ذلك الفرد الخاص إلى الشاهد بلا مبرر، فيفسد البرهان.', 'الاستدلال الطبيعي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'لتكن Γ = {P ∨ Q, ¬P}. أي عبارة ميتامنطقية صحيحة؟', '["Γ ⊨ P","Γ غير قابلة للإشباع","Γ ⊨ ¬Q","Γ ⊨ Q"]'::jsonb, 3, 45, 11, 'multi', 'كل إسناد يحقق ¬P يجعل P كاذبة، ولكي يحقق كذلك P∨Q لا بد أن يجعل Q صادقة. لذلك Q نتيجة دلالية من Γ وفق تعريف اللزوم الدلالي.', 'اللّزوم الدلالي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي خاصية لنظرية حسابية متسقة وقابلة للتمثيل بفاعلية هي التي تمنعها مبرهنة غودل الأولى إذا كانت قوية بما يكفي لتمثيل الحساب الأساسي؟', '["السلامة: ألا تثبت تناقضًا","قابلية تعداد بديهياتها آليًا","الاكتمال: أن تثبت كل جملة أو نفيها","اشتمالها على عمليات الجمع والضرب"]'::jsonb, 2, 55, 12, 'multi', 'تقرر المبرهنة أن كل نسق صوري متسق، قابل للتأكسم الفعال، وقوي حسابيًا بالقدر الكافي يكون غير كامل: توجد جملة في لغته لا يثبتها ولا يثبت نفيها. الشروط الأخرى من فروض النتيجة وليست الخاصية المنفية.', 'عدم الاكتمال');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'ما الخطوة التي تولّد التناقض في مفارقة راسل للمجموعة R = {x | x ∉ x}؟', '["افتراض أن كل مجموعتين متساويتان","منع المجموعة الخالية من الانتماء إلى نفسها","حصر جميع المجموعات في مجموعات منتهية","السؤال هل R ∈ R، إذ ينتج R ∈ R ↔ R ∉ R"]'::jsonb, 3, 50, 13, 'multi', 'بتطبيق شرط تعريف R على R نفسها نحصل على أن R عضو في ذاتها إذا وفقط إذا لم تكن عضوًا في ذاتها. كشفت المفارقة عيب مبدأ الاستيعاب غير المقيد، وعالجته نظريات بديهية مثل ZF بتقييد تكوين المجموعات.', 'مفارقات نظرية المجموعات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'في مفارقة كَري، افترض جملة C تقول: «إذا كانت C صادقة فإن 0=1». ما الذي يميز المفارقة عن مفارقة الكذاب؟', '["تعتمد حصرًا على غموض كلمة «كاذبة»","يمكن اشتقاق نتيجة اعتباطية باستعمال الشرطية والإحالة الذاتية من دون نفي صريح","لا تستخدم الإحالة الذاتية مطلقًا","لا تظهر إلا في منطق متعدد القيم"]'::jsonb, 1, 60, 14, 'multi', 'مفارقة كَري تبني جملة ذاتية المرجع من صورة «إذا كانت هذه الجملة صادقة فـA»، ويمكن ضمن مبادئ استدلال مناسبة الوصول إلى A من غير استعمال نفي أو محمول الكذب. لذلك تكشف أن المشكلة أوسع من مجرد تناقض الصدق والكذب.', 'مفارقات دلالية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي تمييز يمنع صياغة مفارقة الكذاب داخل نظرية تارسكي الهرمية للصدق؟', '["لغة الموضوع لا تحتوي محمول صدق ينطبق على جملها نفسها؛ ويُعرّف الصدق في لغة فوقية","كل جملة في لغة الموضوع تُعد كاذبة","تُحذف الروابط الشرطية من اللغة","يُسمح فقط بالجمل ذات القيمة الثالثة"]'::jsonb, 0, 55, 15, 'multi', 'يفصل تارسكي بين لغة موضوع نتحدث عن جملها ولغة فوقية أغنى نُسند فيها الصدق إلى تلك الجمل. منع محمول صدق شامل داخل اللغة نفسها يحظر الحلقة الدلالية التي تحتاجها جملة الكذاب.', 'نظريات الصدق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'في المنطق الكلاسيكي، إذا كانت مجموعة المقدمات Γ غير متسقة، فما الذي يترتب دلاليًا وفق تعريف Γ ⊨ φ؟', '["لا صيغة تلزم من Γ","تلزم التناقضات فقط","كل صيغة φ تلزم من Γ لأن لا نموذج يحقق جميع مقدماتها","تلزم القضايا الذرية دون المركبة"]'::jsonb, 2, 50, 16, 'multi', 'اللزوم الدلالي يعني أن كل نموذج للمقدمات نموذج للنتيجة. إذا لم يوجد أي نموذج للمقدمات غير المتسقة، فلا يوجد مثال مضاد، فيصدق الشرط على نحو خالٍ؛ وهذا يقابل مبدأ الانفجار برهانيًا.', 'الاتساق والانفجار');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'أي عبارة تميّز المنطق المتسامح مع التناقض (paraconsistent) عن المنطق الكلاسيكي؟', '["يرفض جميع صور نفي التالي","لا يجعل كل قضية نتيجة تلقائية من تناقض واحد","يمنع وجود جمل صادقة","يجعل كل تناقض تحصيل حاصل"]'::jsonb, 1, 50, 17, 'multi', 'السمة التعريفية للمنطق المتسامح مع التناقض هي فشل الانفجار: يمكن أن تحتوي النظرية A و¬A من دون أن تستنتج منها كل B. ولا يعني ذلك بالضرورة رفض سائر قواعد الاستدلال أو اعتبار التناقض صادقًا دائمًا.', 'منطقات غير كلاسيكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'تضم شبكة أربعة رؤوس A وB وC وD، وحوافها AB وBC وCD وDA وAC. كم لونًا على الأقل يلزم لتلوين الرؤوس بحيث يختلف لون كل رأسين متجاورين؟', '["2","3","4","5"]'::jsonb, 1, 55, 18, 'multi', 'المثلث A-B-C-A يفرض ثلاثة ألوان على الأقل. وتكفي ثلاثة: لوّن A وB وC بألوان مختلفة، ثم أعط D لون B؛ فـD مجاور لـA وC وغير مجاور لـB. إذن العدد اللوني يساوي 3.', 'منطق توافقي ونظرية الرسوم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_51, 'لدينا المقدمات: ∀x(P(x)→Q(x))، ∃x(P(x)∧R(x))، ∀x(R(x)→¬Q(x)). ما الحكم الصحيح؟', '["المقدمات قابلة للإشباع إذا كان المجال فارغًا","تلزم منها ∀x¬P(x) مع بقائها متسقة","لا يوجد تعارض لأن الشاهدين الوجوديين قد يختلفان","المقدمات غير قابلة للإشباع"]'::jsonb, 3, 60, 19, 'multi', 'تضمن المقدمة الوجودية شاهدًا واحدًا a يحقق P وR معًا. من P(a) والكلي الأول ينتج Q(a)، ومن R(a) والكلي الثالث ينتج ¬Q(a)، فلا يمكن لأي بنية أن تحقق المقدمات الثلاث معًا.', 'الإشباع في منطق المحمولات');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_52 uuid;
BEGIN
  SELECT id INTO v_lib_id_52 FROM quizzes WHERE title = 'الشبكات وأنظمة التشغيل' LIMIT 1;
  IF v_lib_id_52 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الشبكات وأنظمة التشغيل', 'تكنولوجيا', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_52;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'يرسل مضيف رزمة IPv4 أكبر من MTU للوصلة التالية، وكانت راية DF مفعّلة. ما السلوك المعياري للموجّه؟', '["يجزّئ الرزمة رغم راية DF","يحوّلها إلى IPv6 تلقائيًا","يسقط الرزمة ويرسل ICMP Destination Unreachable برمز Fragmentation Needed","يخفض نافذة TCP ثم يعيد إرسالها"]'::jsonb, 2, 35, 0, 'multi', 'تمنع راية Don''t Fragment تجزئة رزمة IPv4. إذا تجاوز حجمها MTU، يسقطها الموجّه ويرسل رسالة ICMP من النوع Destination Unreachable والرمز Fragmentation Needed لتمكين اكتشاف MTU للمسار.', 'IPv4 وMTU');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'بعد أن يرسل عميل TCP مقطع SYN، يتلقى SYN-ACK صالحًا. ما المقطع الذي يكمل المصافحة الثلاثية؟', '["ACK","FIN-ACK","RST","SYN جديد"]'::jsonb, 0, 30, 1, 'multi', 'تبدأ المصافحة بـSYN ثم يرد الخادم بـSYN-ACK، ويؤكد العميل رقم تسلسل الخادم بمقطع ACK؛ عندها يصبح الاتصال مؤسسًا.', 'TCP');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'يريد محلّل DNS معرفة خوادم البريد المسؤولة عن نطاق وترتيب أفضليتها. أي نوع سجل يطلب؟', '["MX","NS","PTR","TXT"]'::jsonb, 0, 30, 2, 'multi', 'يحمل سجل MX اسم مضيف مبادل البريد وقيمة preference؛ تُفضّل القيمة العددية الأقل. أما NS فيحدد خادم أسماء وPTR للبحث العكسي.', 'DNS');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في شبكة Ethernet محلية، يعرف المضيف عنوان IPv4 للبوابة لكنه لا يعرف عنوانها الفيزيائي. ما البروتوكول الذي يستخدمه للحصول على عنوان MAC؟', '["ICMP","DHCP","NDP","ARP"]'::jsonb, 3, 30, 3, 'multi', 'يربط ARP عنوان بروتوكول IPv4 بعنوان Ethernet داخل الشبكة المحلية. NDP يؤدي وظيفة مقابلة ضمن IPv6، وليس IPv4.', 'شبكات محلية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في نظام بذاكرة افتراضية، حاولت عملية الوصول إلى صفحة صالحة منطقيًا لكنها غير موجودة حاليًا في الذاكرة الفعلية. ما الحدث المتوقع؟', '["تقسيم فوري للعملية إلى خيطين","خطأ صفحة يعالجه النظام بجلب الصفحة","تجاوز تلقائي لذاكرة التخزين المؤقت للمعالج","إرسال إشارة إنهاء حتمًا"]'::jsonb, 1, 35, 4, 'multi', 'يولد الوصول إلى صفحة غير مقيمة page fault. إذا كان العنوان جزءًا صالحًا من فضاء العملية، يستطيع النواة جلب الصفحة إلى الذاكرة وتحديث جدول الصفحات ثم استئناف التنفيذ؛ ليس الخطأ قاتلًا بالضرورة.', 'الذاكرة الافتراضية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'أي آلية تتيح لبرنامج Unix إنشاء عملية جديدة تبدأ كنسخة من العملية المستدعية قبل تنفيذ برنامج آخر عادةً؟', '["execve()","fork()","wait()","mmap()"]'::jsonb, 1, 30, 5, 'multi', 'تنشئ fork() عملية ابنًا بفضاء عناوين منطقي منسوخ من الأب، وغالبًا تُتبع في الابن بـexecve() لاستبدال صورة العملية ببرنامج جديد؛ execve() وحدها لا تنشئ عملية جديدة.', 'العمليات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'ما الخاصية التي تميز الرابط الصلب hard link في نظام ملفات POSIX عن الرابط الرمزي؟', '["يخزن دائمًا مسارًا نصيًا إلى الهدف","يمكنه عبور أنظمة الملفات بلا قيود","له inode الهدف نفسه فقط عندما يكون الهدف مجلدًا","يشير إلى inode نفسه ويظل صالحًا بعد حذف الاسم الأصلي ما دام رابط صلب آخر موجودًا"]'::jsonb, 3, 35, 6, 'multi', 'الرابط الصلب اسم دليل إضافي للكائن نفسه، لذلك يزيد عدّاد الروابط ولا يعتمد على بقاء الاسم الأصلي. الرابط الرمزي كائن مستقل يحتوي مسارًا وقد يصبح معلقًا.', 'أنظمة الملفات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في IPv6، ما الآلية القياسية التي تحل محل ARP لاكتشاف عنوان طبقة الوصلة لجار على الشبكة المحلية؟', '["DHCPv6 فقط","IGMP","Neighbor Discovery باستخدام ICMPv6","OSPFv3"]'::jsonb, 2, 30, 7, 'multi', 'يستخدم IPv6 بروتوكول Neighbor Discovery ورسائل Neighbor Solicitation وNeighbor Advertisement ضمن ICMPv6 لحل عناوين طبقة الوصلة، بدل ARP المستخدم في IPv4.', 'IPv6');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'يعلن موجّه مسارين في جدول IPv4: ‎10.0.0.0/8 عبر A و‎10.1.2.0/24 عبر B. إلى أي قفزة تُرسل رزمة وجهتها ‎10.1.2.77؟', '["A لأن /8 أُضيف أولًا","B لأن /24 هو التطابق الأطول","كلاهما بالتناوب حتمًا","تُسقط بسبب وجود مسارين متداخلين"]'::jsonb, 1, 40, 8, 'multi', 'تطابق الوجهة كلا البادئتين، لكن قرار التوجيه يختار أطول بادئة مطابقة؛ /24 أكثر تحديدًا من /8، لذلك تُستخدم القفزة B.', 'التوجيه');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'اتصال TCP لديه نافذة ازدحام cwnd=12 MSS ونافذة استقبال rwnd=8 MSS، ولا توجد بيانات غير مؤكدة. ما الحد الأقصى المبدئي للبيانات التي يمكن أن تكون قيد الإرسال؟', '["12 MSS","8 MSS","20 MSS","96 MSS"]'::jsonb, 1, 45, 9, 'multi', 'يحد الإرسال كل من التحكم في الازدحام والتحكم في التدفق، لذا نافذة الإرسال الفعلية لا تتجاوز min(cwnd,rwnd)=min(12,8)=8 MSS.', 'TCP المتقدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'خلال استعلام DNS تكراري، أعاد الخادم سجلًا بقيمة TTL تساوي 300. بعد 120 ثانية، ما أكبر TTL ينبغي أن تعرضه نسخة مخبأة لذلك السجل، بافتراض عدم تحديثه؟', '["300 ثانية","420 ثانية","صفر دائمًا","180 ثانية"]'::jsonb, 3, 40, 10, 'multi', 'TTL يحدد الزمن الذي يجوز خلاله تخزين السجل مؤقتًا، وتُنقصه المدة المنقضية في المخبأ. بعد 120 ثانية من 300 يبقى بحد أقصى 180 ثانية.', 'DNS');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'أي وصف دقيق لما تفعله ترجمة PAT/NAPT عند مشاركة عدة مضيفين عنوان IPv4 عامًا واحدًا؟', '["تستبدل عناوين MAC فقط ولا تلمس ترويسة IP","تشفّر حمولة كل رزمة تلقائيًا","تضيف مسارًا ثابتًا منفصلًا لكل مضيف بلا تعديل للرزم","تميز التدفقات بتعديل عناوين وأرقام منافذ النقل مع حفظ حالة الربط"]'::jsonb, 3, 45, 11, 'multi', 'يسمح NAPT بتعدد المضيفين خلف عنوان خارجي واحد عبر ترجمة عنوان IP ومعرّف النقل، مثل منفذ TCP أو UDP، والاحتفاظ بربط يعيد الرزم الواردة إلى التدفق الداخلي الصحيح.', 'NAT');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في OSPF، لماذا لا يكفي عدد القفزات وحده لاختيار المسار الأفضل؟', '["لأنه بروتوكول path-vector يعتمد AS_PATH","لأن OSPF يحسب أقصر مسار وفق كلفة الروابط المعلنة لا عدد الموجّهات فقط","لأنه لا يحتفظ بقاعدة حالة وصلات","لأنه يختار دائمًا المسار ذي أعلى MTU"]'::jsonb, 1, 45, 12, 'multi', 'OSPF بروتوكول حالة وصلات، ويبني شجرة أقصر المسارات باستخدام metric هي مجموع كلف الواجهات. قد يتفوق مسار أكثر قفزات إذا كان مجموع كلفته أقل.', 'بروتوكولات التوجيه');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'شبكة IPv4 هي ‎192.0.2.0/26. بعد استبعاد عنواني الشبكة والبث، كم عنوانًا يمكن إسناده عادةً إلى مضيفين؟', '["62","64","60","126"]'::jsonb, 0, 40, 13, 'multi', 'تترك بادئة /26 ست بتات للمضيف، أي 2^6=64 عنوانًا. في شبكة البث التقليدية يُحجز أول عنوان للشبكة وآخر عنوان للبث، فيبقى 62.', 'العنونة والتقسيم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'تحت خوارزمية الاستبدال LRU، الذاكرة تحوي الصفحات [1،2،3] وكانت 1 الأقل استخدامًا حديثًا. بعد الوصول إلى 2 ثم حدوث خطأ صفحة للصفحة 4، أي صفحة تُستبدل؟', '["2","3","1","4"]'::jsonb, 2, 40, 14, 'multi', 'الوصول إلى 2 يجعلها حديثة الاستخدام، بينما تبقى 1 أقدم صفحة استعمالًا من بين الصفحات المقيمة؛ لذلك تختار LRU الصفحة 1 ضحية للاستبدال.', 'إدارة الذاكرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'أي مجموعة تمثل الشروط الأربعة اللازمة معًا لحدوث الاختناق المتبادل وفق نموذج كوفمان؟', '["الاستبعاد المتبادل، الإمساك والانتظار، عدم نزع المورد، الانتظار الدائري","التزامن، الإنصاف، الأولوية، المقاطعة","الترحيل، التجزئة، التخزين المؤقت، الاستبدال","الانتظار المشغول، التبديل السياقي، الجوع، الانقلاب الأولوي"]'::jsonb, 0, 45, 15, 'multi', 'لا يمكن أن يقع deadlock إلا مع اجتماع mutual exclusion وhold-and-wait وno preemption وcircular wait. كسر أي شرط منها يمنع الاختناق ضمن هذا النموذج.', 'التزامن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في نظام يستخدم copy-on-write بعد fork()، متى تُنسخ صفحة ذاكرة فعلية عادةً إلى صفحة مستقلة للابن أو الأب؟', '["فور استدعاء fork() لكل الصفحات","عند أول قراءة من الصفحة","فقط عند انتهاء العملية الأب","عندما يحاول أحدهما الكتابة إلى الصفحة المشتركة"]'::jsonb, 3, 40, 16, 'multi', 'يسمح copy-on-write للأب والابن بمشاركة الصفحات مبدئيًا على أنها للقراءة. تُنشأ نسخة خاصة عند محاولة الكتابة، مما يؤجل النسخ ويتجنب نسخ صفحات لن تتغير.', 'العمليات والذاكرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'عملية ذات ثلاثة خيوط مستخدم تنتقل من النمط المستخدم إلى النواة لتنفيذ system call حاجب. في نموذج one-to-one، ما النتيجة الأصح؟', '["تُحجب العملية كلها بالضرورة لأن الخيوط تشترك في فضاء العناوين","يتحول الاستدعاء الحاجب تلقائيًا إلى غير حاجب","يمكن للنواة حجب ذلك الخيط وحده مع استمرار خيوط العملية الأخرى القابلة للتشغيل","تنشئ النواة عملية جديدة لكل استدعاء"]'::jsonb, 2, 45, 17, 'multi', 'في نموذج one-to-one يقابل كل خيط مستخدم خيطًا قابلًا للجدولة في النواة، ولذلك يمكن أن ينام الخيط الذي نفذ الاستدعاء الحاجب بينما تستمر خيوط أخرى من العملية نفسها.', 'الخيوط');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في نظام ملفات يستخدم journaling للبيانات الوصفية فقط، ما الضمان الأساسي المقصود بعد انقطاع مفاجئ للطاقة؟', '["إعادة بنية نظام الملفات إلى حالة متسقة، دون ضمان أن أحدث محتوى للملفات كُتب كاملًا","استعادة كل بايت من آخر عملية كتابة تطبيقية حتمًا","منع تلف القرص الفيزيائي","الاستغناء عن التخزين المؤقت للكتابة"]'::jsonb, 0, 45, 18, 'multi', 'تسجيل تغييرات البيانات الوصفية في journal يسمح بإعادة تشغيل المعاملات واستعادة اتساق البنية بعد الانهيار. لكنه لا يساوي تسجيل بيانات الملفات نفسها، لذا قد لا تكون أحدث البيانات التطبيقية محفوظة.', 'أنظمة الملفات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_52, 'في جدولة Round Robin، ماذا يحدث عادةً إذا صُغّرت الشريحة الزمنية كثيرًا جدًا مقارنة بزمن التبديل السياقي؟', '["تتحول الخوارزمية إلى FCFS تمامًا","يختفي زمن الاستجابة من دون أي كلفة","ترتفع كلفة التبديل السياقي وتنخفض كفاءة المعالج","تُمنع العمليات ذات الدفعات الطويلة من التنفيذ كليًا"]'::jsonb, 2, 40, 19, 'multi', 'الشريحة الصغيرة تحسن سرعة التناوب حتى حد ما، لكن إذا قاربت كلفة تبديل السياق يُستهلك جزء كبير من وقت المعالج في الحفظ والاستعادة بدل تنفيذ العمل الفعلي.', 'جدولة المعالج');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_53 uuid;
BEGIN
  SELECT id INTO v_lib_id_53 FROM quizzes WHERE title = 'الذكاء الاصطناعي والأمن السيبراني' LIMIT 1;
  IF v_lib_id_53 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الذكاء الاصطناعي والأمن السيبراني', 'تكنولوجيا', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_53;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في تعلم الآلة الخاضع للإشراف، ما الوظيفة الأساسية لمجموعة التحقق (validation set)؟', '["تقدير التعميم النهائي بعد تثبيت جميع القرارات","زيادة عدد أمثلة التدريب بنسخها","تخزين الأوزان بعد كل دفعة","ضبط المعلمات الفائقة واختيار النموذج دون التدريب عليها مباشرة"]'::jsonb, 3, 35, 0, 'multi', 'تُستخدم مجموعة التحقق للمفاضلة بين النماذج وضبط المعلمات الفائقة، بينما تُحجز مجموعة الاختبار لتقدير الأداء النهائي بعد انتهاء الاختيارات؛ وإلا تسرب أثر الاختيار إلى التقييم.', 'تعلم الآلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'أي وصف يميز التصيد الاحتيالي الموجّه (spear phishing) عن التصيد العام؟', '["يستهدف شخصًا أو جهة بعينها برسالة مصممة من معلومات سياقية","يعمل حصرًا عبر رسائل SMS","يستغل ثغرة ذاكرة بلا تفاعل بشري","يمنع الضحية من فتح المرفقات"]'::jsonb, 0, 30, 1, 'multi', 'التصيد الموجّه يستخدم سياقًا يخص ضحية أو مؤسسة محددة لرفع مصداقية الخداع، بخلاف الحملات العامة واسعة التوزيع؛ ولا يرتبط بوسيلة اتصال واحدة.', 'هندسة اجتماعية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ماذا يحقق التجزئة المملحة لكلمات المرور مقارنة بتجزئة كل كلمة منفردة بلا ملح؟', '["تجعل كلمة المرور قابلة للاسترجاع بمفتاح خاص","تمنع أي تخمين متصل بالشبكة","تجعل القيم المتطابقة تنتج تجزئات مختلفة وتضعف فاعلية الجداول المحسوبة مسبقًا","تستبدل الحاجة إلى دالة اشتقاق بطيئة"]'::jsonb, 2, 35, 2, 'multi', 'الملح قيمة عشوائية فريدة تُدخل مع كلمة المرور؛ لذا لا تتساوى التجزئات حتى عند تساوي الكلمات، وتصبح الجداول المسبقة غير مجدية على نطاق واسع. لكنه لا يمنع التخمين ولا يغني عن دالة اشتقاق مناسبة.', 'مصادقة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في مصفوفة الالتباس لمصنف ثنائي، ماذا تعني الحالة الإيجابية الكاذبة؟', '["تنبأ النموذج بالسالب وكانت الحقيقة موجبة","تنبأ النموذج بالموجب وكانت الحقيقة سالبة","تنبأ النموذج بالموجب وكانت الحقيقة موجبة","رفض النموذج إصدار تنبؤ"]'::jsonb, 1, 30, 3, 'multi', 'الإيجابي الكاذب هو إنذار أو تصنيف موجب لحالة سالبة في الحقيقة. ويقابله السلبي الكاذب، حيث يفوّت المصنف حالة موجبة فعلية.', 'تقييم النماذج');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'أي خاصية أمنية توفرها التوقيعات الرقمية مباشرة عند التحقق الصحيح؟', '["سرية محتوى الرسالة","إخفاء عنوان المرسل الشبكي","أصالة المنشأ وسلامة البيانات","منع نسخ الملف الموقّع"]'::jsonb, 2, 30, 4, 'multi', 'يتيح التوقيع الرقمي كشف تعديل البيانات وربط التوقيع بحائز المفتاح الخاص، فيدعم السلامة وأصالة المنشأ. أما السرية فتحتاج إلى التشفير، والتوقيع لا يمنع النسخ.', 'تشفير تطبيقي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'لماذا يُعد مبدأ أقل امتياز (least privilege) مفيدًا حتى إذا اختُرق حساب مستخدم؟', '["لأنه يحد الصلاحيات المتاحة للحساب، فيقل نطاق الضرر المحتمل","لأنه يضمن اكتشاف الاختراق فورًا","لأنه يشفر جميع الملفات تلقائيًا","لأنه يلغي الحاجة إلى المصادقة المتعددة"]'::jsonb, 0, 30, 5, 'multi', 'يقصر أقل امتياز كل كيان على الصلاحيات اللازمة لمهمته. وعند اختراقه لا يرث المهاجم تلقائيًا قدرات إدارية أو وصولًا أوسع، فينخفض نصف قطر الانفجار.', 'ضبط الوصول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما الفرق الجوهري بين التشفير المتماثل وغير المتماثل؟', '["المتماثل يضمن التوقيع دائمًا، وغير المتماثل يضمن السرية دائمًا","غير المتماثل لا يعتمد على مسائل رياضية","المتماثل يستخدم مفتاحًا مشتركًا للتشفير وفكّه، وغير المتماثل يستخدم زوج مفتاحين مترابطين","المتماثل لا يمكن تطبيقه على البيانات الرقمية"]'::jsonb, 2, 30, 6, 'multi', 'في التشفير المتماثل يشترك الطرفان في مفتاح سري، أما الأنظمة غير المتماثلة فتستخدم مفتاحًا عامًا وآخر خاصًا بعلاقة رياضية. ولا يعني نوع المفتاح وحده تحقق كل غرض أمني تلقائيًا.', 'تشفير');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في هجوم حقن SQL، ما الإجراء البرمجي الأكثر مباشرة لمنع مدخل المستخدم من تغيير بنية الاستعلام؟', '["ترميز قاعدة البيانات بـ UTF-8","استخدام استعلامات معلّمة (parameterized queries) تفصل البيانات عن الشيفرة","إخفاء رسائل الخطأ وحده","زيادة طول كلمة مرور مدير القاعدة"]'::jsonb, 1, 35, 7, 'multi', 'تربط الاستعلامات المعلّمة المدخلات كقيم لا كأجزاء قابلة للتفسير من صياغة SQL، فتمنعها من تعديل بنية الأمر. إخفاء الأخطاء مفيد لكنه لا يزيل الثغرة.', 'أمن التطبيقات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما المقصود بفرط التكيّف (overfitting) في نموذج تعلم آلة؟', '["انخفاض الأداء على التدريب والاختبار معًا بسبب بساطة النموذج","استخدام بيانات أقل من سعة التخزين","تشغيل النموذج على أكثر من معالج","تعلم النموذج تفاصيل وضوضاء بيانات التدريب على حساب التعميم على بيانات جديدة"]'::jsonb, 3, 30, 8, 'multi', 'يحدث فرط التكيّف حين يطابق النموذج خصائص خاصة بعينة التدريب، بما فيها الضوضاء، فيبدو أداؤه التدريبي قويًا بينما يتدهور على أمثلة لم يرها.', 'تعلم الآلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في نموذج السرية والسلامة والتوافر (CIA triad)، أي حادث يمس التوافر أساسًا؟', '["قراءة ملف سري بلا تصريح","إغراق خدمة بطلبات يمنع المستخدمين الشرعيين من الوصول","تعديل سجل مالي خلسة","انتحال توقيع مطور"]'::jsonb, 1, 30, 9, 'multi', 'التوافر يعني إتاحة المعلومات والخدمات عند الحاجة. إغراق الخدمة يعطل الوصول المشروع، بينما القراءة غير المصرح بها تمس السرية والتعديل الخفي يمس السلامة.', 'مبادئ الأمن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في محول (Transformer)، ما الذي تسمح به آلية الانتباه الذاتي تحديدًا؟', '["تحديث الأوزان من دون دالة خسارة","ربط تمثيل كل موضع بمواضع أخرى عبر أوزان مشتقة من الاستعلامات والمفاتيح","ضغط جميع الرموز إلى قيمة ثابتة قبل المعالجة","استبدال التضمينات بقواعد نحوية مكتوبة يدويًا"]'::jsonb, 1, 45, 10, 'multi', 'يحسب الانتباه توافق الاستعلام مع مفاتيح المواضع، ثم يستخدم الأوزان لدمج قيمها؛ وهكذا يعتمد تمثيل الرمز على سياقه حتى لو كان بعيدًا، من دون اشتراط تكرار زمني.', 'نماذج عميقة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'لماذا لا تكفي دالة تجزئة عادية سريعة مثل SHA-256 وحدها لتخزين كلمات المرور بأمان؟', '["لأنها لا تنتج خرجًا ثابت الطول","لأنها تستخدم مفتاحًا عامًا","لأن سرعتها تمكّن المهاجم من اختبار عدد هائل من التخمينات، بخلاف دوال اشتقاق قابلة لزيادة الكلفة","لأنها تعيد كلمة المرور عند اصطدام تجزئتين"]'::jsonb, 2, 45, 11, 'multi', 'صُممت SHA-256 للكفاءة العامة، وهذه السرعة تفيد التخمين غير المتصل بعد تسريب التجزئات. دوال اشتقاق كلمات المرور تضيف ملحًا وكلفة قابلة للضبط، وقد تضيف كلفة ذاكرة، لإبطاء كل محاولة.', 'مصادقة وتجزئة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في TLS 1.3، ما فائدة استخدام تبادل مفاتيح (EC)DHE في المصافحة العادية؟', '["يجعل شهادة الخادم غير ضرورية في كل الحالات","يمنع الخادم من مصادقة العميل","يحوّل التشفير المتماثل إلى تجزئة بلا مفتاح","يوفر سرية أمامية لأن مفاتيح الجلسة لا تُشتق من مفتاح الخادم طويل الأمد وحده"]'::jsonb, 3, 45, 12, 'multi', 'يولّد (EC)DHE أسرارًا مؤقتة للجلسة؛ لذلك لا يكشف الاستيلاء اللاحق على مفتاح مصادقة الخادم طويل الأمد مفاتيح جلسات سابقة مسجلة، وهي خاصية السرية الأمامية.', 'أمن الشبكات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'أي سيناريو يصف هجوم تسميم بيانات التدريب (data poisoning)؟', '["تعديل مدخل وقت الاستدلال فقط لإرباك نموذج ثابت","سرقة أوزان النموذج عبر نسخة احتياطية","إدخال أمثلة خبيثة في بيانات التدريب للتأثير في سلوك النموذج المتعلم","قياس زمن الاستجابة لاستنتاج مفتاح تشفير"]'::jsonb, 2, 45, 13, 'multi', 'التسميم يستهدف مرحلة التدريب أو بياناتها ليغيّر النموذج الناتج، وقد يخفض دقته أو يزرع بابًا خلفيًا. أما تعديل مثال عند الاستدلال فهو تهرب خصومي لا تسميم تدريب.', 'أمن تعلم الآلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما الضمان المركزي للخصوصية التفاضلية عند مقارنة مجموعتي بيانات تختلفان في سجل فرد واحد؟', '["تبقى احتمالات المخرجات متقاربة ضمن حد مضبوط، فيصعب استنتاج مشاركة الفرد","يجب أن تكون مخرجات الآلية متطابقة حرفيًا","تُحذف جميع السمات الحساسة من البيانات","لا يمكن للمهاجم معرفة أي إحصاء سكاني"]'::jsonb, 0, 50, 14, 'multi', 'تحد الخصوصية التفاضلية من مقدار تغير توزيع المخرجات عند إضافة سجل فرد أو حذفه، باستخدام معاملي الخصوصية ε وδ بحسب التعريف؛ وهي لا تتطلب تطابق النتائج ولا تمنع الإحصاءات المفيدة.', 'خصوصية البيانات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما سبب خطورة إعادة استخدام nonce مع المفتاح نفسه في نمط AES-GCM؟', '["يزيد طول النص المشفر فقط","يحوّل AES تلقائيًا إلى RSA","يمنع فك التشفير حتى بالمفتاح الصحيح من دون أي أثر آخر","قد يكشف علاقات بين النصوص الصريحة ويقوض سلامة وسوم المصادقة"]'::jsonb, 3, 50, 15, 'multi', 'يعتمد GCM على عدم تكرار متجه البدء مع المفتاح. التكرار يعيد استخدام تدفق العداد فيكشف XOR النصوص الصريحة، كما يتيح علاقات جبرية قد تؤدي إلى تزوير وسوم المصادقة.', 'تشفير موثّق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في بنية انعدام الثقة (Zero Trust)، على أي افتراض يجب ألا يعتمد قرار الوصول؟', '["هوية الكيان وسلامة جهازه","الثقة الضمنية لمجرد وجود الطلب داخل شبكة المؤسسة","سياسة وصول ديناميكية","الحد الأدنى من الصلاحيات اللازمة"]'::jsonb, 1, 45, 16, 'multi', 'يلغي انعدام الثقة الامتياز الضمني الناتج من الموقع الشبكي. تُقيّم طلبات الوصول وفق الهوية والجهاز والسياسة والسياق، سواء جاء الطلب من داخل المحيط التقليدي أم خارجه.', 'معمارية أمنية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما المقياس الأنسب عندما تكون الفئة الموجبة نادرة وتريد موازنة الدقة الإيجابية (precision) والاستدعاء (recall) في رقم واحد؟', '["درجة F1 بوصفها المتوسط التوافقي لـ precision وrecall","المتوسط الحسابي للدقة الكلية والخسارة","معدل الإيجابيات الحقيقية وحده","الخطأ التربيعي المتوسط للملصقات"]'::jsonb, 0, 45, 17, 'multi', 'درجة F1 هي المتوسط التوافقي للدقة الإيجابية والاستدعاء، فتكون مرتفعة فقط إذا كان الاثنان مرتفعين. أما الدقة الكلية فقد تبدو ممتازة في بيانات غير متوازنة لمجرد توقع الفئة الشائعة.', 'تقييم النماذج');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'لماذا يُستخدم HMAC بدل الاكتفاء بحساب تجزئة عادية للرسالة عند طلب مصادقة مصدرها؟', '["لأن HMAC يشفر الرسالة ويخفي طولها","لأن HMAC يضم مفتاحًا سريًا في بناء مصمم لمقاومة التزوير، بخلاف التجزئة العامة التي يستطيع أي شخص حسابها","لأن التجزئة العادية لا تكشف التعديل إطلاقًا","لأن HMAC لا يحتاج إلى خوارزمية تجزئة"]'::jsonb, 1, 50, 18, 'multi', 'يمكن لأي طرف حساب تجزئة رسالة معدلة، فلا تثبت مصدرًا. أما HMAC فيربط وسم السلامة بمفتاح سري مشترك عبر بناء محدد، فيدعم مصادقة الرسالة وسلامتها من مهاجم لا يملك المفتاح.', 'تشفير تطبيقي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'أي شرط يميز هجوم نقل الحالة (CSRF) الكلاسيكي على تطبيق ويب؟', '["ينفذ المتصفح طلبًا غير مرغوب فيه مستفيدًا من بيانات اعتماد يرفقها تلقائيًا لجلسة الضحية","يشغّل المهاجم شيفرة SQL داخل قاعدة البيانات بلا جلسة","يقرأ المهاجم الذاكرة الفيزيائية عبر DMA فقط","يغيّر خادم DNS المفتاح الخاص للشهادة"]'::jsonb, 0, 45, 19, 'multi', 'يخدع CSRF متصفح مستخدم مصادق عليه لإرسال طلب تغييري، وتلحق به ملفات الارتباط أو بيانات الجلسة تلقائيًا. لذلك تشمل الدفاعات رموز CSRF وSameSite والتحقق من المصدر.', 'أمن الويب');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في MITRE ATT&CK، ما الفرق بين التكتيك والتقنية؟', '["التكتيك أداة برمجية، والتقنية عنوان IP","التقنية مرحلة أعلى من التكتيك دائمًا","لا فرق؛ المصطلحان مترادفان","التكتيك يصف هدف الخصم المرحلي، والتقنية تصف الكيفية التي يسعى بها لتحقيقه"]'::jsonb, 3, 45, 20, 'multi', 'التكتيك يمثل الغاية المرحلية مثل اكتساب الاعتماد أو الحركة الجانبية، بينما التقنية تمثل الأسلوب المستخدم لتحقيق تلك الغاية؛ وقد تُسهم تقنية في أكثر من سياق تكتيكي.', 'نمذجة سلوك الخصوم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'ما الذي يميز هجوم استدلال العضوية (membership inference) على نموذج تعلم آلة؟', '["يحاول تحديد هل كان سجل معين ضمن بيانات تدريب النموذج","يستخرج المفتاح الخاص من شهادة TLS","يضيف أمثلة مسمومة قبل التدريب","يحوّل نموذج التصنيف إلى نموذج انحدار"]'::jsonb, 0, 50, 21, 'multi', 'هدف استدلال العضوية هو تمييز ما إذا استُخدم سجل بعينه في التدريب، غالبًا باستغلال اختلافات الثقة أو السلوك بين أمثلة التدريب وغيرها؛ لذا فهو تهديد خصوصية لا تسميم بيانات.', 'خصوصية تعلم الآلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في DNSSEC، ماذا تثبت سلسلة الثقة بنجاح، وماذا لا توفر؟', '["تخفي اسم النطاق وتضمن توافر الخادم","تستبدل TLS وتثبت محتوى صفحة الويب","تثبت أصالة وسلامة بيانات DNS الموقعة، لكنها لا تشفر استعلام DNS أو جوابه","تمنع تسجيل أي نطاق مشابه بصريًا"]'::jsonb, 2, 50, 22, 'multi', 'تتحقق DNSSEC بالتوقيعات وسلسلة المفاتيح من أن بيانات DNS أصلية ولم تُعدّل، لكنها لا تضيف سرية للنقل؛ يمكن لمراقب الشبكة رؤية الاستعلام والجواب ما لم تُستخدم قناة مشفرة منفصلة.', 'أمن DNS');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'في التعلم الاتحادي (federated learning)، لماذا لا يعني بقاء البيانات الخام على الأجهزة تحقق الخصوصية تلقائيًا؟', '["لأن الخادم يجب أن ينسخ جميع البيانات الخام قبل كل جولة","لأن تحديثات النموذج نفسها قد تسرب معلومات، فتظل الحاجة إلى تجميع آمن أو خصوصية تفاضلية بحسب التهديد","لأن النموذج لا يتعلم إلا من بيانات عامة","لأن التشفير يمنع جمع التحديثات نهائيًا"]'::jsonb, 1, 50, 23, 'multi', 'التعلم الاتحادي يقلل مركزية البيانات الخام، لكن التدرجات أو تحديثات المعلمات قد تحمل إشارات عن أمثلة العملاء. لذلك تُضاف تقنيات مثل التجميع الآمن والخصوصية التفاضلية وفق نموذج التهديد.', 'تعلم موزع آمن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_53, 'أي وصف أدق لهجوم حقن التعليمات (prompt injection) على تطبيق يستخدم نموذجًا لغويًا مع أدوات خارجية؟', '["تعديل أوزان النموذج أثناء التدريب فقط","تجاوز جدار ناري عبر تجزئة كلمة المرور","زيادة طول السياق لتحسين الدقة بلا أثر أمني","مدخل غير موثوق يحاول تغيير تعليمات النموذج أو حمله على استخدام أدوات بما يخالف قصد التطبيق"]'::jsonb, 3, 50, 24, 'multi', 'ينشأ الحقن حين تُعامل بيانات الخصم كتعليمات مؤثرة، مباشرة أو عبر محتوى مسترجع. وتزداد الخطورة مع الأدوات؛ لذا يلزم تقييد الصلاحيات والتحقق من الإجراءات وعدم اعتبار الفصل النصي حدًا أمنيًا كافيًا.', 'أمن النماذج اللغوية');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_54 uuid;
BEGIN
  SELECT id INTO v_lib_id_54 FROM quizzes WHERE title = 'تاريخ كأس العالم والبطولات الكبرى' LIMIT 1;
  IF v_lib_id_54 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('تاريخ كأس العالم والبطولات الكبرى', 'رياضة', '', 'medium', 'ar', true)
    RETURNING id INTO v_lib_id_54;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'في النسخة الافتتاحية لكأس العالم عام 1930، أي منتخب فاز باللقب وعلى حساب مَن في المباراة النهائية؟', '["الأرجنتين على أوروغواي","إيطاليا على تشيكوسلوفاكيا","البرازيل على يوغوسلافيا","أوروغواي على الأرجنتين"]'::jsonb, 3, 30, 0, 'multi', 'استضافت أوروغواي النسخة الأولى، وهزمت الأرجنتين 4–2 في النهائي بملعب سنتيناريو لتصبح أول بطلة للعالم.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'لماذا لا تُعد مباراة البرازيل وأوروغواي الحاسمة في مونديال 1950 نهائيًا تقليديًا من مباراة واحدة؟', '["لأنها أُعيدت مرتين","لأن المرحلة الختامية كانت مجموعة من أربعة منتخبات","لأن اللقب حُسم بفارق الأهداف قبلها","لأنها كانت مباراة فاصلة بعد تعادل نهائي"]'::jsonb, 1, 30, 1, 'multi', 'حُسم مونديال 1950 عبر مجموعة نهائية رباعية. جاءت مباراة أوروغواي والبرازيل في جولتها الأخيرة وحسم فوز أوروغواي 2–1 اللقب، لكنها لم تكن نهائيًا بنظام خروج المغلوب.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي إنجاز فردي حققه جيف هيرست في نهائي كأس العالم 1966 وظل فريدًا في نهائيات الرجال حتى نسخة 2022؟', '["سجل في كل مباريات البطولة","سجل ثلاثية في المباراة النهائية","أحرز هدفًا من منتصف الملعب","صد ركلتي جزاء في النهائي"]'::jsonb, 1, 30, 2, 'multi', 'سجل هيرست ثلاثة أهداف لإنجلترا في فوزها 4–2 على ألمانيا الغربية. ظل صاحب الثلاثية الوحيدة في نهائي كأس العالم للرجال إلى أن سجل كيليان مبابي ثلاثية في نهائي 2022.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما الأثر المباشر لفوز البرازيل بكأس العالم للمرة الثالثة عام 1970 على كأس جول ريميه؟', '["مُنحت البرازيل حق الاحتفاظ بها نهائيًا","أُعيدت الكأس إلى أوروغواي","أُلغيت قاعدة احتساب الأهداف","أصبح اسمها كأس القارات"]'::jsonb, 0, 30, 3, 'multi', 'نصت القاعدة على احتفاظ أول منتخب يفوز بالبطولة ثلاث مرات بكأس جول ريميه. حققت البرازيل فوزها الثالث في 1970، فاحتفظت بالكأس واستُحدثت كأس جديدة للنسخ التالية.', 'كؤوس ورموز');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي تغيير بنيوي بارز شهدته نهائيات كأس العالم في إسبانيا 1982؟', '["إدخال ركلات الترجيح لأول مرة","رفع عدد المنتخبات من 16 إلى 24","إلغاء دور المجموعات","رفع عدد المنتخبات من 24 إلى 32"]'::jsonb, 1, 30, 4, 'multi', 'كانت إسبانيا 1982 أول نسخة تضم 24 منتخبًا بدلًا من 16، ما وسّع تمثيل الاتحادات القارية وفرض مرحلتين من المجموعات قبل نصف النهائي.', 'نظم البطولات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما السابقة التي سجلها نهائي كأس العالم 1994 بين البرازيل وإيطاليا؟', '["أول نهائي يُحسم بهدف ذهبي","أول نهائي يُعاد في اليوم التالي","أول نهائي يُحسم بركلات الترجيح","أول نهائي بلا بطاقات"]'::jsonb, 2, 30, 5, 'multi', 'انتهى النهائي بالتعادل 0–0 بعد الوقت الإضافي، ثم فازت البرازيل بركلات الترجيح، فكان أول نهائي لكأس العالم يُحسم بهذه الوسيلة.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'بماذا تميزت استضافة كأس العالم 2002 تاريخيًا؟', '["أول نسخة خارج أوروبا فقط","أول نسخة في آسيا وأول استضافة مشتركة","أول نسخة تقام شتاءً","أول نسخة بثلاث دول مضيفة"]'::jsonb, 1, 30, 6, 'multi', 'نظمت كوريا الجنوبية واليابان بطولة 2002، فكانت أول كأس عالم في آسيا وأول نسخة يشترك بلدان في استضافتها.', 'استضافة البطولات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما الإنجاز الجغرافي الذي حققته إسبانيا بتتويجها في جنوب أفريقيا 2010؟', '["أول منتخب أفريقي يفوز باللقب","أول منتخب أوروبي يفوز بكأس العالم خارج أوروبا","أول حامل لقب يفوز بكل مبارياته","أول منتخب يفوز دون استقبال أهداف"]'::jsonb, 1, 30, 7, 'multi', 'بتغلبها على هولندا في جوهانسبرغ، أصبحت إسبانيا أول منتخب أوروبي يتوج بكأس العالم في بطولة أقيمت خارج القارة الأوروبية.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي منتخب أصبح في 2014 أول منتخب أوروبي يحرز كأس العالم في قارتي أمريكا؟', '["ألمانيا","إيطاليا","فرنسا","إسبانيا"]'::jsonb, 0, 30, 8, 'multi', 'فازت ألمانيا على الأرجنتين 1–0 في ريو دي جانيرو، فكانت أول دولة أوروبية تتوج بكأس العالم على أرض من قارتي أمريكا.', 'كأس العالم لكرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما أول بطولة دولية كبرى للمنتخبات أُقيمت ضمن الألعاب الأولمبية للسيدات عام 1996، ومن فاز بها؟', '["الرجبي؛ نيوزيلندا","الكريكيت؛ أستراليا","كرة القدم؛ النرويج","كرة القدم؛ الولايات المتحدة"]'::jsonb, 3, 30, 9, 'multi', 'دخلت كرة القدم النسائية البرنامج الأولمبي في أتلانتا 1996، وفازت الولايات المتحدة بالذهب بعد تغلبها على الصين في النهائي.', 'الألعاب الأولمبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'من المدرب الوحيد الذي قاد منتخبًا إلى لقبين متتاليين في كأس العالم للرجال، وفي أي نسختين؟', '["هيلمو شون؛ 1970 و1974","كارلوس بيلاردو؛ 1986 و1990","ماريو زاغالو؛ 1958 و1962","فيتوريو بوتسو؛ 1934 و1938"]'::jsonb, 3, 40, 10, 'multi', 'قاد فيتوريو بوتسو إيطاليا إلى لقبي 1934 و1938، وهو المدرب الوحيد الذي فاز بكأس العالم للرجال في نسختين متتاليتين.', 'مدربون');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي منتخب سجل 27 هدفًا في مونديال 1954، وهو أعلى رصيد لمنتخب في نسخة واحدة؟', '["أوروغواي","ألمانيا الغربية","المجر","النمسا"]'::jsonb, 2, 40, 11, 'multi', 'سجل منتخب المجر 27 هدفًا في خمس مباريات بسويسرا 1954. ورغم قوته الهجومية، خسر النهائي 3–2 أمام ألمانيا الغربية.', 'سجلات كأس العالم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما الرقم العمري الذي ارتبط ببيليه في نهائي كأس العالم 1958؟', '["أصغر لاعب يسجل في نهائي، بعمر 17 عامًا و249 يومًا","أصغر قائد يرفع الكأس","أصغر حارس يحافظ على شباكه","أصغر لاعب يطرد في نهائي"]'::jsonb, 0, 40, 12, 'multi', 'سجل بيليه هدفين أمام السويد في النهائي وهو في السابعة عشرة و249 يومًا، فأصبح أصغر مسجل في نهائي كأس العالم.', 'سجلات كأس العالم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي كأس رُفعت لأول مرة في مونديال 1974 بعد إحالة كأس جول ريميه إلى التقاعد؟', '["كأس القارات","كأس النصر الأولمبي","كأس العالم FIFA الحالية","كأس هنري ديلوناي"]'::jsonb, 2, 40, 13, 'multi', 'استُحدثت كأس العالم FIFA التي صممها سيلفيو غازانيغا، ورفعها منتخب ألمانيا الغربية لأول مرة بعد فوزه بنهائي 1974.', 'كؤوس ورموز');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي منتخب حقق أول فوز لمنتخب أفريقي في تاريخ نهائيات كأس العالم، وفي أي نسخة؟', '["المغرب في 1970","الجزائر في 1982","الكاميرون في 1990","تونس في 1978"]'::jsonb, 3, 40, 14, 'multi', 'هزمت تونس المكسيك 3–1 في الأرجنتين 1978، مسجلة أول انتصار لمنتخب أفريقي في نهائيات كأس العالم.', 'أفريقيا في كأس العالم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ما السابقة الأفريقية التي حققها المغرب في كأس العالم 1986؟', '["أول منتخب أفريقي يبلغ النهائي","أول منتخب أفريقي يفوز بركلات الترجيح","أول منتخب أفريقي يتصدر مجموعته ويبلغ دور الـ16","أول منتخب أفريقي يستضيف البطولة"]'::jsonb, 2, 40, 15, 'multi', 'تصدر المغرب مجموعته أمام إنجلترا وبولندا والبرتغال، وأصبح أول منتخب أفريقي يعبر دور المجموعات إلى دور الـ16.', 'أفريقيا في كأس العالم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي منتخب أصبح في إيطاليا 1990 أول ممثل لأفريقيا يبلغ ربع نهائي كأس العالم؟', '["الكاميرون","نيجيريا","الجزائر","مصر"]'::jsonb, 0, 40, 16, 'multi', 'بلغت الكاميرون ربع النهائي بعد الفوز على الأرجنتين ورومانيا وكولومبيا، ثم خسرت أمام إنجلترا بعد وقت إضافي.', 'أفريقيا في كأس العالم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي نسخة كانت الأولى التي تضم 32 منتخبًا في نهائيات كأس العالم للرجال؟', '["فرنسا 1998","الولايات المتحدة 1994","كوريا واليابان 2002","ألمانيا 2006"]'::jsonb, 0, 40, 17, 'multi', 'توسعت النهائيات من 24 إلى 32 منتخبًا في فرنسا 1998، موزعة على ثماني مجموعات من أربعة منتخبات.', 'نظم البطولات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'من تُوج بالنسخة الأولى من بطولة أمم أوروبا عام 1960، وأين أُقيمت المرحلة النهائية؟', '["إسبانيا؛ إيطاليا","يوغوسلافيا؛ الاتحاد السوفيتي","الاتحاد السوفيتي؛ فرنسا","ألمانيا الغربية؛ بلجيكا"]'::jsonb, 2, 45, 18, 'multi', 'استضافت فرنسا المرحلة النهائية للبطولة الأوروبية الأولى، وفاز الاتحاد السوفيتي على يوغوسلافيا 2–1 بعد وقت إضافي في النهائي.', 'كأس أمم أوروبا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'ارتبط اسم أنتونين بانينكا بنهائي بطولة أمم أوروبا 1976 بسبب أي لقطة؟', '["هدف ذهبي بالرأس","تصديه لثلاث ركلات جزاء","ركلة جزاء ساقطة حسمت ركلات الترجيح","أسرع هدف في تاريخ النهائي"]'::jsonb, 2, 45, 19, 'multi', 'نفذ بانينكا الركلة الحاسمة لتشيكوسلوفاكيا بتسديدة ساقطة في وسط المرمى أمام ألمانيا الغربية، فأصبح هذا الأسلوب يحمل اسمه.', 'كأس أمم أوروبا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'كيف وصلت الدنمارك إلى نهائيات يورو 1992 التي فازت بلقبها؟', '["دُعيت بدل يوغوسلافيا المستبعدة","تأهلت بصفتها حاملة اللقب","فازت بملحق بعد بدء البطولة","تأهلت بصفتها الدولة المضيفة"]'::jsonb, 0, 45, 20, 'multi', 'احتلت الدنمارك المركز الثاني خلف يوغوسلافيا في مجموعتها، ثم دخلت النهائيات بدل يوغوسلافيا المستبعدة قبل البطولة، وتوجت بالفوز على ألمانيا في النهائي.', 'كأس أمم أوروبا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي بطولة بدأت في الأرجنتين عام 1916 وتعد أقدم بطولة قارية لمنتخبات كرة القدم؟', '["كأس أمم أوروبا","الكأس الذهبية","كأس آسيا","كوبا أمريكا"]'::jsonb, 3, 45, 21, 'multi', 'أقيمت بطولة أمريكا الجنوبية الأولى في الأرجنتين عام 1916 بالتزامن مع تأسيس اتحاد كونميبول، وتطورت لاحقًا إلى كوبا أمريكا.', 'كوبا أمريكا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'من فاز بالنسخة الأولى من كأس العالم للرجبي عام 1987، وعلى حساب أي منتخب في النهائي؟', '["أستراليا على إنجلترا","جنوب أفريقيا على نيوزيلندا","فرنسا على ويلز","نيوزيلندا على فرنسا"]'::jsonb, 3, 45, 22, 'multi', 'استضافت نيوزيلندا وأستراليا النسخة الأولى، وفازت نيوزيلندا على فرنسا 29–9 في نهائي أوكلاند.', 'كأس العالم للرجبي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي منتخب فاز بكأس العالم الأولى للكريكيت للرجال عام 1975، وأين أقيم النهائي؟', '["أستراليا؛ ملبورن","جزر الهند الغربية؛ لوردز","إنجلترا؛ ذا أوفال","الهند؛ إيدن غاردنز"]'::jsonb, 1, 45, 23, 'multi', 'تغلبت جزر الهند الغربية على أستراليا في نهائي 1975 بملعب لوردز في لندن، لتصبح أول بطلة لكأس العالم للكريكيت للرجال.', 'كأس العالم للكريكيت');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_54, 'أي نادٍ أصبح أول بطل للمسابقة بعد اعتماد اسم «دوري أبطال أوروبا» في موسم 1992–1993؟', '["ميلان","برشلونة","بايرن ميونخ","مارسيليا"]'::jsonb, 3, 45, 24, 'multi', 'فاز أولمبيك مارسيليا على ميلان 1–0 في نهائي ميونخ، فأصبح أول بطل تحت مسمى دوري أبطال أوروبا في موسم 1992–1993.', 'دوري أبطال أوروبا');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_55 uuid;
BEGIN
  SELECT id INTO v_lib_id_55 FROM quizzes WHERE title = 'إحصائيات وقوانين رياضية نادرة' LIMIT 1;
  IF v_lib_id_55 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('إحصائيات وقوانين رياضية نادرة', 'رياضة', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_55;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين IFAB للعبة 2025/2026، متى تصبح الكرة في اللعب عند ركلة البداية؟', '["عندما يلمسها لاعب ثانٍ","عندما تُركل وتتحرك بوضوح","عندما تتحرك إلى نصف ملعب الخصم","عند إطلاق الحكم صافرة ثانية"]'::jsonb, 1, 30, 0, 'multi', 'ينص القانون 8 على أن الكرة تصبح في اللعب بمجرد ركلها وتحركها بوضوح؛ ولا يشترط اتجاهها إلى الأمام أو لمس لاعب ثانٍ.', 'كرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قانون IFAB 14 لموسم 2025/2026، ما الوضع القانوني المطلوب لقدمي حارس المرمى لحظة تنفيذ ركلة الجزاء؟', '["كلتا القدمين أمام خط المرمى","كلتا القدمين تلامسان خط المرمى حتمًا","قدم واحدة على الأقل تلامس خط المرمى أو تكون بمحاذاته أو خلفه","قدم واحدة على الأقل داخل منطقة المرمى دون صلة بالخط"]'::jsonb, 2, 35, 1, 'multi', 'عند ركل الكرة يجب أن يكون جزء من قدم واحدة على الأقل ملامسًا لخط المرمى أو بمحاذاته أو خلفه؛ لذلك لا يلزم إبقاء القدمين كلتيهما على الخط.', 'كرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد FIBA الرسمية 2024، إذا استعاد الفريق المهاجم الكرة بعد أن لمست تسديدته الحلقة، إلى كم يُضبط جهاز توقيت التسديدة؟', '["24 ثانية","20 ثانية","8 ثوانٍ","14 ثانية"]'::jsonb, 3, 30, 2, 'multi', 'عندما تلمس التسديدة الحلقة ثم يسيطر الفريق نفسه مجددًا على الكرة، يُضبط توقيت التسديدة على 14 ثانية، لا على دورة جديدة كاملة من 24 ثانية.', 'كرة السلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في قواعد FIBA الرسمية 2024، خلال كم ثانية يجب على رامي الرمية الحرة إطلاق الكرة بعد أن يضعها الحكم تحت تصرفه؟', '["3 ثوانٍ","8 ثوانٍ","10 ثوانٍ","5 ثوانٍ"]'::jsonb, 3, 30, 3, 'multi', 'تلزم المادة 43 الرامي بإطلاق الكرة خلال خمس ثوانٍ من وضعها تحت تصرفه؛ تجاوز المدة مخالفة للرمية الحرة.', 'كرة السلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد FIVB للكرة الطائرة داخل الصالات 2025–2028، هل تُحسب ملامسة حائط الصد ضمن اللمسات الثلاث المسموحة للفريق؟', '["نعم، وتكون اللمسة الأولى دائمًا","لا، ويحق للفريق ثلاث لمسات أخرى بعد الصد","لا، لكن لا يبقى إلا لمستان","تُحسب فقط إذا لمسها لاعبان في الصد"]'::jsonb, 1, 30, 4, 'multi', 'ملامسة الصد لا تُعد ضربة من ضربات الفريق؛ لذلك يمكن للفريق تنفيذ ثلاث ضربات بعد ملامسة الصد لإعادة الكرة.', 'الكرة الطائرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد ITF للتنس 2025، ما ترتيب الإرسال الأساسي في شوط كسر التعادل؟', '["يرسل اللاعب الأول نقطة واحدة، ثم يرسل كل لاعب نقطتين بالتناوب","يرسل اللاعب الأول نقطتين ثم يتناوبان كل نقطة","يتناوب اللاعبان بعد كل نقطة طوال الشوط","يرسل مستقبل الشوط السابق أول ثلاث نقاط"]'::jsonb, 0, 35, 5, 'multi', 'يبدأ اللاعب الذي حان دوره بنقطة واحدة من جهة اليمين، ثم يرسل الخصم نقطتين، وبعد ذلك يستمر التناوب بواقع نقطتين لكل لاعب.', 'التنس');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين BWF للريشة الطائرة، إذا أصبحت نتيجة الشوط 29–29، فما الذي يحسم الشوط؟', '["فارق نقطتين مهما طال اللعب","ثلاث نقاط فاصلة متتالية","إعادة الشوط من الصفر","النقطة التالية؛ فيفوز من يبلغ 30"]'::jsonb, 3, 30, 6, 'multi', 'بعد 20–20 يلزم فارق نقطتين، لكن النظام يضع سقفًا: عند 29–29 يفوز بالشوط من يسجل النقطة الثلاثين أولًا.', 'الريشة الطائرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في سباق التتابع المتنوع 4×100 متر وفق قواعد World Aquatics، ما الترتيب الصحيح للسباحات الأربع؟', '["ظهر، صدر، فراشة، حرة","فراشة، ظهر، صدر، حرة","صدر، فراشة، ظهر، حرة","ظهر، فراشة، صدر، حرة"]'::jsonb, 0, 30, 7, 'multi', 'ترتيب التتابع المتنوع هو الظهر ثم الصدر ثم الفراشة ثم الحرة. ويختلف ذلك عن ترتيب الفردي المتنوع الذي يبدأ بالفراشة.', 'السباحة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين ITTF، ما أقل ارتفاع رأسي يجب أن ترتفع إليه الكرة بعد قذفها من الكف في الإرسال الصحيح بتنس الطاولة؟', '["10 سم","16 سم","12 سم","20 سم"]'::jsonb, 1, 30, 8, 'multi', 'يجب قذف الكرة شبه رأسي من كف مفتوحة بحيث ترتفع 16 سم على الأقل من دون إكسابها دورانًا عمدًا قبل ضربها.', 'تنس الطاولة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في سلاح الشيش (Foil) وفق قواعد FIE، أي منطقة تُعد هدفًا صالحًا أساسيًا؟', '["الجسم كله بما فيه القناع والساقان","الجزء الواقع فوق الخصر بما فيه الذراعان","الرأس والذراع المسلحة فقط","الجذع فقط وفق سطح الهدف المحدد، دون الأطراف"]'::jsonb, 3, 30, 9, 'multi', 'الهدف الصالح في الشيش هو الجذع المحدد بالسترة الكهربائية، بخلاف سيف المبارزة الذي يجعل الجسم كله هدفًا، والسيف العربي الذي يستهدف ما فوق الخصر مع استثناءات القاعدة.', 'المبارزة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد FIVB للكرة الطائرة داخل الصالات 2025–2028، متى يرتكب الليبيرو خطأ إكمال ضربة هجومية؟', '["إذا كانت الكرة لحظة الضرب أعلى من قمة الشبكة بالكامل","كلما ضرب الكرة بيد واحدة","إذا قفز من خلف خط الهجوم ولو كانت الكرة منخفضة","إذا كانت الضربة هي اللمسة الثالثة للفريق"]'::jsonb, 0, 45, 10, 'multi', 'لا يجوز لليبيرو إكمال ضربة هجومية من أي مكان إذا كانت الكرة بكاملها أعلى من الحافة العليا للشبكة لحظة الضرب؛ المعيار هو ارتفاع الكرة لا عدد اللمسات.', 'الكرة الطائرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد ITF للتنس 2025، ارتدت الكرة صحيحة داخل ملعب الخصم ثم لمست سياجًا ثابتًا قبل أن يتمكن الخصم من ردها. لمن النقطة؟', '["للخصم لأن السياج خارج الملعب","لضارب الكرة","تُعاد النقطة دائمًا","تُحتسب خطأ إرسال إن حدثت أثناء التبادل"]'::jsonb, 1, 45, 11, 'multi', 'إذا لمست الكرة الأرض داخل الملعب الصحيح ثم أصابت أحد الملحقات الثابتة قبل ردها، يفوز ضاربها بالنقطة؛ أما إصابة الملحق الثابت قبل الارتداد الصحيح فتُفقده النقطة.', 'التنس');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قانون ITTF للعب السريع (expedite system)، ما الذي يحدث إذا أعاد المستقبل الكرة 13 مرة بصورة صحيحة في تبادل واحد بعد تفعيل النظام؟', '["يفوز المستقبل بالنقطة","يفوز المرسل بالنقطة","تُعاد النقطة بإرسال جديد","ينتهي الشوط لمصلحة المتقدم"]'::jsonb, 0, 45, 12, 'multi', 'بعد تفعيل نظام التعجيل، إذا أتم المستقبل 13 ردًا صحيحًا في التبادل فإنه يربح النقطة، ما يمنع استمرار التبادلات الدفاعية بلا نهاية.', 'تنس الطاولة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد World Athletics، أي ترتيب يمثل مسابقات اليوم الثاني من العشاري للرجال؟', '["100 م، وثب طويل، جلة، وثب عالٍ، 400 م","110 م حواجز، جلة، وثب عالٍ، رمح، 800 م","110 م حواجز، قرص، قفز بالزانة، رمح، 1500 م","قرص، 400 م، قفز بالزانة، رمح، 5000 م"]'::jsonb, 2, 45, 13, 'multi', 'يبدأ اليوم الثاني للعشاري بـ110 م حواجز، ثم رمي القرص، فالقفز بالزانة، فرمي الرمح، وينتهي بسباق 1500 م؛ أما الخيار الثاني فهو ترتيب اليوم الأول.', 'ألعاب القوى');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في الفردي المتنوع بالسباحة وفق World Aquatics، ما الترتيب القانوني للأساليب الأربعة؟', '["فراشة، ظهر، صدر، حرة","ظهر، صدر، فراشة، حرة","فراشة، صدر، ظهر، حرة","صدر، ظهر، فراشة، حرة"]'::jsonb, 0, 40, 14, 'multi', 'ترتيب الفردي المتنوع هو الفراشة ثم الظهر ثم الصدر ثم الحرة، بينما يبدأ التتابع المتنوع بالظهر لأسباب مرتبطة ببداية سباحة الظهر.', 'السباحة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين World Rugby للاتحاد (15 لاعبًا)، إذا أمسك لاعب الكرة وهو خارج خط الـ22 ثم أعادها إلى داخل الـ22 وركلها مباشرة إلى التماس، فما الأصل في مكان تنفيذ رمية التماس؟', '["حيث عبرت الكرة خط التماس دائمًا","مقابل موضع الركلة، لأن الفريق أعاد الكرة إلى داخل الـ22","على خط الـ22 حتمًا","عند منتصف الملعب"]'::jsonb, 1, 50, 15, 'multi', 'لا يستفيد الفريق من كسب الأرض بالركل المباشر إلى التماس إذا كان هو من أعاد الكرة إلى داخل منطقة الـ22؛ تكون الرمية مقابل مكان الركلة، ما لم تقع حالة استثنائية منصوص عليها.', 'الرجبي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في ركلة الجزاء الركنية بهوكي الميدان وفق قواعد FIH، ما الحد الأقصى للاعبي الفريق المدافع الذين يجوز أن يقفوا خلف خط المرمى عند بدء التنفيذ، مع احتساب حارس المرمى إن وُجد؟', '["أربعة","ستة","جميع اللاعبين الأحد عشر","خمسة"]'::jsonb, 3, 45, 16, 'multi', 'يسمح بوجود خمسة مدافعين كحد أقصى، ومن بينهم حارس المرمى إن كان حاضرًا، خلف خط المرمى؛ ويقف بقية المدافعين خلف خط المنتصف.', 'هوكي الميدان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين MCC للكريكيت (إصدار 2022)، كم مهلة اللاعب القادم كي يكون جاهزًا لاستقبال الكرة أو ليكون شريكه جاهزًا بعد سقوط الويكيت، قبل إمكان إخراجه Timed out؟', '["ثلاث دقائق","دقيقة واحدة","دقيقتان","خمس دقائق"]'::jsonb, 0, 45, 17, 'multi', 'يحدد قانون MCC رقم 40 مهلة ثلاث دقائق. هذا السؤال يتعمد تحديد قوانين MCC؛ فقد تفرض شروط بعض البطولات الدولية مهلة أقصر.', 'الكريكيت');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قانون MCC للكريكيت 19.5، قفز مدافع من داخل الحد لصد كرة في الهواء، ثم هبط خارج الحد وهو لا يزال يلمس الكرة. ما الحكم؟', '["لا تُحتسب حدود لأن أول قفزة كانت من الداخل","كرة ميتة بلا نقاط","تُحتسب حدود لأن آخر تماس للمدافع مع الأرض قبل لمس الكرة لم يبقَ كله داخل الحد","يُترك القرار لقائد الفريق المدافع"]'::jsonb, 2, 50, 18, 'multi', 'لكي لا يُعد المدافع ملامسًا للحد، يجب أن يكون آخر تماس له مع الأرض قبل أول لمس للكرة داخل الحد، وألا يلامس الأرض خارجه وهو يلمس الكرة؛ الهبوط خارجًا مع استمرار اللمس يجعلها حدودًا.', 'الكريكيت');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في البيسبول وفق قواعد WBSC، متى يمكن إعلان الكرة الطائرة داخل الملعب Infield Fly؟', '["عند أقل من خروجين ووجود عدّائين على الأولى والثانية، أو امتلاء القواعد، مع كرة سهلة نسبيًا للاعب داخلي","عند وجود عدّاء على القاعدة الأولى فقط مهما كان عدد الخارجين","عند خروجين ووجود عدّاء على الثالثة","في أي كرة عالية داخل المنطقة الترابية"]'::jsonb, 0, 50, 19, 'multi', 'تتطلب القاعدة أقل من خروجين، وعدّائين على الأولى والثانية أو قواعد ممتلئة، وكرة طائرة صحيحة يمكن للاعب داخلي التقاطها بجهد عادي؛ والغرض منع إسقاط متعمد يخلق إخراجًا مزدوجًا سهلًا.', 'البيسبول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد الاتحاد العالمي للكيرلنغ، كم حجرًا في بداية كل شوط تشملها منطقة الحماية الحرة بحيث لا يجوز للفريق المنافس إخراج حجر الخصم منها من اللعب؟', '["أول ثلاثة أحجار","أول أربعة أحجار","أول خمسة أحجار","أول ستة أحجار"]'::jsonb, 2, 45, 20, 'multi', 'تسري قاعدة منطقة الحماية الحرة خلال الأحجار الخمسة الأولى من الشوط؛ لا يجوز إخراج حجر للخصم واقع في المنطقة الحرة من اللعب قبل رمي الحجر السادس.', 'الكيرلنغ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد الغولف المشتركة بين R&A وUSGA، حرّك اللاعب كرته عرضًا أثناء بحث معقول عنها في المنطقة العامة. ما الإجراء المعتاد؟', '["ضربة جزاء وتُلعب الكرة من مكانها الجديد","خسارة الحفرة تلقائيًا","لا جزاء وتبقى الكرة حيث توقفت","لا جزاء وتُعاد الكرة إلى موضعها الأصلي"]'::jsonb, 3, 45, 21, 'multi', 'لا عقوبة على التحريك العرضي أثناء محاولة معقولة للعثور على الكرة أو تحديدها، لكن يجب إعادة الكرة إلى موضعها الأصلي، ويُقدّر الموضع إن لم يكن معلومًا بدقة.', 'الغولف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قوانين IFAB 2025/2026، لمس الحكم الكرة داخل الملعب وبقيت لدى الفريق نفسه، لكن اللمسة بدأت هجمة واعدة. ما الاستئناف؟', '["يستمر اللعب لأن الاستحواذ لم يتغير","ركلة حرة غير مباشرة ضد آخر لاعب لمسها","كرة ساقطة للفريق الذي كان يملك أو كان سيملك الاستحواذ، في موضع اللمس وفق أحكام القانون","رمية تماس لأقرب فريق"]'::jsonb, 2, 50, 22, 'multi', 'يوقف الحكم اللعب إذا لامسته الكرة وبدأت هجمة واعدة، حتى لو لم يتغير الفريق المستحوذ. ويُستأنف بكرة ساقطة وفق القانون 8، مع القاعدة الخاصة للحارس إذا كان الموضع داخل منطقة الجزاء.', 'كرة القدم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'في كرة السلة وفق FIBA 2024، فريق يسيطر على الكرة في منطقته الخلفية وحصل على وقت مستقطع بعد مرور 5 ثوانٍ من مهلة الثماني ثواني. كم يتبقى له لعبور الكرة عند استئنافها من الخلف؟', '["8 ثوانٍ جديدة","5 ثوانٍ","3 ثوانٍ","تُلغى المهلة بعد الوقت المستقطع"]'::jsonb, 2, 50, 23, 'multi', 'الوقت المستقطع لا يعيد عدّ الثماني ثواني في هذا الاستئناف؛ إذا انقضت خمس ثوانٍ قبل التوقف، يبقى للفريق ثلاث ثوانٍ لنقل الكرة إلى منطقته الأمامية.', 'كرة السلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_55, 'وفق قواعد FIE، أي سلاح مبارزة يجعل كامل جسم الخصم، بما فيه اليدان والقدمان، هدفًا صالحًا للمسة؟', '["الشيش Foil","سيف المبارزة Épée","السيف العربي Sabre","الأسلحة الثلاثة جميعًا"]'::jsonb, 1, 40, 24, 'multi', 'في سيف المبارزة Épée يشمل الهدف كامل سطح جسم المبارز وملابسه ومعداته، بخلاف الشيش والسيف العربي اللذين يحددان مناطق هدف أضيق.', 'المبارزة');
  END IF;
END $$;



